window.GLOSSIKA_B2 = {"book":2,"lessons":[{"lesson":1,"range":[1,100],"items":[{"n":1,"zh":"你见过她的画吗？","en":"Have you seen any of her paintings?","it":"Hai visto qualcuno dei suoi quadri?","ipa":"ạj vịsto kwalkụno dẹj swɔ̣j kwạdri?"},{"n":2,"zh":"我上周见过她的一些作品。","en":"I saw some of her work last week.","it":"Ho visto qualche suo lavoro la settimana scorsa.","ipa":"ɔ vịsto kwạlke sụo lavọro la setːimạna skọrsa."},{"n":3,"zh":"布里吉特在工厂工作，但她做过很多不同的工作。","en":"Brigitte works in a factory, but she's had a lot of different jobs.","it":"Brigitta lavora in fabbrica, ma ha fatto molti lavori differenti.","ipa":"briʤịtːa lavọra in fạbːrika, m‿ a fạtːo mọlti lavọri difːerɛ̣nti."},{"n":4,"zh":"五年前她在一家餐厅做服务员。","en":"Five years ago she was a waitress in a restaurant.","it":"Cinque (5) anni fa, faceva la cameriera in un ristorante.","ipa":"ʧịŋkwe (5) ạnːi fa, faʧẹva la kamerjẹra in un ristorạnte."},{"n":5,"zh":"之后，她在农场工作过，但她并不太喜欢那份工作。","en":"After that, she worked on a farm, but she didn't enjoy it very much.","it":"In seguito, ha lavorato in una fattoria, ma non le è piaciuto molto.","ipa":"in sẹɡwito, a lavorạto in ụna fatːɔ̣rja, ma non l‿ ɛ̣ pjaʧụto mọlto."},{"n":6,"zh":"你认识建红姐姐吗？","en":"Do you know Jianhong's sister?","it":"Conosci la sorella di Jianhong?","ipa":"konọʃi la sorɛ̣lːa di (…)?"},{"n":7,"zh":"我见过她几次，但从未和她说过话。","en":"I've seen her a few times, but I've never spoken to her.","it":"L'ho vista qualche volta, però non le ho mai parlato.","ipa":"lɔ vịsta kwạlke vɔ̣lta, perɔ̣ non le ɔ mạj parlạto."},{"n":8,"zh":"你和她说过话吗？","en":"Have you ever spoken to her?","it":"Le hai mai parlato?","ipa":"le ạj mạj parlạto?"},{"n":9,"zh":"我上周在聚会上遇见了她，她人很好。","en":"I met her at a party last week. She's very nice.","it":"L'ho incontrata alla festa settimana scorsa. È molto carina.","ipa":"lɔ iŋkontrạt‿ ạlːa fɛ̣sta setːimạna skọrsa. ɛ̣ mọlto karịna."},{"n":10,"zh":"每天有人打扫办公室。","en":"Somebody cleans the office every day. > The office is cleaned every day.","it":"Ogni giorno, qualcuno pulisce l'ufficio. > L'ufficio è pulito ogni giorno.","ipa":"ɔ̣ɲːi ʤọrno, kwalkụno pulịʃe lufːịʧo. > lufːịʧo ɛ̣ pulịt‿ ɔ̣ɲːi ʤọrno."},{"n":11,"zh":"昨天有人打扫了办公室。","en":"Somebody cleaned the office yesterday. > The office was cleaned yesterday.","it":"Qualcuno ha pulito l'ufficio ieri. > Ieri, l'ufficio è stato pulito.","ipa":"kwalkụno a pulịto lufːịʧo jẹri. > jẹri, lufːịʧo ɛ̣ stạto pulịto."},{"n":12,"zh":"黄油是由牛奶制成的。","en":"Butter is made from milk.","it":"Il burro è ricavato dal latte.","ipa":"il bụrːo ɛ̣ rikavạto dal lạtːe."},{"n":13,"zh":"橙子进口到加拿大。","en":"Oranges are imported into Canada.","it":"Le arance sono importate in Canada.","ipa":"le arạɲʧe sọno importạte in kạnada."},{"n":14,"zh":"这些房间多久打扫一次？","en":"How often are these rooms cleaned?","it":"Quanto spesso vengono pulite queste camere?","ipa":"kwạnto spɛ̣sːo vẹŋɡono pulịte kwɛ̣ste kạmere?"},{"n":15,"zh":"我从没被邀请参加过聚会。","en":"I'm never invited to parties.","it":"Non sono mai invitato alle feste.","ipa":"non sọno mạj invitạto ạlːe fɛ̣ste."},{"n":16,"zh":"这座房子是一百年前建的。","en":"This house was built one hundred (100) years ago.","it":"Questa casa è stata costruita cent'anni fa.","ipa":"kwɛ̣sta kạza ɛ̣ stạta kostrwịta ʧentạnːi fa."},{"n":17,"zh":"这些房子是一百年前建的。","en":"These houses were built one hundred (100) years ago.","it":"Queste case sono state costruite cent'anni fa.","ipa":"kwɛ̣ste kạze sọno stạte kostrwịte ʧentạnːi fa."},{"n":18,"zh":"电话是什么时候发明的？","en":"When was the telephone invented?","it":"Quando è stato inventato il telefono?","ipa":"kwạndo ɛ̣ stạto inventạto il telɛ̣fono?"},{"n":19,"zh":"我们上周没有被邀请去参加聚会。","en":"We weren't invited to the party last week.","it":"La settimana scorsa, siamo stati invitati alla festa.","ipa":"la setːimạna skọrsa, sjạmo stạt‿ invitạti ạlːa fɛ̣sta."},{"n":20,"zh":"事故中有人受伤吗？","en":"Was anybody injured in the accident?","it":"Qualcuno è rimasto ferito nell'incidente?","ipa":"kwalkụno ɛ̣ rimạsto ferịto nɛlːiɲʧidɛ̣nte?"},{"n":21,"zh":"两个人被送进了医院。","en":"Two people were taken to the hospital.","it":"Due persone sono state portate all'ospedale.","ipa":"dụe persọne sọno stạte portạte alːospedạle."},{"n":22,"zh":"我1989年（1989）在哥伦比亚出生。","en":"I was born in Colombia in nineteen eighty-nine (1989).","it":"Sono nato in Colombia nel millenovecentottantanove (1989).","ipa":"sọno nạto in kolọmbja nɛl milːenoveʧentotːantanɔ̣ve ()."},{"n":23,"zh":"你在哪里出生的？——在台北。","en":"Where were you born? — In Taipei.","it":"Dove sei nato? — A Taipei.","ipa":"dọve sɛ̣j nạto? — a taipɛ̣j."},{"n":24,"zh":"电话是贝尔在1876年（1876）发明的。","en":"The telephone was invented by Bell in eighteen seventy-six (1876).","it":"Il telefono è stato inventato da Bell nel milleottocentosettantasei (1876).","ipa":"il telɛ̣fono ɛ̣ stạto inventạto da bɛlː nɛl milːeotːoʧentozetːantasẹj ()."},{"n":25,"zh":"几天前我被狗咬了。","en":"I was bitten by dog a few days ago.","it":"Due giorni fa, sono stato morso da un cane.","ipa":"dụe ʤọrni fa, sọno stạto mɔ̣rso da un kạne."},{"n":26,"zh":"你喜欢这些画吗？它们是我一个朋友的画。","en":"Do you like these paintings? They were painted by a friend of mine.","it":"Ti piacciono questi quadri? Sono stati dipinti da un mio amico.","ipa":"ti pjạtʧono kwɛ̣sti kwạdri? sọno stạti dipịnti da un mịo amịko."},{"n":27,"zh":"这些房间每天都打扫吗？","en":"Are these rooms cleaned every day?","it":"Queste camere vengono pulite ogni giorno?","ipa":"kwɛ̣ste kạmere vẹŋɡono pulịte ɔ̣ɲːi ʤọrno?"},{"n":28,"zh":"玻璃是由沙子制成的。","en":"Glass is made from sand.","it":"Il vetro è ricavato dalla sabbia.","ipa":"il vẹtro ɛ̣ rikavạto dạlːa sạbːja."},{"n":29,"zh":"邮票在邮局出售。","en":"Stamps are sold at the post office.","it":"I francobolli sono venduti in posta.","ipa":"i fraŋkobọlːi sọno vendụt‿ in pọsta."},{"n":30,"zh":"这个词不太常用。","en":"This word is not used very often.","it":"Questa parola non è usata molto spesso.","ipa":"kwɛ̣sta parɔ̣la non ɛ̣ uzạta mọlto spɛ̣sːo."},{"n":31,"zh":"我们可以在这里停车吗？","en":"Are we allowed to park here?","it":"Possiamo parcheggiare qui? > Abbiamo il permesso per parcheggiare qui?","ipa":"posːjạmo parkedʤạre kwị? > abːjạmo il permɛ̣sːo pɛr parkedʤạre kwị?"},{"n":32,"zh":"这个词怎么发音？","en":"How is this word pronounced?","it":"Come si pronuncia questa parola?","ipa":"kọme si pronụɲʧa kwɛ̣sta parɔ̣la?"},{"n":33,"zh":"这所房子上个月刷了油漆。","en":"The house was painted last month.","it":"La casa è stata pitturata il mese scorso.","ipa":"la kạza ɛ̣ stạta pitːurạta il mẹze skọrso."},{"n":34,"zh":"我的手机几天前被盗了。","en":"My phone was stolen a few days ago.","it":"Il mio telefono è stato rubato qualche giorno fa.","ipa":"il mịo telɛ̣fono ɛ̣ stạto rubạto kwạlke ʤọrno fa."},{"n":35,"zh":"事故中有三个人受伤。","en":"Three people were injured in the accident.","it":"Tre persone sono rimaste ferite durante l'incidente.","ipa":"trɛ persọne sọno rimạste ferịte durạnte liɲʧidɛ̣nte."},{"n":36,"zh":"这座桥是什么时候建造的？","en":"When was this bridge built?","it":"Quando è stato costruito questo ponte?","ipa":"kwạndo ɛ̣ stạto kostrwịto kwɛ̣sto pọnte?"},{"n":37,"zh":"噪声没有把我吵醒。","en":"I wasn't woken up by the noise.","it":"Non sono stato svegliato dal rumore.","ipa":"non sọno stạto sveʎːjạto dal rumọre."},{"n":38,"zh":"这些窗户是怎么打破的？","en":"How were these windows broken?","it":"Come sono state rotte queste finestre?","ipa":"kọme sọno stạte rọtːe kwɛ̣ste finɛ̣stre?"},{"n":39,"zh":"上周你被邀请去阿德里安的派对了吗？","en":"Were you invited to Adrian's party last week?","it":"Settimana scorsa, sei stato invitato alla festa di Adriano?","ipa":"setːimạna skọrsa, sɛ̣j stạto invitạto ạlːa fɛ̣sta di adrjạno?"},{"n":40,"zh":"足球在世界上大多数国家都踢。","en":"Football is played in most countries of the world.","it":"Il calcio è praticato nella maggior parte dei paesi del mondo.","ipa":"il kạlʧo ɛ̣ pratikạto nɛ̣lːa madʤọr pạrte dẹj paẹzi dɛl mọndo."},{"n":41,"zh":"为什么邮件发错了地址？","en":"Why did the email get sent to the wrong address?","it":"Perché la mail è stata inviata all'indirizzo sbagliato?","ipa":"perkɛ̣ la mạil ɛ̣ stạta invjạt‿ alːindirịʦːo zbaʎːjạto?"},{"n":42,"zh":"车库是修车的地方。","en":"A garage is a place where cars are repaired.","it":"L'autofficina è il luogo dove vengono riparate le macchine.","ipa":"lawtofːiʧịna ɛ̣ il lwɔ̣ɡo dọve vẹŋɡono riparạte le mạkːine."},{"n":43,"zh":"你在哪里出生的？","en":"Where were you born?","it":"Dove sei nato?","ipa":"dọve sɛ̣j nạto?"},{"n":44,"zh":"瑞士有多少种语言？","en":"How many languages are spoken in Switzerland?","it":"Quante lingue si parlano in Svizzera?","ipa":"kwạnte lịŋɡwe si pạrlano in svịʦːera?"},{"n":45,"zh":"有人闯进了我们的房子，但没东西被偷。","en":"Somebody broke into our house, but nothing was stolen.","it":"Qualcuno si è introdotto nella nostra casa, ma non è stato rubato niente.","ipa":"kwalkụno si ɛ̣ introdọtːo nɛ̣lːa nọstra kạza, ma non ɛ̣ stạto rubạto njɛ̣nte."},{"n":46,"zh":"自行车是什么时候发明的？","en":"When was the bicycle invented?","it":"Quando è stata inventata la bicicletta?","ipa":"kwạndo ɛ̣ stạta inventạta la biʧiklɛ̣tːa?"},{"n":47,"zh":"我昨天看到了一起事故。有两个人被送进了医院。","en":"I saw an accident yesterday. Two people were taken to the hospital.","it":"Ho visto un incidente ieri. Due persone sono state portate all'ospedale.","ipa":"ɔ vịsto un iɲʧidɛ̣nte jẹri. dụe persọne sọno stạte portạte alːospedạle."},{"n":48,"zh":"纸是由木头做的。","en":"Paper is made from wood.","it":"La carta viene ricavata dal legno.","ipa":"la kạrta vjẹne rikavạta dal lẹɲːo."},{"n":49,"zh":"上周酒店发生了火灾。有两个房间被损坏了。","en":"There was a fire at the hotel last week. Two of the rooms were damaged.","it":"C'è stato un incendio all'albergo la settimana scorsa. Due [delle] camere sono state danneggiate.","ipa":"ʧɛ̣ stạto un iɲʧɛ̣ndjo alːalbɛ̣rɡo la setːimạna skọrsa. dụe [dɛ̣lːe] kạmere sọno stạte danːedʤạte."},{"n":50,"zh":"你从哪里得到这张照片的？——是我的一个朋友给我的。","en":"Where did you get this picture? — It was given to me by a friend of mine.","it":"Dove hai preso questa foto? — Me l'ha data un amico.","ipa":"dọve ạj prẹzo kwɛ̣sta fọto? — mɛ la dạta un amịko."},{"n":51,"zh":"许多英国节目在美国电视上播出。","en":"Many British programs are shown on American television.","it":"Molti programmi inglesi sono trasmessi dalla televisione americana.","ipa":"mọlti proɡrạmː‿ inɡlẹzi sọno trasmɛ̣sːi dạlːa televizjọne amerikạna."},{"n":52,"zh":"阿列克谢和阿纳斯塔西娅去婚礼了吗？——没有，他们没被邀请。","en":"Did Aleksey and Anastasia go to the wedding? — No, they weren't invited.","it":"Aleksey e Anastasia sono andati al matrimonio? — No, non erano invitati.","ipa":"(…) e anastạzja sọno andạti al matrimɔ̣njo? — nɔ, non ẹrano invitạti."},{"n":53,"zh":"这部电影有多老了？——它是1965年制作的。","en":"How old is this movie? — It was made in nineteen sixty-five (1965).","it":"Quanti anni ha questo film? — È stato girato nel millenovecentosessantacinque (1965).","ipa":"kwạnti ạnːi a kwɛ̣sto film? — ɛ̣ stạto ʤirạto nɛl milːenoveʧentozesːantaʧịŋkwe ()."},{"n":54,"zh":"我的车上周被偷了，但第二天警察找到了它。","en":"My car was stolen last week, but the next day it was found by the police.","it":"La mia macchina è stata rubata settimana scorsa, ma il giorno seguente è stata ritrovata dalla polizia.","ipa":"la mịa mạkːina ɛ̣ stạta rubạta setːimạna skọrsa, ma il ʤọrno seɡwɛ̣nt‿ ɛ̣ stạta ritrovạta dạlːa poliʦịa."},{"n":55,"zh":"阿图罗出生在哈瓦那。","en":"Arturo was born in Havana.","it":"Arturo è nato all'Havana.","ipa":"artụro ɛ̣ nạto alːavạna."},{"n":56,"zh":"安娜出生在罗马。","en":"Anna was born in Rome.","it":"Anna è nata a Roma.","ipa":"ạnːa ɛ̣ nạt‿ a rọma."},{"n":57,"zh":"她的父母出生在里约热内卢。","en":"Her parents were born in Rio de Janeiro.","it":"I suoi genitori sono nati a Rio de Janeiro.","ipa":"i swɔ̣j ʤenitọri sọno nạti a (…) (…) (…)."},{"n":58,"zh":"我出生在伦敦。","en":"I was born in London.","it":"Io sono nato a Londra.","ipa":"ịo sọno nạto a lọndra."},{"n":59,"zh":"我妈妈出生在巴黎。","en":"My mother was born in Paris.","it":"Mia mamma è nata a Parigi.","ipa":"mịa mạmːa ɛ̣ nạt‿ a parịʤi."},{"n":60,"zh":"有人在刷门。门正在被刷。","en":"Somebody is painting the door. The door is being painted.","it":"Qualcuno sta pitturando la porta. La porta viene verniciata.","ipa":"kwalkụno sta pitːurạndo la pɔ̣rta. la pɔ̣rta vjẹne verniʧạta."},{"n":61,"zh":"我的汽车在修理厂，正在修。","en":"My car is at the garage. It's being repaired.","it":"La mia macchina è in officina. È in riparazione.","ipa":"la mịa mạkːina ɛ̣ in ofːiʧịna. ɛ̣ in riparaʦjọne."},{"n":62,"zh":"公园对面正在建一些新房子。","en":"Some new houses are being built across from the park.","it":"Di fronte al parco, stanno costruendo alcune case nuove.","ipa":"di frọnte al pạrko, stạnːo kostrwɛ̣ndo alkụne kạze nwɔ̣ve."},{"n":63,"zh":"办公室现在正在打扫。","en":"The office is being cleaned right now.","it":"Si sta pulendo l'ufficio in questo momento.","ipa":"si sta pulɛ̣ndo lufːịʧo in kwɛ̣sto momɛ̣nto."},{"n":64,"zh":"办公室每天都打扫。","en":"The office is cleaned every day.","it":"L'ufficio viene pulito tutti i giorni.","ipa":"lufːịʧo vjẹne pulịto tụtː‿ i ʤọrni."},{"n":65,"zh":"在美国，足球比赛通常在周末进行，但下个周末没有大型比赛。","en":"In the United States, football games are usually played on the weekends, but no big games are being played next weekend.","it":"Negli Stati Uniti, le partite di calcio sono giocate, solitamente, nei fine settimana, ma non si giocheranno partite importanti nel prossimo weekend.","ipa":"nɛ̣ʎːi stạti unịti, le partịte di kạlʧo sọno ʤokạte, solitamɛ̣nte, nɛ̣j fịne setːimạna, ma non si ʤokerạnːo partịte importạnti nɛl prɔ̣sːimo (…)."},{"n":66,"zh":"有人把门漆了。> 门已经被漆了。","en":"Somebody has painted the door. > The door has been painted.","it":"Qualcuno ha pitturato la porta. > La porta è stata pitturata.","ipa":"kwalkụno a pitːurạto la pɔ̣rta. la pɔ̣rta ɛ̣ stạta pitːurạta."},{"n":67,"zh":"有人偷了我的钥匙。> 我的钥匙被偷了。","en":"Somebody has stolen my key. > My key has been stolen.","it":"Qualcuno ha rubato la mia chiave. > La mia chiave è stata rubata.","ipa":"kwalkụno a rubạto la mịa kjạve. la mịa kjạv‿ ɛ̣ stạta rubạta."},{"n":68,"zh":"有人偷了我的钥匙。> 我的钥匙被偷了。","en":"Somebody has stolen my keys. > My keys have been stolen.","it":"Qualcuno ha rubato le mie chiavi. > Le mie chiavi sono state rubate.","ipa":"kwalkụno a rubạto le mịe kjạvi. le mịe kjạvi sọno stạte rubạte."},{"n":69,"zh":"没有人邀请我参加派对。> 我没有被邀请参加派对。","en":"Nobody has invited me to the party. > I haven't been invited to the party.","it":"Nessuno mi ha invitato alla festa. > Non sono stato (♀stata) invitato (♀invitata) alla festa.","ipa":"nesːụno mi a invitạto ạlːa fɛ̣sta. non sọno stạto (♀stạta) invitạto (♀invitạta) ạlːa fɛ̣sta."},{"n":70,"zh":"这件衬衫有人洗了吗？> 这件衬衫洗了吗？","en":"Has somebody washed this shirt? > Has this shirt been washed?","it":"Qualcuno ha lavato questa maglietta? > Questa maglietta è stata lavata?","ipa":"kwalkụno a lavạto kwɛ̣sta maʎːjɛ̣tːa? kwɛ̣sta maʎːjɛ̣tːa ɛ̣ stạta lavạta?"},{"n":71,"zh":"房间不再脏了。已经打扫过了。","en":"The room isn't dirty anymore. It's been cleaned.","it":"La camera non è più sporca. È stata pulita.","ipa":"la kạmera non ɛ̣ piụ spọrka. ɛ̣ stạta pulịta."},{"n":72,"zh":"房间昨天打扫了。","en":"The room was cleaned yesterday.","it":"La camera è stata pulita ieri.","ipa":"la kạmera ɛ̣ stạta pulịta jẹri."},{"n":73,"zh":"我找不到我的钥匙了。我觉得它们被偷了。","en":"I can't find my keys. I think they've been stolen.","it":"Non riesco a trovare le chiavi. Penso [che] siano state rubate.","ipa":"non rjẹsko a trovạre le kjạvi. pẹnso [ke] sịano stạte rubạte."},{"n":74,"zh":"我的钥匙上周被偷了。","en":"My keys were stolen last week.","it":"Le mie chiavi sono state rubate la settimana scorsa.","ipa":"le mịe kjạvi sọno stạte rubạte la setːimạna skọrsa."},{"n":75,"zh":"汽车正在修理。> 汽车正在被修理。","en":"The car's being repaired. > The car's getting repaired.","it":"La macchina è a riparare. > La macchina viene riparata.","ipa":"la mạkːina ɛ̣ a riparạre. la mạkːina vjẹne riparạta."},{"n":76,"zh":"一座桥正在建造。> 一座桥正在被建造。","en":"A bridge is being built. > A bridge is getting built.","it":"Un ponte è in costruzione. > Viene costruito un ponte.","ipa":"un pọnt‿ ɛ̣ in kostruʦjọne. vjẹne kostrwịto un pọnte."},{"n":77,"zh":"窗户正在被清洗。> 窗户正在被清洗。","en":"The windows are being washed. > The windows are getting washed.","it":"Stanno lavando le finestre. > Le finestre vengono lavate.","ipa":"stạnːo lavạndo le finɛ̣stre. le finɛ̣stre vẹŋɡono lavạte."},{"n":78,"zh":"草正在被割。> 草正在被割。","en":"The grass is being cut. > The grass is getting cut.","it":"Si sta tagliando l'erba. > Viene tagliata l'erba.","ipa":"si sta taʎːjạndo lɛ̣rba. vjẹne taʎːjạta lɛ̣rba."},{"n":79,"zh":"办公室正在被打扫。> 办公室正在被打扫。","en":"The office is being cleaned. > The office is getting cleaned.","it":"Stanno lavando l'ufficio. > L'ufficio viene lavato.","ipa":"stạnːo lavạndo lufːịʧo. lufːịʧo vjẹne lavạto."},{"n":80,"zh":"衬衫已经熨过了。> 衬衫被熨过了。","en":"The shirts have been ironed. > The shirts got ironed.","it":"Le magliette sono state stirate.","ipa":"le maʎːjɛ̣tːe sọno stạte stirạte."},{"n":81,"zh":"窗户破了。","en":"The window's been broken. > The window got broken.","it":"La finestra è stata rotta. > La finestra si è rotta.","ipa":"la finɛ̣stra ɛ̣ stạta rọtːa. la finɛ̣stra si ɛ̣ rọtːa."},{"n":82,"zh":"屋顶正在修。","en":"The roof is being repaired. > The roof is getting repaired.","it":"Il tetto è in riparazione. > Il tetto viene riparato.","ipa":"il tɛ̣tːo ɛ̣ in riparaʦjọne. il tɛ̣tːo vjẹne riparạto."},{"n":83,"zh":"车子损坏了。","en":"The car's been damaged. > The car got damaged.","it":"La macchina è stata danneggiata. > La macchina ha riportato dei danni.","ipa":"la mạkːina ɛ̣ stạta danːedʤạta. la mạkːin‿ a riportạto dẹj dạnːi."},{"n":84,"zh":"房子正在被拆。","en":"The houses are being torn down. > The houses are getting torn down.","it":"Le case vengono demolite.","ipa":"le kạze vẹŋɡono demolịte."},{"n":85,"zh":"树被砍倒了。","en":"The trees have been cut down. > The trees got cut down.","it":"Gli alberi sono stati tagliati.","ipa":"ʎːi ạlberi sọno stạti taʎːjạti."},{"n":86,"zh":"他们被邀请去参加派对。","en":"They've been invited to a party. > They got invited to a party.","it":"Sono stati invitati alla festa.","ipa":"sọno stạt‿ invitạti ạlːa fɛ̣sta."},{"n":87,"zh":"我现在不能用办公室，它在刷漆。","en":"I can't use my office right now. It's being painted.","it":"Non posso usare il mio ufficio in questo momento. Lo si sta pitturando.","ipa":"non pɔ̣sːo uzạre il mịo ufːịʧo in kwɛ̣sto momɛ̣nto. lo si sta pitːurạndo."},{"n":88,"zh":"我们没去派对，没被邀请。","en":"We didn't go to the party. We weren't invited.","it":"Non siamo andati alla festa. Non eravamo invitati.","ipa":"non sjạmo andạti ạlːa fɛ̣sta. non eravạmo invitạti."},{"n":89,"zh":"洗衣机坏了，现在修好了。","en":"The washing machine was broken. It's been repaired now.","it":"La lavatrice era rotta. È stata riparata adesso.","ipa":"la lavatrịʧ‿ ẹra rọtːa. ɛ̣ stạta riparạt‿ adɛ̣sːo."},{"n":90,"zh":"洗衣机昨天下午正在修。","en":"The washing machine was getting repaired yesterday afternoon.","it":"Ieri pomeriggio, la lavatrice era in riparazione.","ipa":"jẹri pomerịdʤo, la lavatrịʧ‿ ẹra in riparaʦjọne."},{"n":91,"zh":"工厂是制造东西的地方。","en":"A factory is a place where things are made.","it":"Una fabbrica è un luogo dove si producono le cose.","ipa":"ụna fạbːrika ɛ̣ un lwɔ̣ɡo dọve si prodụkono le kɔ̣ze."},{"n":92,"zh":"这些房子多大了？什么时候建的？","en":"How old are these houses? When were they built?","it":"Quanti anni hanno queste case? Quando sono state costruite?","ipa":"kwạnti ạnːi ạnːo kwɛ̣ste kạze? kwạndo sọno stạte kostrwịte?"},{"n":93,"zh":"现在电脑在用吗？——是的，博里斯在用。","en":"Is the computer being used at the moment? — Yes, Boris is using it.","it":"Il computer è utilizzato in questo momento? — Sì. Boris lo sta usando.","ipa":"il kompjụter ɛ̣ utiliʦːạto in kwɛ̣sto momɛ̣nto? sị. (…) lo sta uzạndo."},{"n":94,"zh":"我以前从没见过这些花，它们叫什么？","en":"I've never seen these flowers before. What are they called?","it":"Non ho mai visto questi fiori prima d'ora. Come si chiamano?","ipa":"non ɔ mạj vịsto kwɛ̣sti fjọri prịma dọra. kọme si kjạmano?"},{"n":95,"zh":"我的太阳镜昨天在海滩上被偷了。","en":"My sunglasses were stolen at the beach yesterday.","it":"I miei occhiali da sole sono stati rubati ieri in spiaggia.","ipa":"i mjɛ̣j okːjạli da sọle sọno stạti rubạti jẹri in spjạdʤa."},{"n":96,"zh":"桥被封闭了，上周坏了，还没修。","en":"The bridge is closed. It got damaged last week, and it hasn't been repaired yet.","it":"Il ponte è chiuso. È stato danneggiato la settimana scorsa e non è ancora stato riparato.","ipa":"il pọnt‿ ɛ̣ kiụzo. ɛ̣ stạto danːedʤạto la setːimạna skọrsa e non ɛ̣ aŋkọra stạto riparạto."},{"n":97,"zh":"还没修好。","en":"It hasn't gotten repaired yet.","it":"Non è ancora stato riparato.","ipa":"non ɛ̣ aŋkọra stạto riparạto."},{"n":98,"zh":"请安静点，我在工作。","en":"Please be quiet. I'm working.","it":"Fai silenzio per favore. Sto lavorando.","ipa":"fạj silɛ̣nʦjo pɛr favọre. stɔ lavorạndo."},{"n":99,"zh":"现在下不了雨。","en":"It isn't raining right now.","it":"Adesso, non sta piovendo.","ipa":"adɛ̣sːo, non sta pjovɛ̣ndo."},{"n":100,"zh":"你今晚做什么？","en":"What are you doing tonight?","it":"Che cosa fai stasera?","ipa":"ke kɔ̣za fạj stasẹra?"}]},{"lesson":2,"range":[101,200],"items":[{"n":101,"zh":"她来的时候我正在工作。","en":"I was working when she arrived.","it":"Stavo lavorando, quando è arrivata.","ipa":"stạvo lavorạndo, kwạndo ɛ̣ arːivạta."},{"n":102,"zh":"没下雨，所以我们不需要伞。","en":"It wasn't raining, so we didn't need an umbrella.","it":"Non stava piovendo, per cui non avevamo bisogno dell'ombrello.","ipa":"non stạva pjovɛ̣ndo, pɛr kwị non avevạmo bizọɲːo dɛlːombrɛ̣lːo."},{"n":103,"zh":"你三点的时候在做什么？","en":"What were you doing at three o'clock (3:00)?","it":"Che cosa stavi facendo alle tre (3:00) in punto?","ipa":"ke kɔ̣za stạvi faʧɛ̣ndo ạlːe trɛ (3:00) in pụnto?"},{"n":104,"zh":"这些办公室不是每天都打扫。","en":"These offices aren't cleaned every day.","it":"Questi uffici non vengono puliti tutti i giorni.","ipa":"kwɛ̣sti ufːịʧi non vẹŋɡono pulịti tụtː‿ i ʤọrni."},{"n":105,"zh":"办公室昨天被打扫了。昨天办公室被清洁了。","en":"The office was cleaned yesterday. The office got cleaned yesterday.","it":"L'ufficio è stato pulito ieri.","ipa":"lufːịʧo ɛ̣ stạto pulịto jẹri."},{"n":106,"zh":"窗户是怎么破的？窗户是怎么弄破的？","en":"How was the window broken? How did the window get broken?","it":"Com'è stata rotta la finestra? Come si è rotta la finestra?","ipa":"komɛ̣ stạta rọtːa la finɛ̣stra? kọme si ɛ̣ rọtːa la finɛ̣stra?"},{"n":107,"zh":"我住在这栋房子里已经十年了。","en":"I've lived in this house for ten (10) years.","it":"Vivo in questa casa da dieci (10) anni.","ipa":"vịvo in kwɛ̣sta kạza da djẹʧi (10) ạnːi."},{"n":108,"zh":"Dietrich 从来没骑过马。","en":"Dietrich has never ridden a horse.","it":"Dietrich non ha mai cavalcato un cavallo.","ipa":"(…) non a mạj kavalkạto un kavạlːo."},{"n":109,"zh":"Filippa 从没去过南美洲。","en":"Filippa hasn't been to South America.","it":"Filippa non è stata in Sud America.","ipa":"filịpːa non ɛ̣ stạta in sud amẹrika."},{"n":110,"zh":"Daisuke 和 Aiko 去哪儿了？","en":"Where have Daisuke and Aiko gone?","it":"Dove sono andati Daisuke e Aiko?","ipa":"dọve sọno andạti (…) e (…)?"},{"n":111,"zh":"我喜欢咖啡，但不喜欢茶。","en":"I like coffee, but I don't like tea.","it":"Mi piace il caffè, ma non mi piace il tè.","ipa":"mi pjạʧe il kafːɛ̣, ma non mi pjạʧe il tɛ̣."},{"n":112,"zh":"Gabriele 很少出门。","en":"Gabriele doesn't go out very often.","it":"Gabriele non esce molto spesso.","ipa":"ɡabrjẹle non ẹʃe mọlto spɛ̣sːo."},{"n":113,"zh":"你周末通常做什么？","en":"What do you usually do on weekends?","it":"Cosa fai solitamente nei fine settimana?","ipa":"kɔ̣za fạj solitamɛ̣nte nɛ̣j fịne setːimạna?"},{"n":114,"zh":"Fyodor 是一个人住吗？","en":"Does Fyodor live alone?","it":"Fyodor vive da solo?","ipa":"fjọdor vịve da sọlo?"},{"n":115,"zh":"我昨天没看电视。","en":"I didn't watch TV yesterday.","it":"Non ho guardato la tivù ieri.","ipa":"non ɔ ɡwardạto la tivụ jẹri."},{"n":116,"zh":"上周没下雨。","en":"It didn't rain last week.","it":"Non è piovuto settimana scorsa.","ipa":"non ɛ̣ pjovụto setːimạna skọrsa."},{"n":117,"zh":"Fabio 和 Donatella 什么时候出去的？","en":"What time did Fabio and Donatella go out?","it":"A che ora Fabio e Donatella sono usciti?","ipa":"a ke ọra fạbjo e donatɛ̣lːa sọno uʃịti?"},{"n":118,"zh":"你晚上工作吗？","en":"Do you work at night?","it":"Lavori di notte?","ipa":"lavọri di nɔ̣tːe?"},{"n":119,"zh":"他们要去哪儿？","en":"Where are they going?","it":"Dove stanno andando?","ipa":"dọve stạnːo andạndo?"},{"n":120,"zh":"你为什么看着我？","en":"Why are you looking at me?","it":"Perchè mi stai guardando?","ipa":"perkɛ̣ mi stạj ɡwardạndo?"},{"n":121,"zh":"薛妮亚住在你附近吗？","en":"Does Xenia live near you?","it":"Xenia vive vicino a te?","ipa":"(…) vịve viʧịno a tɛ?"},{"n":122,"zh":"你喜欢做饭吗？","en":"Do you like to cook?","it":"Ti piace cucinare?","ipa":"ti pjạʧe kuʧinạre?"},{"n":123,"zh":"太阳在照耀吗？","en":"Is the sun shining?","it":"C'è il sole?","ipa":"ʧɛ̣ il sọle?"},{"n":124,"zh":"商店几点关门？","en":"What time do the stores close?","it":"A che ora chiudono i negozi?","ipa":"a ke ọra kiụdono i neɡɔ̣ʦi?"},{"n":125,"zh":"弗兰茨今天上班吗？","en":"Is Franz working today?","it":"Franz lavora oggi?","ipa":"(…) lavọra ɔ̣dʤi?"},{"n":126,"zh":"这个词是什么意思？","en":"What does this word mean?","it":"Cosa significa questa parola?","ipa":"kɔ̣za siɲːịfika kwɛ̣sta parɔ̣la?"},{"n":127,"zh":"你感觉好吗？","en":"Are you feeling all right?","it":"Ti senti bene?","ipa":"ti sɛ̣nti bẹne?"},{"n":128,"zh":"海蒂晚上不工作。","en":"Heidi doesn't work at night.","it":"Heidi non lavora di notte.","ipa":"ẹidi non lavọra di nɔ̣tːe."},{"n":129,"zh":"我很累，今晚不想出去。","en":"I'm very tired. I don't want to go out tonight.","it":"Sono molto stanco (♀stanca). Non voglio uscire stasera.","ipa":"sọno mọlto stạŋko (♀stạŋka). non vɔ̣ʎːjo uʃịre stasẹra."},{"n":130,"zh":"我很累，今晚不出去。","en":"I'm very tired. I'm not going out tonight.","it":"Sono molto stanco (♀stanca). Stasera, non uscirò.","ipa":"sọno mọlto stạŋko (♀stạŋka). stasẹra, non uʃirɔ̣."},{"n":131,"zh":"高桥拓郎这周不上班，他在度假。","en":"Takahiro's not working this week. He's on vacation.","it":"Takahiro non lavora questa settimana. È in ferie.","ipa":"takaịro non lavọra kwɛ̣sta setːimạna. ɛ̣ in fẹrje."},{"n":132,"zh":"我父母通常在家，他们很少出去。","en":"My parents are usually at home. They don't go out very often.","it":"I miei genitori di solito sono a casa. Non escono molto spesso.","ipa":"i mjɛ̣j ʤenitọri di sɔ̣lito sọno a kạza. non ẹskono mọlto spɛ̣sːo."},{"n":133,"zh":"美津子去过很多地方，但她不会说任何外语。","en":"Mitsuko has traveled a lot, but she doesn't speak any foreign languages.","it":"Mitsuko ha viaggiato molto, però non parla nessuna lingua straniera.","ipa":"(…) a vjadʤạto mọlto, perɔ̣ non pạrla nesːụna lịŋɡwa stranjẹra."},{"n":134,"zh":"你可以把电视关了，我不看了。","en":"You can turn off the television. I'm not watching it.","it":"Puoi spegnere la televisione, non la sto guardando.","ipa":"pwɔ̣j spẹɲːere la televizjọne, non la stɔ ɡwardạndo."},{"n":135,"zh":"弗洛拉邀请我们参加她下周的派对，但我们不去。","en":"Flora has invited us to her party next week, but we're not going.","it":"Flora ci ha invitato alla sua festa la settimana prossima, ma non ci andremo.","ipa":"flọra ʧi a invitạto ạlːa sụa fɛ̣sta la setːimạna prɔ̣sːima, ma non ʧi andrẹmo."},{"n":136,"zh":"你的鞋子是在哪里制造的？","en":"Where were your shoes made?","it":"Dove sono state prodotte le tue scarpe?","ipa":"dọve sọno stạte prodọtːe le tụe skạrpe?"},{"n":137,"zh":"你昨晚出去了吗？","en":"Did you go out last night?","it":"Sei uscito ieri sera?","ipa":"sɛ̣j uʃịto jẹri sẹra?"},{"n":138,"zh":"你十点半在做什么？","en":"What were you doing at ten thirty (10:30)?","it":"Cosa stavi facendo alle dieci e mezza (10:30)?","ipa":"kɔ̣za stạvi faʧɛ̣ndo ạlːe djẹʧi e mɛ̣ʣa (10:30)?"},{"n":139,"zh":"你妈妈是在哪里出生的？","en":"Where was your mother born?","it":"Dov'è nata tua mamma?","ipa":"dovɛ̣ nạta tụa mạmːa?"},{"n":140,"zh":"马可回家了吗？","en":"Has Marco gone home?","it":"Marco è andato a casa?","ipa":"mạrko ɛ̣ andạto a kạza?"},{"n":141,"zh":"他什么时候走的？","en":"What time did he go?","it":"A che ora è andato?","ipa":"a ke ọra ɛ̣ andạto?"},{"n":142,"zh":"这些房子是什么时候建的？","en":"When were these houses built?","it":"Quando sono state costruite queste case?","ipa":"kwạndo sọno stạte kostrwịte kwɛ̣ste kạze?"},{"n":143,"zh":"康斯坦丁到了吗？","en":"Has Konstantin arrived yet?","it":"Costantino è già arrivato?","ipa":"kostantịno ɛ̣ ʤạ arːivạto?"},{"n":144,"zh":"你为什么早点回家？","en":"Why did you go home early?","it":"Perchè sei andato a casa presto?","ipa":"perkɛ̣ sɛ̣j andạto a kạza prɛ̣sto?"},{"n":145,"zh":"他们结婚多久了？","en":"How long have they been married?","it":"Da quanto tempo sono sposati?","ipa":"da kwạnto tẹmpo sọno spozạti?"},{"n":146,"zh":"米莱娜丢了护照。","en":"Milena's lost her passport.","it":"Milena ha perso il [suo] passaporto.","ipa":"milẹn‿ a pɛ̣rso il [sụo] pasːapọrto."},{"n":147,"zh":"这座桥是十年前建的。","en":"This bridge was built ten (10) years ago.","it":"Questo ponte è stato costruito dieci (10) anni fa.","ipa":"kwɛ̣sto pọnt‿ ɛ̣ stạto kostrwịto djẹʧi (10) ạnːi fa."},{"n":148,"zh":"你工作做完了吗？","en":"Have you finished your work yet?","it":"Hai già finito il tuo lavoro?","ipa":"ạj ʤạ finịto il tụo lavọro?"},{"n":149,"zh":"这个镇子总是很干净。街道每天都打扫。","en":"This town is always clean. The streets get cleaned every day.","it":"Questa città è sempre pulita. Le strade vengono pulite ogni giorno.","ipa":"kwɛ̣sta ʧitːạ ɛ̣ sẹmpre pulịta. le strạde vẹŋɡono pulịte ɔ̣ɲːi ʤọrno."},{"n":150,"zh":"我刚泡了些咖啡。要来点吗？","en":"I've just made some coffee. Would you like some?","it":"Ho appena fatto il caffè. Ne vuoi un po'?","ipa":"ɔ apːẹna fạtːo il kafːɛ̣. ne vwɔ̣j un pɔ?"},{"n":151,"zh":"这张照片很老了。是好久以前拍的。","en":"This is a very old photograph. It was taken a long time ago.","it":"Questa è una foto molto vecchia. È stata scattata tanto tempo fa.","ipa":"kwɛ̣sta ɛ̣ ụna fọto mọlto vɛ̣kːja. ɛ̣ stạta skatːạta tạnto tẹmpo fa."},{"n":152,"zh":"保罗买了一辆新车。","en":"Paolo's bought a new car.","it":"Paolo ha comprato una macchina nuova.","ipa":"pạolo a komprạto ụna mạkːina nwɔ̣va."},{"n":153,"zh":"我要带把伞。下雨了。","en":"I'm going to take an umbrella with me. It's raining.","it":"Prenderò un ombrello con me. Sta piovendo.","ipa":"prenderɔ̣ un ombrɛ̣lːo kon mɛ. sta pjovɛ̣ndo."},{"n":154,"zh":"你怎么这么累？你昨晚睡得晚吗？","en":"Why are you so tired? Did you go to bed late last night?","it":"Perchè sei così stanco? Sei andato a letto tardi ieri notte?","ipa":"perkɛ̣ sɛ̣j kozị stạŋko? sɛ̣j andạto a lɛ̣tːo tạrdi jẹri nɔ̣tːe?"},{"n":155,"zh":"巧克力在哪里？你都吃完了？","en":"Where are the chocolates? Have you eaten all of them?","it":"Dove sono i cioccolatini? Li hai mangiati tutti quanti?","ipa":"dọve sọno i ʧokːolatịni? li ạj maɲʤạti tụtːi kwạnti?"},{"n":156,"zh":"你新工作怎么样？你喜欢吗？","en":"How is your new job? Are you enjoying it?","it":"Com'è il tuo nuovo lavoro? Ti sta piacendo?","ipa":"komɛ̣ il tụo nwɔ̣vo lavọro? ti sta pjaʧɛ̣ndo?"},{"n":157,"zh":"我的汽车在事故中严重损坏了，但我没事。","en":"My car was badly damaged in the accident, but I was okay.","it":"La mia macchina è stata gravemente danneggiata durante l'incidente, ma io stavo bene.","ipa":"la mịa mạkːina ɛ̣ stạta ɡravemɛ̣nte danːedʤạta durạnte liɲʧidɛ̣nte, ma ịo stạvo bẹne."},{"n":158,"zh":"吉乌莉亚有辆车，但她不太常开。","en":"Giuliana has a car, but she doesn't drive it very often.","it":"Guiliana ha un'automobile, ma non guida molto spesso.","ipa":"ɡwiljạn‿ a unawtomọbile, ma non ɡwịda mọlto spɛ̣sːo."},{"n":159,"zh":"卡兹米不在家。她出去几天了。","en":"Kasumi isn't at home. She's gone away for a few days.","it":"Kasumi non è a casa. È andata via per qualche giorno.","ipa":"kazụmi non ɛ̣ a kạza. ɛ̣ andạta vịa pɛr kwạlke ʤọrno."},{"n":160,"zh":"我不懂这个问题。你能再解释一遍吗？","en":"I don't understand the problem. Can you explain it again?","it":"Non capisco il problema. Puoi spiegarmelo di nuovo?","ipa":"non kapịsko il problẹma. pwɔ̣j spjeɡạrmelo di nwɔ̣vo?"},{"n":161,"zh":"桥本在他房间里，他在听音乐。","en":"Kenichi's in his room. He's listening to music.","it":"Kenichi è in camera sua. Sta ascoltando la musica.","ipa":"(…) ɛ̣ in kạmera sụa. st‿ askoltạndo la mụzika."},{"n":162,"zh":"我不知道这个词怎么读。","en":"I don't know how to say this word. How is it pronounced?","it":"Non so come dire questa parola. Come si pronuncia?","ipa":"non sɔ kọme dịre kwɛ̣sta parɔ̣la. kọme si pronụɲʧa?"},{"n":163,"zh":"这窗户怎么开？你能给我演示一下吗？","en":"How do you open this window? Can you show me?","it":"Come si apre questa finestra? Puoi mostrarmelo?","ipa":"kọme si ạpre kwɛ̣sta finɛ̣stra? pwɔ̣j mostrạrmelo?"},{"n":164,"zh":"我昨天打扫了我的房间。","en":"I cleaned my room yesterday.","it":"Ieri, ho pulito la mia camera.","ipa":"jẹri, ɔ pulịto la mịa kạmera."},{"n":165,"zh":"Henrik在大学学的是工程。","en":"Henrik studied engineering in college.","it":"Enrico ha studiato ingegneria all'università.","ipa":"enrịko a studjạto iɲʤeɲːerịa alːuniversitạ."},{"n":166,"zh":"我已经打扫了我的房间。","en":"I've cleaned my room.","it":"Ho pulito la mia camera.","ipa":"ɔ pulịto la mịa kạmera."},{"n":167,"zh":"Magda在迈阿密住了十三年了。","en":"Magda has lived in Miami for thirteen (13) years.","it":"Magda vive a Miami da tredici (13) anni.","ipa":"mạɡda vịve a mjạmi da trẹdiʧi (13) ạnːi."},{"n":168,"zh":"这些房间每天都打扫。这些房间每天都会被打扫。","en":"These rooms are cleaned every day. These rooms get cleaned every day.","it":"Queste camere sono pulite tutti i giorni.","ipa":"kwɛ̣ste kạmere sọno pulịte tụtː‿ i ʤọrni."},{"n":169,"zh":"我的汽车已经修好了。","en":"My car has been repaired.","it":"La mia macchina è stata riparata.","ipa":"la mịa mạkːina ɛ̣ stạta riparạta."},{"n":170,"zh":"我昨天做了个蛋糕。","en":"I made a cake yesterday.","it":"Ho fatto una torta ieri.","ipa":"ɔ fạtːo ụna tɔ̣rta jẹri."},{"n":171,"zh":"我泡了些咖啡。","en":"I've made some coffee.","it":"Ho fatto del caffè.","ipa":"ɔ fạtːo dɛl kafːɛ̣."},{"n":172,"zh":"昨晚有人打破了这窗户。","en":"Somebody broke this window last night.","it":"Qualcuno ha rotto questa finestra ieri notte.","ipa":"kwalkụno a rọtːo kwɛ̣sta finɛ̣stra jẹri nɔ̣tːe."},{"n":173,"zh":"有人打破了这窗户。","en":"Somebody's broken this window.","it":"Qualcuno ha rotto questa finestra.","ipa":"kwalkụno a rọtːo kwɛ̣sta finɛ̣stra."},{"n":174,"zh":"这窗户昨晚被打破了。这窗户昨晚被弄坏了。","en":"This window was broken last night. This window got broken last night.","it":"Questa finestra è stata rotta ieri notte. La finestra si è rotta la notte scorsa.","ipa":"kwɛ̣sta finɛ̣stra ɛ̣ stạta rọtːa jẹri nɔ̣tːe. la finɛ̣stra si ɛ̣ rọtːa la nɔ̣tːe skọrsa."},{"n":175,"zh":"我洗手是因为它们很脏。","en":"I washed my hands because they were dirty.","it":"Mi sono lavato le mani perchè erano sporche.","ipa":"mi sọno lavạto le mạni perkɛ̣ ẹrano spọrke."},{"n":176,"zh":"我感觉很好。我昨晚睡得很香。","en":"I feel good. I slept very well last night.","it":"Mi sento bene. Ho dormito molto bene ieri notte.","ipa":"mi sɛ̣nto bẹne. ɔ dormịto mọlto bẹne jẹri nɔ̣tːe."},{"n":177,"zh":"我们昨天看了一部非常好的电影。","en":"We saw a really good movie yesterday.","it":"Ieri, abbiamo visto un film davvero bello.","ipa":"jẹri, abːjạmo vịsto un film davːẹro bɛ̣lːo."},{"n":178,"zh":"我们度假的时候雨下得很大。","en":"It rained a lot while we were on vacation.","it":"È piovuto molto mentre eravamo in vacanza.","ipa":"ɛ̣ pjovụto mọlto mɛ̣ntre eravạmo in vakạnʦa."},{"n":179,"zh":"我丢了包。你看到过吗？","en":"I've lost my bag. Have you seen it?","it":"Ho perso la [mia] borsa. L'hai vista?","ipa":"ɔ pɛ̣rso la [mịa] bọrsa. lạj vịsta?"},{"n":180,"zh":"Linda的自行车上周被偷了。","en":"Linda's bicycle was stolen last week.","it":"La bici di Linda è stata rubata settimana scorsa.","ipa":"la bịʧi di lịnda ɛ̣ stạta rubạta setːimạna skọrsa."},{"n":181,"zh":"我很累，所以早早就睡了。","en":"I went to bed early because I was tired.","it":"Sono andato a letto presto perchè ero stanco.","ipa":"sọno andạto a lɛ̣tːo prɛ̣sto perkɛ̣ ẹro stạŋko."},{"n":182,"zh":"那个购物中心大约是20年前建的。","en":"The shopping mall was built about twenty (20) years ago.","it":"Il centro commerciale fu costruito venti (20) anni fa.","ipa":"il ʧɛ̣ntro komːerʧạle fu kostrwịto vɛ̣nti (20) ạnːi fa."},{"n":183,"zh":"皮埃特罗16岁就开始学开车了。","en":"Pietro learned to drive when he was sixteen (16).","it":"Pietro ha imparato a guidare quando aveva sedici (16) anni.","ipa":"pjẹtro a imparạto a ɡwidạre kwạndo avẹva sẹdiʧi (16) ạnːi."},{"n":184,"zh":"我从没骑过马。","en":"I've never ridden a horse.","it":"Non ho mai cavalcato un cavallo.","ipa":"non ɔ mạj kavalkạto un kavạlːo."},{"n":185,"zh":"莫妮卡是我的好朋友，我认识她很久了。","en":"Monika's a good friend of mine. I've known her for a long time.","it":"Monica è una mia cara amica. La conosco da molto tempo.","ipa":"mɔ̣nika ɛ̣ ụna mịa kạra amịka. la konọsko da mọlto tẹmpo."},{"n":186,"zh":"昨天我摔倒了，把腿弄伤了。","en":"Yesterday I fell and hurt my leg.","it":"Ieri sono caduto e mi sono fatto male alla gamba.","ipa":"jẹri sọno kadụto e mi sọno fạtːo mạle ạlːa ɡạmba."},{"n":187,"zh":"我哥哥去年跑了波士顿马拉松。你跑过马拉松吗？","en":"My brother ran in the Boston Marathon last year. Have you ever run in a marathon?","it":"L'anno scorso, mio fratello ha corso la maratona di Boston. Hai mai corso una maratona?","ipa":"lạnːo skọrso, mịo fratɛ̣lːo a kọrso la maratọna di (…). ạj mạj kọrso ụna maratọna?"},{"n":188,"zh":"你告诉赫尔曼你新工作的事情了吗？","en":"Have you told Herman about your new job?","it":"Hai detto a Herman del tuo nuovo lavoro?","ipa":"ạj dɛ̣tːo a (…) dɛl tụo nwɔ̣vo lavọro?"},{"n":189,"zh":"我们周日打了篮球，打得不太好，但赢了比赛。","en":"We played basketball on Sunday. We didn't play very well, but we won the game.","it":"Abbiamo giocato a pallacanestro domenica. Non abbiamo giocato molto bene ma abbiamo vinto la partita.","ipa":"abːjạmo ʤokạto a palːakanɛ̣stro domẹnika. non abːjạmo ʤokạto mọlto bẹne m‿ abːjạmo vịnto la partịta."},{"n":190,"zh":"我认识麻萨鲁，但从来没见过他的妻子。","en":"I know Masaru, but I've never met his wife.","it":"Conosco Masaru, ma non ho mai incontrato sua moglie.","ipa":"konọsko mazạru, ma non ɔ mạj iŋkontrạto sụa mọʎːje."},{"n":191,"zh":"我们半夜被大声音乐吵醒了。","en":"We were woken up by loud music in the middle of the night.","it":"Nel bel mezzo della notte, siamo stati svegliati dalla musica alta.","ipa":"nɛl bɛl mɛ̣ʣo dɛ̣lːa nɔ̣tːe, sjạmo stạti sveʎːjạti dạlːa mụzik‿ ạlta."},{"n":192,"zh":"基米科跳进河里游到了对岸。","en":"Kimiko jumped into the river and swam to the other side.","it":"Kimiko è saltato nel fiume e ha nuotato fino all'altra sponda.","ipa":"kimịko ɛ̣ saltạto nɛl fiụm‿ e a nwotạto fịno alːạltra spọnda."},{"n":193,"zh":"你喜欢那部电影吗？——是的，我觉得很好看。","en":"Did you like the movie? — Yes, I thought it was very good.","it":"Ti è piaciuto il film? — Sì, mi è sembrato molto bello.","ipa":"ti ɛ̣ pjaʧụto il film? sị, mi ɛ̣ sembrạto mọlto bɛ̣lːo."},{"n":194,"zh":"菲律宾说着很多不同的语言。","en":"Many different languages are spoken in the Philippines.","it":"Nelle Filippine si parlano molte lingue differenti.","ipa":"nɛ̣lːe filipːịne si pạrlano mọlte lịŋɡwe difːerɛ̣nti."},{"n":195,"zh":"我们的假期因为住酒店花了很多钱。","en":"Our vacation cost a lot of money because we stayed in an expensive hotel.","it":"La nostra vacanza è costata tanti soldi perchè siamo stati in un albergo caro.","ipa":"la nọstra vakạnʦa ɛ̣ kostạta tạnti sɔ̣ldi perkɛ̣ sjạmo stạt‿ in un albɛ̣rɡo kạro."},{"n":196,"zh":"你开过超快的车吗？","en":"Have you ever driven a very fast car?","it":"Hai mai guidato una macchina davvero veloce?","ipa":"ạj mạj ɡwidạto ụna mạkːina davːẹro velɔ̣ʧe?"},{"n":197,"zh":"音乐会的所有票都很快卖完了。","en":"All the tickets for the concert were sold very quickly.","it":"Tutti i biglietti per il concerto furono venduti molto rapidamente.","ipa":"tụtː‿ i biʎːjɛ̣tːi pɛr il koɲʧɛ̣rto fụrono vendụti mọlto rapidamɛ̣nte."},{"n":198,"zh":"我们吃饭的时候，一只鸟从开着的窗户飞了进来。","en":"A bird flew in through the open window while we were having our dinner.","it":"Un uccello è volato dentro dalla finestra [aperta] mentre stavamo cenando.","ipa":"un utʧɛ̣lːo ɛ̣ volạto dɛ̣ntro dạlːa finɛ̣stra [apɛ̣rta] mɛ̣ntre stavạmo ʧenạndo."},{"n":199,"zh":"迪帕克和拉克希米在哪里？——他们在公园打网球。","en":"Where are Deepak and Lakshmi? — They're playing tennis in the park.","it":"Dove sono Deepak e Lakshmi? — Stanno giocando a tennis nel parco.","ipa":"dọve sọno (…) e (…)? — stạnːo ʤokạndo a tɛ̣nːis nɛl pạrko."},{"n":200,"zh":"派夫明天要打网球。","en":"Pavel's playing tennis tomorrow.","it":"Domani Pavel giocherà a tennis.","ipa":"domạni (…) ʤokerạ a tɛ̣nːis."}]},{"lesson":3,"range":[201,300],"items":[{"n":201,"zh":"我下周不上班。","en":"I'm not working next week.","it":"Settimana prossima non lavorerò.","ipa":"setːimạna prɔ̣sːima non lavorerɔ̣."},{"n":202,"zh":"Yuliana周五要去牙医那里。","en":"Yuliana's going to the dentist on Friday.","it":"Venerdì Giuliana andrà dal dentista.","ipa":"venerdị ʤuljạn‿ andrạ dal dentịsta."},{"n":203,"zh":"我们下周末要开派对。","en":"We're having a party next weekend.","it":"Daremo una festa il prossimo fine settimana.","ipa":"darẹmo ụna fɛ̣sta il prɔ̣sːimo fịne setːimạna."},{"n":204,"zh":"你今晚和朋友见面吗？","en":"Are you meeting your friends tonight?","it":"Ti vedrai con i tuoi amici stasera?","ipa":"ti vedrạj kon i twɔ̣j amịʧi stasẹra?"},{"n":205,"zh":"你明天晚上做什么？","en":"What are you doing tomorrow night?","it":"Cosa farai domani sera?","ipa":"kɔ̣za farạj domạni sẹra?"},{"n":206,"zh":"我今晚不出去，我要待在家里。","en":"I'm not going out tonight. I'm staying at home.","it":"Non uscirò stasera. Resterò a casa.","ipa":"non uʃirɔ̣ stasẹra. resterɔ̣ a kạza."},{"n":207,"zh":"我今晚要待在家里。","en":"I'm staying at home this evening.","it":"Stasera, rimarrò a casa.","ipa":"stasẹra, rimarːɔ̣ a kạza."},{"n":208,"zh":"你今晚出去吗？","en":"Are you going out tonight?","it":"Esci stasera?","ipa":"ẹʃi stasẹra?"},{"n":209,"zh":"Wilma下周不来参加派对。","en":"Wilma isn't coming to the party next week.","it":"Wilma non verrà alla festa settimana prossima.","ipa":"wịlma non verːạ ạlːa fɛ̣sta setːimạna prɔ̣sːima."},{"n":210,"zh":"明天早上七点半（7:30）飞机到达纽约。","en":"The plane arrives in New York at seven thirty (7:30) tomorrow morning.","it":"L'aereo arriva a New York alle sette e trenta (7:30) di domani mattina.","ipa":"laẹreo arːịv‿ a (…) (…) ạlːe sɛ̣tː‿ e trɛ̣nta (7:30) di domạni matːịna."},{"n":211,"zh":"今晚电影什么时候结束？","en":"What time does the movie end tonight?","it":"A che ora finisce il film stasera?","ipa":"a ke ọra finịʃe il film stasẹra?"},{"n":212,"zh":"我明天要去听音乐会。","en":"I'm going to a concert tomorrow.","it":"Domani andrò a un concerto.","ipa":"domạni andrɔ̣ a un koɲʧɛ̣rto."},{"n":213,"zh":"音乐会七点半（7:30）开始。","en":"The concert starts at seven thirty (7:30).","it":"Il concerto inizia alle diciannove e trenta (19:30).","ipa":"il koɲʧɛ̣rto inịʦj‿ ạlːe diʧanːɔ̣v‿ e trɛ̣nta (19:30)."},{"n":214,"zh":"你什么时候出发？","en":"What time are you leaving?","it":"A che ora partirai?","ipa":"a ke ọra partịraj?"},{"n":215,"zh":"你的飞机什么时候起飞？","en":"What time does your plane leave?","it":"A che ora parte il tuo aereo?","ipa":"a ke ọra pạrte il tụo aẹreo?"},{"n":216,"zh":"Julius周六要打网球。","en":"Julius is playing tennis on Saturday.","it":"Sabato, Giulio giocherà a tennis.","ipa":"sạbato, ʤụljo ʤokerạ a tɛ̣nːis."},{"n":217,"zh":"Claudio要去电影院。","en":"Claudio's going to the movies.","it":"Claudio sta andando al cinema.","ipa":"klạwdjo st‿ andạndo al ʧịnema."},{"n":218,"zh":"Camila要和Valerio见面。","en":"Camila's meeting with Valerio.","it":"Camilla si sta incontrando con Valerio.","ipa":"kamịlːa si sta iŋkontrạndo kon valẹrjo."},{"n":219,"zh":"Priscilla要和Wencai吃午饭。","en":"Priscilla's having lunch with Wencai.","it":"Priscilla sta pranzando con Wencai.","ipa":"(…) sta pranʦạndo kon (…)."},{"n":220,"zh":"Vitale和Rosetta要去参加派对。","en":"Vitale and Rosetta are going to a party.","it":"Vitale e Rosetta stanno andando a una festa.","ipa":"vitạl‿ e rozɛ̣tːa stạnːo andạndo a ụna fɛ̣sta."},{"n":221,"zh":"你下周工作吗？","en":"Are you working next week?","it":"Lavori settimana prossima?","ipa":"lavọri setːimạna prɔ̣sːima?"},{"n":222,"zh":"你朋友什么时候来？","en":"What time are your friends coming?","it":"A che ora arriveranno i tuoi amici?","ipa":"a ke ọra arːiverạnːo i twɔ̣j amịʧi?"},{"n":223,"zh":"一鹃什么时候去度假？","en":"When is Yijuan going on vacation?","it":"Quando andrà in vacanza Yijuan?","ipa":"kwạndo andrạ in vakạnʦa (…)?"},{"n":224,"zh":"我周一要去电影院。","en":"I'm going to the movies on Monday.","it":"Lunedì andrò al cinema.","ipa":"lunedị andrɔ̣ al ʧịnema."},{"n":225,"zh":"听说！艾莉莎下个月要结婚了！","en":"Listen to this! Elisa's getting married next month!","it":"Senti qua! Elisa si sposa il mese prossimo!","ipa":"sɛ̣nti kwa! elịza si spɔ̣za il mẹze prɔ̣sːimo!"},{"n":226,"zh":"我爸妈下周要去度假。—听起来不错，他们去哪儿？","en":"My parents are going on vacation next week. — Sounds good, where are they going?","it":"I miei genitori andranno in vacanza la settimana prossima. Benissimo, dove vanno (andranno)?","ipa":"i mjɛ̣j ʤenitọri andrạnːo in vakạnʦa la setːimạna prɔ̣sːima. benịsːimo, dọve vạnːo (andrạnːo)?"},{"n":227,"zh":"埃斯特班这学期在上英语课。课程周五结束。","en":"Esteban's taking an English course this semester. The course is ending on Friday.","it":"Esteban sta frequentando un corso d'inglese questo semestre. Il corso finirà venerdì.","ipa":"ẹsteban sta frekwentạndo un kọrso dinɡlẹze kwɛ̣sto semɛ̣stre. il kọrso finirạ venerdị."},{"n":228,"zh":"明晚有个派对，但我不去。","en":"There's a party tomorrow night, but I'm not going.","it":"Domani sera c'è una festa, ma non ci andrò.","ipa":"domạni sẹra ʧɛ̣ ụna fɛ̣sta, ma non ʧi andrɔ̣."},{"n":229,"zh":"我今晚要和朋友们出去。你一起来吗？","en":"I'm going out with some friends tonight. Why don't you come too?","it":"Uscirò con alcuni amici stasera. Perchè non vieni anche tu?","ipa":"uʃirɔ̣ kon alkụni amịʧi stasẹra. perkɛ̣ non vjẹni ạŋke tu?"},{"n":230,"zh":"我们八点（8:00）在拉吉家见面。","en":"We're meeting at Raj's house at eight o'clock (8:00).","it":"Ci vediamo a casa di Raj alle otto (8:00) spaccate.","ipa":"ʧi vedjạmo a kạza di (…) ạlːe ɔ̣tːo (8:00) spakːạte."},{"n":231,"zh":"派对后你怎么回家？打车吗？","en":"How are you getting home after the party tomorrow? By taxi?","it":"Come tornerai a casa domani dopo la festa? In taxi?","ipa":"kọme tornerạj a kạza domạni dɔ̣po la fɛ̣sta? in tạksi?"},{"n":232,"zh":"我可以坐公交。最后一班公交午夜发车。","en":"I can go by bus. The last bus leaves at midnight.","it":"Posso andarci con il pullman. L'ultimo autobus parte a mezzanotte.","ipa":"pɔ̣sːo andạrʧi kon il pụlːman. lultịmo ạwtobus pạrte a meʣanɔ̣tːe."},{"n":233,"zh":"你今晚想去看电影吗？—当然，电影几点开始？","en":"Do you want to go to the movies tonight? — Sure, what time does the movie begin?","it":"Vuoi andare al cinema stasera? — Certo, a che ora inizia il film?","ipa":"vwɔ̣j andạre al ʧịnema stasẹra? — ʧɛ̣rto, a ke ọra inịʦja il film?"},{"n":234,"zh":"你明天下午做什么？—我在工作。","en":"What are you doing tomorrow afternoon? — I'm working.","it":"Cosa farai domani pomeriggio? — Lavoro.","ipa":"kɔ̣za farạj domạni pomerịdʤo? — lavọro."},{"n":235,"zh":"我今晚要看电视。","en":"I'm going to watch TV tonight.","it":"Stasera, io guarderò la televisione.","ipa":"stasẹra, ịo ɡwarderɔ̣ la televizjọne."},{"n":236,"zh":"她今晚要看电视。","en":"She's going to watch TV tonight.","it":"Lei guarderà la tivù stasera.","ipa":"lɛ̣j ɡwarderạ la tivụ stasẹra."},{"n":237,"zh":"我明天要去买些书。","en":"I'm going to buy some books tomorrow.","it":"Domani comprerò qualche libro.","ipa":"domạni komprerɔ̣ kwạlke lịbro."},{"n":238,"zh":"萨克蒂要卖掉她的车。","en":"Shakti's going to sell her car.","it":"Shakti venderà la sua macchina.","ipa":"(…) venderạ la sụa mạkːina."},{"n":239,"zh":"我今天早上不吃早餐。我不饿。","en":"I'm not going to have breakfast this morning. I'm not hungry.","it":"Non farò colazione stamattina. Non ho fame.","ipa":"non farɔ̣ kolaʦjọne stamatːịna. non ɔ fạme."},{"n":240,"zh":"你下周的婚礼要穿什么？","en":"What are you going to wear to the wedding next week?","it":"Cosa indosserai al matrimonio la prossima settimana?","ipa":"kɔ̣za indosːerạj al matrimɔ̣njo la prɔ̣sːima setːimạna?"},{"n":241,"zh":"我要去洗手。","en":"I'm going to wash my hands.","it":"Vado a lavarmi le mani.","ipa":"vạdo a lavạrmi le mạni."},{"n":242,"zh":"你今晚的派对会邀请沃尔特吗？","en":"Are you going to invite Walter to your party?","it":"Inviterai Walter alla tua festa?","ipa":"inviterạj (…) ạlːa tụa fɛ̣sta?"},{"n":243,"zh":"我明天要和Satomi打网球。","en":"I'm playing tennis with Satomi tomorrow.","it":"Domani giocherò a tennis con Satomi.","ipa":"domạni ʤokerɔ̣ a tɛ̣nːis kon satɔ̣mi."},{"n":244,"zh":"某事要发生了。","en":"Something is going to happen.","it":"Qualcosa sta per accadere.","ipa":"kwalkɔ̣za sta pɛr akːadẹre."},{"n":245,"zh":"看看天空！要下雨了。","en":"Look at the sky! It's going to rain.","it":"Guarda il cielo! Sta per piovere.","ipa":"ɡwạrda il ʧɛ̣lo! sta pɛr pjɔ̣vere."},{"n":246,"zh":"现在九点了，我还没准备好。我要迟到了。","en":"It's nine o'clock (9:00) and I'm not ready. I'm going to be late.","it":"Sono le nove (9:00) in punto e non sono pronto. Farò tardi.","ipa":"sọno le nɔ̣ve (9:00) in pụnto e non sọno prọnto. farɔ̣ tạrdi."},{"n":247,"zh":"你今晚派对要穿什么？","en":"What are you going to wear to the party tonight?","it":"Che cosa indosserai stasera alla festa?","ipa":"ke kɔ̣za indosːerạj stasẹra ạlːa fɛ̣sta?"},{"n":248,"zh":"今天天气不错。我不想坐公交，我要步行。","en":"It's a nice day. I don't want to take the bus. I'm going to walk.","it":"È una bella giornata. Non voglio prendere l'autobus. Andrò a piedi.","ipa":"ɛ̣ ụna bɛ̣lːa ʤornạta. non vɔ̣ʎːjo prɛ̣ndere lạwtobus. andrɔ̣ a pjẹdi."},{"n":249,"zh":"Yevgeniy下周要去圣彼得堡。他会和一些朋友一起去。","en":"Yevgeniy's going to St. Petersburg next week. He's going to go with some friends.","it":"Yevgeniy andrà a San Pietroburgo settimana prossima. Andrà con alcuni amici.","ipa":"(…) andrạ a san pjetrobụrɡo setːimạna prɔ̣sːima. andrạ kon alkụni amịʧi."},{"n":250,"zh":"我饿了，我要吃个三明治。","en":"I'm hungry. I'm going to have a sandwich.","it":"Ho fame. Mi mangerò un panino.","ipa":"ɔ fạme. mi maɲʤerɔ̣ un panịno."},{"n":251,"zh":"Violetta下周过生日。我们要给她买份礼物。","en":"It's Violetta's birthday next week. We're going to get her a present.","it":"Settimana prossima è il compleanno di Violetta. Le compreremo un regalo.","ipa":"setːimạna prɔ̣sːima ɛ̣ il kompleạnːo di vjolɛ̣tːa. le komprerẹmo un reɡạlo."},{"n":252,"zh":"Feliciana说她感觉非常累。她打算躺一个小时。","en":"Feliciana says she's feeling very tired. She's going to lie down for an hour.","it":"Feliciana dice di sentirsi molto stanca. Andrà a stendersi per un'ora.","ipa":"feliʧạna dịʧe di sentịrsi mọlto stạŋka. andrạ a stɛ̣ndersi pɛr unọra."},{"n":253,"zh":"总统的演讲今晚在电视上。你要看吗？","en":"The president's speech is on television tonight. Are you going to watch it?","it":"Stasera, il discorso del presidente sarà trasmesso alla televisione. Lo guarderai?","ipa":"stasẹra, il diskọrso dɛl prezidɛ̣nte sarạ trasmɛ̣sːo ạlːa televizjọne. lo ɡwarderạj?"},{"n":254,"zh":"Gerardo毕业后打算做什么？","en":"What's Gerardo going to do when he finishes school?","it":"Cosa farà Gerardo quando avrà terminato la scuola?","ipa":"kɔ̣za farạ ʤerạrdo kwạndo avrạ terminạto la skwɔ̣la?"},{"n":255,"zh":"Aliyah每天上班。她总是从八点半到四点半都在那里。","en":"Aliyah goes to work every day. She's always there from eight thirty (8:30) until four thirty (4:30).","it":"Aliyah va a lavorare tutti i giorni. È sempre lì, dalle otto e trenta (8:30) alle quattro e trenta (4:30).","ipa":"(…) v‿ a lavorạre tụtː‿ i ʤọrni. ɛ̣ sẹmpre lị, dạlːe ɔ̣tːo e trɛ̣nta (8:30) ạlːe kwạtːro e trɛ̣nta (4:30)."},{"n":256,"zh":"现在十一点了。Aliyah在工作。","en":"It's eleven o'clock (11:00) now. Aliyah's at work.","it":"Sono le undici (11:00) in punto, adesso. Aliyah è al lavoro.","ipa":"sọno le ụndiʧi (11:00) in pụnto, adɛ̣sːo. (…) ɛ̣ al lavọro."},{"n":257,"zh":"昨天这个时候，Aliyah在工作。","en":"At eleven [o'clock] (11:00) yesterday, she was at work.","it":"Ieri alle undici (11:00), lei era al lavoro.","ipa":"jẹri ạlːe ụndiʧi (11:00), lɛ̣j ẹra al lavọro."},{"n":258,"zh":"明天这个时候，Aliyah会在工作。","en":"At eleven [o'clock] (11:00) tomorrow, she'll be at work.","it":"Domani alle undici (11:00), lei sarà al lavoro.","ipa":"domạni ạlːe ụndiʧi (11:00), lɛ̣j sarạ al lavọro."},{"n":259,"zh":"Yuko经常旅行。今天她在法兰克福，明天要去迪拜。下周要去新加坡。","en":"Yuko travels a lot. Today she's in Frankfurt. Tomorrow she'll be in Dubai. Next week she'll be in Singapore.","it":"Yuko viaggia molto. Oggi si trova a Francoforte. Domani sarà a Dubai. La prossima settimana sarà a Singapore.","ipa":"(…) vjạdʤa mọlto. ɔ̣dʤi si trɔ̣v‿ a fraŋkofɔ̣rte. domạni sarạ a dubạj. la prɔ̣sːima setːimạna sarạ a siŋɡapọre."},{"n":260,"zh":"你今晚可以给我打电话。我会在家。","en":"You can call me tonight. I'll be at home.","it":"Puoi chiamarmi stasera. Sarò a casa.","ipa":"pwɔ̣j kjamạrmi stasẹra. sarɔ̣ a kạza."},{"n":261,"zh":"把旧面包放在院子里，鸟儿会吃的。","en":"Leave the old bread in the yard. The birds will eat it.","it":"Lascia il pane vecchio in cortile. Gli uccelli lo mangeranno.","ipa":"lạʃa il pạne vɛ̣kːjo in kortịle. ʎːi utʧɛ̣lːi lo maɲʤerạnːo."},{"n":262,"zh":"我们今晚可能出去。","en":"We'll probably go out tonight.","it":"Probabilmente usciremo stasera.","ipa":"probabilmɛ̣nte uʃirẹmo stasẹra."},{"n":263,"zh":"你今晚会在家吗？","en":"Will you be at home tonight?","it":"Sarai a casa stasera?","ipa":"sarạj a kạza stasẹra?"},{"n":264,"zh":"我明天不在这里。","en":"I won't be here tomorrow.","it":"Non sarò qui domani.","ipa":"non sarɔ̣ kwị domạni."},{"n":265,"zh":"睡觉前别喝咖啡，否则你睡不着。","en":"Don't drink coffee before you go to bed; otherwise, you won't sleep.","it":"Non bere il caffè prima di andare a letto, altrimenti non riuscirai a dormire.","ipa":"non bẹre il kafːɛ̣ prịma di andạre a lɛ̣tːo, altrimɛ̣nti non riuʃirạj a dormịre."},{"n":266,"zh":"我想阿伊曼会通过驾照考试。","en":"I think Ayman will pass his driver's test.","it":"Penso che Ayman passerà l'esame di guida.","ipa":"pẹnso ke ajmạn pasːerạ lezạme di ɡwịda."},{"n":267,"zh":"我认为今天下午不会下雨。","en":"I don't think it'll rain this afternoon.","it":"Non penso che pioverà questo pomeriggio.","ipa":"non pẹnso ke pjoverạ kwɛ̣sto pomerịdʤo."},{"n":268,"zh":"你觉得考试会很难吗？","en":"Do you think the test will be difficult?","it":"Pensi che l'esame sarà difficile?","ipa":"pẹnsi ke lezạme sarạ difːịʧile?"},{"n":269,"zh":"我们周六去看电影，你想和我们一起去吗？","en":"We're going to the movies on Saturday. Do you want to come with us?","it":"Andremo al cinema sabato. Vuoi venire con noi?","ipa":"andrẹmo al ʧịnema sạbato. vwɔ̣j venịre kon nọj?"},{"n":270,"zh":"我明天不工作。","en":"I'm not working tomorrow.","it":"Domani non lavoro.","ipa":"domạni non lavọro."},{"n":271,"zh":"你明天要去考驾照吗？","en":"Are you going to take your driver's test tomorrow?","it":"Domani, sosterrai l'esame per la patente?","ipa":"domạni, sosterːạj lezạme pɛr la patɛ̣nte?"},{"n":272,"zh":"昨天她在里约热内卢。","en":"Yesterday she was in Rio de Janeiro.","it":"Ieri, lei era a Rio de Janeiro.","ipa":"jẹri, lɛ̣j ẹra a rịo de janẹiro."},{"n":273,"zh":"明天她会在加拉加斯。","en":"Tomorrow she'll be in Caracas.","it":"Domani sarà a Caracas.","ipa":"domạni sarạ a karạkas."},{"n":274,"zh":"上周她在利马。","en":"Last week she was in Lima.","it":"Settimana scorsa era a Lima.","ipa":"setːimạna skọrsa ẹra a lịma."},{"n":275,"zh":"下周她会在波哥大。","en":"Next week she'll be in Bogota.","it":"Settimana prossima sarà a Bogotà.","ipa":"setːimạna prɔ̣sːima sarạ a boɡotạ."},{"n":276,"zh":"现在她在布宜诺斯艾利斯。","en":"Right now she's in Buenos Aires.","it":"In questo momento si trova a Buenos Aires.","ipa":"in kwɛ̣sto momɛ̣nto si trɔ̣v‿ a bwɛ̣nos aịres."},{"n":277,"zh":"三天前她在圣地亚哥。","en":"Three days ago she was in Santiago.","it":"Tre giorni fa era a Santiago.","ipa":"trɛ ʤọrni fa ẹra a santjạɡo."},{"n":278,"zh":"旅行结束时她会非常累。","en":"At the end of her trip she'll be very tired.","it":"Alla fine del suo viaggio sarà molto stanca.","ipa":"ạlːa fịne dɛl sụo vjạdʤo sarạ mọlto stạŋka."},{"n":279,"zh":"一小时后我会去看电影。","en":"I'll be at the movies an hour from now.","it":"Sarò al cinema fra un'ora.","ipa":"sarɔ̣ al ʧịnema fra unọra."},{"n":280,"zh":"今晚午夜我会睡着。","en":"I'll be asleep at midnight tonight.","it":"Stasera, a mezzanotte, starò dormendo.","ipa":"stasẹra, a meʣanɔ̣tːe, starɔ̣ dormɛ̣ndo."},{"n":281,"zh":"明后天下午三点我会在工作。","en":"I'll be working at three [o'clock] (3:00) tomorrow afternoon.","it":"Alle tre (3:00) in punto di domani pomeriggio, starò lavorando.","ipa":"ạlːe trɛ (3:00) in pụnto di domạni pomerịdʤo, starɔ̣ lavorạndo."},{"n":282,"zh":"再过两年我就换新工作了。","en":"I'll be at a new job two (2) years from now.","it":"Fra due (2) anni, avrò un nuovo lavoro.","ipa":"fra dụe (2) ạnːi, avrɔ̣ un nwɔ̣vo lavọro."},{"n":283,"zh":"你准备好了吗？－还没呢，五分钟内就准备好了。","en":"Are you ready yet? － Not yet. I'll be ready in five (5) minutes.","it":"Sei già pronto? — Non ancora, sarò pronto in cinque (5) minuti.","ipa":"sɛ̣j ʤạ prọnto? — non aŋkọra, sarɔ̣ prọnto in ʧịŋkwe (5) minụti."},{"n":284,"zh":"我要去外面几天，今晚就出发，所以明天不在家。","en":"I'm going away for a few days. I'm leaving tonight, so I won't be at home tomorrow.","it":"Vado via per alcuni giorni. Parto questa sera, perciò domani non sarò a casa.","ipa":"vạdo vịa pɛr alkụni ʤọrni. pạrto kwɛ̣sta sẹra, perʧɔ̣ domạni non sarɔ̣ a kạza."},{"n":285,"zh":"不会下雨，所以不用带伞。","en":"It won't rain, so you don't need to take an umbrella.","it":"Non pioverà, quindi non hai bisogno di prendere l'ombrello.","ipa":"non pjoverạ, kwịndi non ạj bizọɲːo di prɛ̣ndere lombrɛ̣lːo."},{"n":286,"zh":"我今晚感觉不太舒服。","en":"I don't feel very well tonight.","it":"Non mi sento molto bene stasera.","ipa":"non mi sɛ̣nto mọlto bẹne stasẹra."},{"n":287,"zh":"好吧，早点睡，明天早上你会感觉好些。","en":"Well, go to bed early and you'll feel better in the morning.","it":"Beh, va' a letto presto e ti sentirai meglio domattina.","ipa":"bɛ, v‿ a lɛ̣tːo prɛ̣sto e ti sentirạj mẹʎːjo domatːịna."},{"n":288,"zh":"下周一就是Qasim的生日，他25岁。","en":"It's Qasim's birthday next Monday. He'll be twenty-five (25).","it":"Lunedì prossimo è il compleanno di Qasim. Compierà venticinque (25) anni.","ipa":"lunedị prɔ̣sːimo ɛ̣ il kompleạnːo di (…). kompjerạ ventiʧịŋkwe (25) ạnːi."},{"n":289,"zh":"很抱歉今天早上我迟到了，不会再发生了。","en":"I'm sorry I was late this morning. It won't happen again.","it":"Mi dispiace ero in ritardo stamattina. Non succederà di nuovo.","ipa":"mi dispjạʧ‿ ẹro in ritạrdo stamatːịna. non sutʧederạ di nwɔ̣vo."},{"n":290,"zh":"我想Euna会通过驾照考试。","en":"I think Euna will pass her driver's test.","it":"Penso che Euna supererà l'esame di guida.","ipa":"pẹnso ke (…) supererạ lezạme di ɡwịda."},{"n":291,"zh":"我想Jiyeong不会通过驾照考试。","en":"I don't think Jiyeong will pass his driver's test.","it":"Non penso che Jiyeong passerà l'esame della patente.","ipa":"non pẹnso ke (…) pasːerạ lezạme dɛ̣lːa patɛ̣nte."},{"n":292,"zh":"我想我们会赢得比赛。","en":"I think we'll win the game.","it":"Penso che vinceremo la partita.","ipa":"pẹnso ke viɲʧerẹmo la partịta."},{"n":293,"zh":"我明天不会在这里。＞我觉得我明天不会在这里。","en":"I won't be here tomorrow. > I don't think I'll be here tomorrow.","it":"Non sarò qui domani. > Non penso che ci sarò domani.","ipa":"non sarɔ̣ kwị domạni. > non pẹnso ke ʧi sarɔ̣ domạni."},{"n":294,"zh":"我想Iris会喜欢她的礼物。","en":"I think Iris will like her present.","it":"Penso che a Iris piacerà il [suo] regalo.","ipa":"pẹnso ke a ịris pjaʧerạ il [sụo] reɡạlo."},{"n":295,"zh":"他们不会结婚的。＞我觉得他们不会结婚的。","en":"They won't get married. > I don't think they'll get married.","it":"Non si sposeranno. > Non penso che si sposeranno.","ipa":"non si spozerạnːo. > non pẹnso ke si spozerạnːo."},{"n":296,"zh":"你不会喜欢这部电影的。＞我觉得你不会喜欢这部电影的。","en":"You won't like the movie. > I don't think you'll like the movie.","it":"Non ti piacerà il film. > Non penso che ti piacerà il film.","ipa":"non ti pjaʧerạ il film. > non pẹnso ke ti pjaʧerạ il film."},{"n":297,"zh":"我们今晚要去电影院，我们有票。","en":"We're going to the theater tonight. We've got tickets.","it":"Andiamo a teatro stasera. Abbiamo i biglietti.","ipa":"andjạmo a teạtro stasẹra. abːjạmo i biʎːjɛ̣tːi."},{"n":298,"zh":"你明天晚上有什么安排？－没什么，我空闲。","en":"What are you doing tomorrow night? — Nothing, I'm free.","it":"Cosa fai domani sera? — Niente, sono libero.","ipa":"kɔ̣za fạj domạni sẹra? — njɛ̣nte, sọno lịbero."},{"n":299,"zh":"他们明天早上出发，火车八点四十（8:40）。","en":"They're leaving tomorrow morning. Their train is at eight forty (8:40).","it":"Partono domani mattina. Il loro treno è alle otto e quaranta (8:40).","ipa":"pạrtono domạni matːịna. il lọro trẹno ɛ̣ ạlːe ɔ̣tːo e kwarạnta (8:40)."},{"n":300,"zh":"你为什么穿外套？－我要出去。","en":"Why are you putting on your coat? — I'm going out.","it":"Perché stai mettendo il cappotto? — Sto uscendo.","ipa":"perkɛ̣ stạj metːɛ̣ndo il kapːɔ̣tːo? — stɔ uʃɛ̣ndo."}]},{"lesson":4,"range":[301,400],"items":[{"n":301,"zh":"你觉得Jorge今晚会给我们打电话吗？","en":"Do you think Jorge will call us tonight?","it":"Pensi che Jorge ci chiamerà stasera?","ipa":"pẹnsi ke (…) ʧi kjamerạ stasẹra?"},{"n":302,"zh":"法里德周六不能见我们，他在工作。","en":"Farid can't meet us on Saturday. He's working.","it":"Farid non può incontrarci sabato. Lavora.","ipa":"(…) non pwɔ̣ venịre sạbato. lavọra."},{"n":303,"zh":"我们坐飞机去巴塞罗那吧，不用开车那么久。","en":"Let's fly to Barcelona instead of driving. It won't take as long.","it":"Prendiamo un volo per Barcellona invece di guidare. Non ci vorrà così tanto tempo.","ipa":"prendjạmo un vọlo pɛr barʧelːọna invẹʧe di ɡwidạre. non ʧi vorːạ kozị tạnto tẹmpo."},{"n":304,"zh":"你周末有什么计划？","en":"What are your plans for the weekend?","it":"Quali sono i tuoi programmi per il fine settimana?","ipa":"kwạli sọno i twɔ̣j proɡrạmːi pɛr il fịne setːimạna?"},{"n":305,"zh":"一些朋友要来和我们住一起。","en":"Some friends are coming to stay with us.","it":"Alcuni amici verranno a stare da noi.","ipa":"alkụni amịʧi verːạnːo a stạre da nọj."},{"n":306,"zh":"我的箱子很重，我帮你拿。","en":"My suitcase is very heavy. － I'll carry it for you.","it":"La mia valigia è molto pesante. — Te la porto io.","ipa":"la mịa valịʤa ɛ̣ mọlto pezạnte. — tɛ la pɔ̣rto ịo."},{"n":307,"zh":"我明天给你打电话，好吗？","en":"I'll call you tomorrow, okay?","it":"Ti chiamo domani, va bene?","ipa":"ti kjạmo domạni, va bẹne?"},{"n":308,"zh":"我累了，我觉得今晚早点睡。","en":"I'm tired. I think I'll go to bed early tonight.","it":"Sono stanco. Penso che andrò a letto presto stasera.","ipa":"sọno stạŋko. pẹnso ke andrɔ̣ a lɛ̣tːo prɛ̣sto stasẹra."},{"n":309,"zh":"今天天气真好，我想我会在外面坐着。","en":"It's a nice day. I think I'll sit outside.","it":"È una bella giornata. Penso che mi siederò fuori.","ipa":"ɛ̣ ụna bɛ̣lːa ʤornạta. pẹnso ke mi sjederɔ̣ fwɔ̣ri."},{"n":310,"zh":"下雨了，我觉得今天可能不会出去。","en":"It's raining. I don't think I'll go out.","it":"Sta piovendo. Non penso che uscirò.","ipa":"sta pjovɛ̣ndo. non pẹnso ke uʃirɔ̣."},{"n":311,"zh":"我明天要工作。","en":"I'm working tomorrow.","it":"Domani lavoro.","ipa":"domạni lavọro."},{"n":312,"zh":"今晚电视上有好节目，我要看。","en":"There's a good program on TV tonight. I'm going to watch it.","it":"C'è un bel programma in televisione stasera. Lo guarderò.","ipa":"ʧɛ̣ un bɛl proɡrạmːa in televizjọne stasẹra. lo ɡwarderɔ̣."},{"n":313,"zh":"你这个周末打算做什么？","en":"What are you doing this weekend?","it":"Che cosa fai questo fine settimana?","ipa":"ke kɔ̣za fạj kwɛ̣sto fịne setːimạna?"},{"n":314,"zh":"这房间很暖和，我开个窗户行吗？","en":"It's very warm in this room. Shall I open a window?","it":"Fa davvero caldo in questa stanza. Devo aprire la finestra?","ipa":"fa davːẹro kạldo in kwɛ̣sta stạnʦa. dẹvo aprịre la finɛ̣stra?"},{"n":315,"zh":"我今晚给你打电话好吗？","en":"Shall I call you tonight?","it":"Devo chiamarti stasera?","ipa":"dẹvo kjamạrti stasẹra?"},{"n":316,"zh":"今天天气真好，我们去散步怎么样？","en":"It's a nice day. Shall we go for a walk?","it":"È una bella giornata. Andiamo a fare una passeggiata?","ipa":"ɛ̣ ụna bɛ̣lːa ʤornạta. andjạmo a fạre ụna pasːedʤạta?"},{"n":317,"zh":"我们晚餐吃什么？","en":"What shall we have for dinner?","it":"Cosa mangiamo per cena?","ipa":"kɔ̣za maɲʤạmo pɛr ʧẹna?"},{"n":318,"zh":"我今晚给你打电话好吗？","en":"Should I call you tonight?","it":"Ti devo chiamare stasera?","ipa":"ti dẹvo kjamạre stasẹra?"},{"n":319,"zh":"今天天气真好，我们去散步怎么样？","en":"It's a nice day. Should we go for a walk?","it":"È una bella giornata. Dovremmo andare a fare una passeggiata?","ipa":"ɛ̣ ụna bɛ̣lːa ʤornạta. dovrɛ̣mːo andạre a fạre ụna pasːedʤạta?"},{"n":320,"zh":"我们晚餐吃什么？","en":"What should we have for dinner?","it":"Cosa dovremmo mangiare per cena?","ipa":"kɔ̣za dovrɛ̣mːo maɲʤạre pɛr ʧẹna?"},{"n":321,"zh":"享受你的假期吧。我会给你寄张明信片。","en":"Enjoy your vacation. — I'll send you a postcard.","it":"Divertiti in vacanza. — Ti manderò una cartolina.","ipa":"divɛ̣rtit‿ in vakạnʦa. — ti manderɔ̣ ụna kartolịna."},{"n":322,"zh":"我不要这个香蕉。我饿了，我吃。","en":"I don't want this banana. — I'm hungry. I'll have it.","it":"Non voglio questa banana. — Ho fame, la mangerò io.","ipa":"non vɔ̣ʎːjo kwɛ̣sta banạna. — ɔ fạme, la maɲʤerɔ̣ ịo."},{"n":323,"zh":"你要椅子吗？不用了，我坐地上。","en":"Do you want a chair? — No, it's okay. I'll sit on the floor.","it":"Vuoi una sedia? — No, va bene così. Mi siederò per terra.","ipa":"vwɔ̣j ụna sẹdja? — nɔ, va bẹne kozị. mi sjederɔ̣ pɛr tɛ̣rːa."},{"n":324,"zh":"你给Gamila打电话了吗？哦不，我忘了。我现在就打。","en":"Did you call Gamila? — Oh no, I forgot. I'll call her now.","it":"Hai chiamato Gamila? — Ah, no, mi sono dimenticato, la chiamerò adesso.","ipa":"ạj kjamạto ɡamịla? — a, nɔ, mi sọno dimentikạto, la kjamerɔ̣ adɛ̣sːo."},{"n":325,"zh":"你要和我一起来吗？不了，我想我在这儿待着。","en":"Are you coming with me? — No, I don't think so. I'm staying here.","it":"Vieni con me? — No, credo di no. Io resto qui.","ipa":"vjẹni kon mɛ? — nɔ, krẹdo di nɔ. ịo rẹsto kwị."},{"n":326,"zh":"你怎么用这个相机？给我，我教你。","en":"How do you use this camera? — Give it to me and I'll show you.","it":"Come si usa questa videocamera? — Dammela che te lo mostro.","ipa":"kọme si ụza kwɛ̣sta videokạmera? — dạmːela ke tɛ lo mọstro."},{"n":327,"zh":"今天好冷。我觉得我不出去。","en":"It's cold today. I don't think I'll go out.","it":"Fa freddo oggi. Non penso che uscirò.","ipa":"fa frɛ̣dː‿ ɔ̣dʤi. non pẹnso ke uʃirɔ̣."},{"n":328,"zh":"我饿了，我想买点吃的。","en":"I'm hungry. I think I'll buy something to eat.","it":"Ho fame. Penso che comprerò qualcosa da mangiare.","ipa":"ɔ fạme. pẹnso ke komprerɔ̣ kwalkɔ̣za da maɲʤạre."},{"n":329,"zh":"我很累。我觉得我今天不玩网球了。","en":"I feel very tired. I don't think I'll play tennis today.","it":"Mi sento molto stanco. Non penso che oggi giocherò a tennis.","ipa":"mi sɛ̣nto mọlto stạŋko. non pẹnso ke ɔ̣dʤi ʤokerɔ̣ a tɛ̣nːis."},{"n":330,"zh":"我喜欢这顶帽子。我想我买下它。","en":"I like this hat. I think I'll buy it.","it":"Mi piace questo cappello. Penso che lo comprerò.","ipa":"mi pjạʧe kwɛ̣sto kapːɛ̣lːo. pẹnso ke lo komprerɔ̣."},{"n":331,"zh":"这相机太贵了。我觉得我不买。","en":"This camera is too expensive. I don't think I'll buy it.","it":"Questa videocamera è troppo cara. Non penso che la comprerò.","ipa":"kwɛ̣sta videokạmera ɛ̣ trɔ̣pːo kạra. non pẹnso ke la komprerɔ̣."},{"n":332,"zh":"我还没买东西呢。我稍后再买。","en":"I haven't done the shopping yet. I'll do it later.","it":"Non ho ancora fatto la spesa. La farò più tardi.","ipa":"non ɔ aŋkọra fạtːo la spẹza. la farɔ̣ piụ tạrdi."},{"n":333,"zh":"我喜欢运动。我经常看电视上的体育节目。","en":"I like sports. I watch a lot of sports on TV.","it":"Mi piacciono gli sport. Guardo molti sport alla televisione.","ipa":"mi pjạtʧono ʎːi spɔrt. ɡwạrdo mọlti spɔrt ạlːa televizjọne."},{"n":334,"zh":"我需要锻炼一下。我想去散步。","en":"I need some exercise. I think I'll go for a walk.","it":"Ho bisogno di fare un po' di movimento. Penso che andrò a fare una passeggiata.","ipa":"ɔ bizọɲːo di fạre un pɔ di movimɛ̣nto. pẹnso ke andrɔ̣ a fạre ụna pasːedʤạta."},{"n":335,"zh":"Yoshi打算买辆新车。他上周告诉我的。","en":"Yoshi's going to buy a new car. He told me last week.","it":"Yoshi comprerà una nuova macchina. Me l'ha detto la settimana scorsa.","ipa":"(…) komprerạ ụna nwɔ̣va mạkːina. mɛ la dɛ̣tːo la setːimạna skọrsa."},{"n":336,"zh":"这封信是给Sachiko的。——好吧，我给她。","en":"This letter is for Sachiko. — Okay, I'll give it to her.","it":"Questa lettera è per Sachiko. — Ok, gliela darò io.","ipa":"kwɛ̣sta lɛ̣tːera ɛ̣ pɛr (…). — ɔk, ʎːjẹla darɔ̣ ịo."},{"n":337,"zh":"你今晚有什么安排吗？","en":"Are you doing anything this evening?","it":"Fai qualcosa stasera?","ipa":"fạj kwalkɔ̣za stasẹra?"},{"n":338,"zh":"是的，我要和几个朋友出去。","en":"Yes, I'm going out with some friends.","it":"Sì, esco con alcuni amici.","ipa":"sị, ẹsko kon alkụni amịʧi."},{"n":339,"zh":"我明天晚上不能和你出去，因为我得工作。","en":"I can't go out with you tomorrow night, as I'm working.","it":"Non posso uscire con te domani sera perché lavoro.","ipa":"non pɔ̣sːo uʃịre kon tɛ domạni sẹra perkɛ̣ lavọro."},{"n":340,"zh":"这房间好暗。我应该开灯吗？","en":"It's dark in this room. Should I turn on the light?","it":"E' buio in questa stanza. Devo accendere la luce?","ipa":"ɛ̣ bụjo in kwɛ̣sta stạnʦa. dẹvo atʧɛ̣ndere la lụʧe?"},{"n":341,"zh":"我在这儿等吗？——不，跟我来。","en":"Shall I wait here? — No, come with me.","it":"Aspetto qui? — No, vieni con me.","ipa":"aspɛ̣tːo kwị? — nɔ, vjẹni kon mɛ."},{"n":342,"zh":"我该去商店吗？——不，我去。","en":"Should I go to the store? — No, I'll go.","it":"Devo andare a fare la spesa? — No, ci vado io.","ipa":"dẹvo andạre a fạre la spẹza? — nɔ, ʧi vạdo ịo."},{"n":343,"zh":"我们开个派对怎么样？——好，我们邀请谁呢？","en":"Should we have a party? — Yes, who shall we invite?","it":"Dovremmo organizzare una festa? — Sì, chi invitiamo?","ipa":"dovrɛ̣mː‿ orɡaniʦːạre ụna fɛ̣sta? — sị, k‿ invitjạmo?"},{"n":344,"zh":"我不确定假期去哪儿。我可能去哥斯达黎加。","en":"I'm not sure where to go on vacation. I might go to Costa Rica.","it":"Non so bene dove andare in ferie. Forse, potrei andare in Costa Rica.","ipa":"non sɔ bẹne dọve andạre in fẹrje. fọrse, potrẹj andạre in kɔ̣sta rịka."},{"n":345,"zh":"看起来可能会下雨。","en":"It looks like it might rain.","it":"Sembra che possa venire a piovere.","ipa":"sẹmbra ke pɔ̣sːa venịre a pjɔ̣vere."},{"n":346,"zh":"我今晚可能去看电影，但还不确定。","en":"I might go to the movies tonight, but I'm not sure.","it":"Potrei magari andare al cinema stasera, ma non ne sono sicuro.","ipa":"potrẹj maɡạri andạre al ʧịnema stasẹra, ma non ne sọno sikụro."},{"n":347,"zh":"Faruq什么时候给你打电话？——我不知道。他可能今天下午打。","en":"When's Faruq going to call you? — I don't know. He might call this afternoon.","it":"Quando ti chiamerà Faruq? — Non lo so. È possibile che chiami questo pomeriggio.","ipa":"kwạndo ti kjamerạ (…)? — non lo sɔ. ɛ̣ posːịbile ke kjạmi kwɛ̣sto pomerịdʤo."},{"n":348,"zh":"带把伞吧。可能会下雨。","en":"Take an umbrella with you. It might rain.","it":"Prendi un ombrello con te. Potrebbe piovere.","ipa":"prɛ̣ndi un ombrɛ̣lːo kon tɛ. potrɛ̣bːe pjɔ̣vere."},{"n":349,"zh":"买张彩票。你可能好运。","en":"Buy a lottery ticket. You might be lucky.","it":"Compra un biglietto della lotteria. Potresti essere fortunato.","ipa":"kọmpra un biʎːjɛ̣tːo dɛ̣lːa lotːerịa. potrɛ̣sti ɛ̣sːere fortunạto."},{"n":350,"zh":"你今晚出去吗？——我可能去。","en":"Are you going out tonight? — I might.","it":"Esci stasera? — Può darsi.","ipa":"ẹʃi stasẹra? — pwɔ̣ dạrsi."},{"n":351,"zh":"我明天打网球。> 我可能明天打网球。","en":"I'm playing tennis tomorrow. > I might play tennis tomorrow.","it":"Domani giocherò a tennis. > È possibile che domani giochi a tennis.","ipa":"domạni ʤokerɔ̣ a tɛ̣nːis. ɛ̣ posːịbile ke domạni ʤɔ̣ki a tɛ̣nːis."},{"n":352,"zh":"Hadiya稍后会打电话。","en":"Hadiya's going to call later.","it":"Hadiya chiamerà più tardi.","ipa":"(…) kjamerạ piụ tạrdi."},{"n":353,"zh":"Hadiya可能稍后会打电话。","en":"Hadiya might call later.","it":"Hadiya potrebbe chiamare più tardi.","ipa":"(…) potrɛ̣bːe kjamạre piụ tạrdi."},{"n":354,"zh":"我可能明天不去上班。","en":"I might not go to work tomorrow.","it":"Potrebbe darsi che domani non vada al lavoro.","ipa":"potrɛ̣bːe dạrsi ke domạni non vạd‿ al lavọro."},{"n":355,"zh":"Shumei可能不会来派对。","en":"Shumei might not come to the party.","it":"Shumei potrebbe non venire alla festa.","ipa":"(…) potrɛ̣bːe non venịre ạlːa fɛ̣sta."},{"n":356,"zh":"我今晚可能去看电影。","en":"I may go to the movies tonight.","it":"Può darsi che stasera vada al cinema.","ipa":"pwɔ̣ dạrsi ke stasẹra vạd‿ al ʧịnema."},{"n":357,"zh":"Jianhao可能不会来派对。","en":"Jianhao may not come to the party.","it":"Jianhao potrebbe non venire alla festa.","ipa":"(…) potrɛ̣bːe non venịre ạlːa fɛ̣sta."},{"n":358,"zh":"我可以问个问题吗？","en":"May I ask a question?","it":"Potrei fare una domanda?","ipa":"potrẹj fạre ụna domạnda?"},{"n":359,"zh":"我可以坐这儿吗？——当然可以。","en":"May I sit here? — Sure.","it":"Posso sedermi qui? — Certo.","ipa":"pɔ̣sːo sedẹrmi kwị? — ʧɛ̣rto."},{"n":360,"zh":"我可能去看电影。> 我可能去看电影。","en":"It's possible that I'll go to the movies. > I might go to the movies.","it":"È possibile che io vada al cinema. > Potrebbe darsi che vada al cinema.","ipa":"ɛ̣ posːịbile ke ịo vạd‿ al ʧịnema. > potrɛ̣bːe dạrsi ke vạd‿ al ʧịnema."},{"n":361,"zh":"我明天可能见到你。","en":"It's possible that I'll see you tomorrow. > I might see you tomorrow.","it":"Domani, è possibile che ti veda. > Forse, potrei vederti domani.","ipa":"domạni, ɛ̣ posːịbile ke ti vẹda. > fọrse, potrẹj vedẹrti domạni."},{"n":362,"zh":"他可能忘记打电话了。","en":"It's possible that Hakim will forget to call. > He might forget to call.","it":"È possibile che Hakim si dimentichi di chiamare. > Hakim potrebbe dimenticarsi di chiamare.","ipa":"ɛ̣ posːịbile ke (…) si dimɛ̣ntiki di kjamạre. > (…) potrɛ̣bːe dimentikạrsi di kjamạre."},{"n":363,"zh":"今天可能要下雪。","en":"It's possible that it'll snow today. > It might snow today.","it":"È possibile che oggi nevichi. > Potrebbe nevicare oggi.","ipa":"ɛ̣ posːịbile ke ɔ̣dʤi nẹviki. > potrɛ̣bːe nevikạre ɔ̣dʤi."},{"n":364,"zh":"我今晚可能要迟到。","en":"It's possible that I'll be late tonight. > I might be late tonight.","it":"È possibile che faccia tardi stanotte. > Potrei fare tardi questa notte.","ipa":"ɛ̣ posːịbile ke fạtʧa tạrdi stạnotːe. > potrẹj fạre tạrdi kwɛ̣sta nɔ̣tːe."},{"n":365,"zh":"她下周可能不在这里。","en":"It's possible that Jamila won't be here next week. > She might not be here next week.","it":"È possibile che Jamila non sarà qui la settimana prossima. > Potrebbe non essere qui la prossima settimana.","ipa":"ɛ̣ posːịbile ke (…) non sarạ kwị la setːimạna prɔ̣sːima. > potrɛ̣bːe non ɛ̣sːere kwị la prɔ̣sːima setːimạna."},{"n":366,"zh":"我可能没时间出去。","en":"It's possible that I won't have time to go out. > I might not have time to go out.","it":"È possibile che io non avrò tempo per uscire. > Potrei non aver tempo di uscire.","ipa":"ɛ̣ posːịbile ke ịo non avrɔ̣ tẹmpo pɛr uʃịre. > potrẹj non avẹr tẹmpo di uʃịre."},{"n":367,"zh":"你假期要去哪里？——我不确定。我可能去意大利。","en":"Where are you going for your vacation? — I'm not sure. I might go to Italy.","it":"Dove andrai in vacanza? — Non lo so. Forse, potrei andare in Italia.","ipa":"dọve andrạj in vakạnʦa? — non lo sɔ. fọrse, potrẹj andạre in itạlja."},{"n":368,"zh":"这个周末你打算做什么？——我不知道。我可能去徒步旅行。","en":"What are you doing this weekend? — I don't know. I might go hiking.","it":"Cosa fai questo fine settimana? — Non lo so. Forse vado a fare una camminata in montagna.","ipa":"kɔ̣za fạj kwɛ̣sto fịne setːimạna? — non lo sɔ. fọrse vạdo a fạre ụna kamːinạta in montạɲːa."},{"n":369,"zh":"你什么时候再见到Pablo？——我不确定。我可能这个夏天会见到他。","en":"When will you see Pablo again? — I'm not sure. I might see him this summer.","it":"Quando vedrai Paolo di nuovo? — Non lo so, forse quest'estate.","ipa":"kwạndo vedrạj pạolo di nwɔ̣vo? — non lo sɔ, fọrse kwɛstestạte."},{"n":370,"zh":"你晚饭打算吃什么？——我不知道。我可能吃意大利菜。","en":"What are you going to have for dinner? — I don't know. I might have Italian food.","it":"Che cosa mangerai per cena? — Non lo so, potrei mangiare italiano.","ipa":"ke kɔ̣za maɲʤerạj pɛr ʧẹna? — non lo sɔ, potrẹj maɲʤạre italjạno."},{"n":371,"zh":"你今晚怎么回家？——我不确定。我可能坐公交车。","en":"How are you going to get home tonight? — I'm not sure. I might take the bus.","it":"Come tornerai a casa stasera? — Non so. Forse in autobus.","ipa":"kọme tornerạj a kạza stasẹra? — non sɔ. fọrse in ạwtobus."},{"n":372,"zh":"我听说你赢了一些钱。你打算怎么用？——我还没决定。我可能开个餐馆。","en":"I hear you won some money. What are you going to do with it? — I haven't decided yet. I might open a restaurant.","it":"Ho sentito che hai vinto dei soldi. Che cosa ci farai? Non ho ancora deciso. Magari, potrei aprire un ristorante.","ipa":"ɔ sentịto ke ạj vịnto dẹj sɔ̣ldi. ke kɔ̣za ʧi farạj? non ɔ aŋkọra deʧịzo. maɡạri, potrẹj aprịre un ristorạnte."},{"n":373,"zh":"他明天下午要打网球。","en":"He's playing tennis tomorrow afternoon.","it":"Domani pomeriggio lui giocherà a tennis.","ipa":"domạni pomerịdʤo lụj ʤokerạ a tɛ̣nːis."},{"n":374,"zh":"他明天晚上可能出去。","en":"He might go out tomorrow evening.","it":"Lui potrebbe uscire domani sera.","ipa":"lụj potrɛ̣bːe uʃịre domạni sẹra."},{"n":375,"zh":"他可能早起。","en":"He might get up early.","it":"Lui potrebbe alzarsi presto.","ipa":"lụj potrɛ̣bːe alʦạrsi prɛ̣sto."},{"n":376,"zh":"他明天不会工作。","en":"He won't be working tomorrow.","it":"Lui domani non lavorerà.","ipa":"lụj domạni non lavorerạ."},{"n":377,"zh":"他明天早上可能在家。","en":"He might be at home tomorrow morning.","it":"Domani mattina, potrebbe essere a casa.","ipa":"domạni matːịna, potrɛ̣bː‿ ɛ̣sːere a kạza."},{"n":378,"zh":"他可能看电视。","en":"He might watch television.","it":"Forse, potrebbe guardare la televisione.","ipa":"fọrse, potrɛ̣bːe ɡwardạre la televizjọne."},{"n":379,"zh":"他下午肯定要出去。","en":"He's going out in the afternoon for sure.","it":"Di sicuro, uscirà nel pomeriggio.","ipa":"di sikụro, uʃirạ nɛl pomerịdʤo."},{"n":380,"zh":"他可能去购物，但他不确定。","en":"He might go shopping, but he's not sure.","it":"Potrebbe andare a fare compere, ma non ne è sicuro.","ipa":"potrɛ̣bːe andạre a fạre kọmpere, ma non n‿ ɛ̣ sikụro."},{"n":381,"zh":"我会弹钢琴。我哥哥也会弹钢琴。","en":"I can play the piano. My brother can play the piano, too.","it":"So suonare il pianoforte. Anche mio fratello sa suonare il pianoforte.","ipa":"sɔ swonạre il pjanofɔ̣rte. ạŋke mịo fratɛ̣lːo sa swonạre il pjanofɔ̣rte."},{"n":382,"zh":"Marisol会说意大利语和西班牙语，但不会说法语。","en":"Marisol can speak Italian and Spanish, but she can't speak French.","it":"Marisol parla l'italiano e lo spagnolo, ma non sa parlare il francese.","ipa":"marizɔ̣l pạrla litaljạno e lo spaɲːọlo, ma non sa parlạre il fraɲʧẹze."},{"n":383,"zh":"你会游泳吗？——是的，但我不太擅长。","en":"Can you swim? — Yes, but I'm not a very good swimmer.","it":"Sai nuotare? — Sì, però non sono un bravo nuotatore.","ipa":"sạj nwotạre? — sị, perɔ̣ non sọno un brạvo nwotatọre."},{"n":384,"zh":"你能换开二十美元吗？——抱歉，我换不开。","en":"Can you change a twenty-dollar bill? — I'm sorry, I can't.","it":"Puoi cambiarmi una banconota da venti dollari? — No, mi dispiace.","ipa":"pwɔ̣j kambjạrmi ụna baŋkonɔ̣ta da vɛ̣nti dɔ̣lːari? — nɔ, mi dispjạʧe."},{"n":385,"zh":"我下周要办派对，但Hyeonyeong和Maengsuk不能来。","en":"I'm having a party next week, but Hyeonyeong and Maengsuk can't come.","it":"Darò una festa settimana prossima, ma Hyeonyeong e Maengsuk non possono venire.","ipa":"darɔ̣ ụna fɛ̣sta setːimạna prɔ̣sːima, ma (…) e (…) non pɔ̣sːono venịre."},{"n":386,"zh":"我小时候跑得很快。","en":"When I was young, I could run very fast.","it":"Quand'ero giovane, riuscivo a correre molto velocemente.","ipa":"kwandẹro ʤọvane, riuʃịvo a kọrːere mọlto veloʧemɛ̣nte."},{"n":387,"zh":"Nuria来美国之前，她几乎不懂英语。现在她什么都能懂。","en":"Before Nuria came to the United States, she couldn't understand much English. Now she can understand everything.","it":"Nuria, prima di venire negli Stati Uniti, non capiva molto l'inglese. Ora riesce a capire tutto.","ipa":"nụrja, prịma di venịre nɛ̣ʎːi stạti unịti, non kapịva mọlto linɡlẹze. ọra rjẹʃe a kapịre tụtːo."},{"n":388,"zh":"我昨晚很累，但睡不着。","en":"I was tired last night, but I couldn't sleep.","it":"Ero stanco ieri notte, però non riuscivo a dormire.","ipa":"ẹro stạŋko jẹri nɔ̣tːe, perɔ̣ non riuʃịvo a dormịre."},{"n":389,"zh":"我上周办了派对，但Imran和Latifa没来。","en":"I had a party last week, but Imran and Latifa couldn't come.","it":"Ho fatto una festa settimana scorsa, ma Imran e Latifa non sono potuti venire.","ipa":"ɔ fạtːo ụna fɛ̣sta setːimạna skọrsa, ma (…) e latịfa non sọno potụti venịre."},{"n":390,"zh":"请你开门好吗？——请你开门好吗？","en":"Can you open the door, please? > Could you open the door, please?","it":"Puoi aprire la porta, per favore? > Potresti aprire la porta, per favore?","ipa":"pwɔ̣j aprịre la pɔ̣rta, pɛr favọre? > potrɛ̣sti aprịre la pɔ̣rta, pɛr favọre?"},{"n":391,"zh":"请你等一下，好吗？——请你等一下，好吗？","en":"Can you wait a minute, please? > Could you wait a moment, please?","it":"Puoi aspettare un minuto, per favore? > Potresti aspettare un momento, per favore?","ipa":"pwɔ̣j aspetːạre un minụto, pɛr favọre? > potrɛ̣sti aspetːạre un momɛ̣nto, pɛr favọre?"},{"n":392,"zh":"请给我换一美元零钱，好吗？——请给我换一美元零钱，好吗？","en":"Can I have change for a dollar, please? > Could I have change for a dollar, please.","it":"Posso cambiare un euro, per favore? > Potrei cambiare un euro, per favore?","ipa":"pɔ̣sːo kambjạre un ẹwro, pɛr favọre? > potrẹj kambjạre un ẹwro, pɛr favọre?"},{"n":393,"zh":"Silvio，我能借你的伞吗？——Silvio，我能借你的伞吗？","en":"Silvio, can I borrow your umbrella? > Silvio, could I borrow your umbrella?","it":"Silvio, posso prendere in prestito il tuo ombrello? > Silvio, potrei prendere in prestito il tuo ombrello?","ipa":"sịlvjo, pɔ̣sːo prɛ̣ndere in prɛ̣stito il tụo ombrɛ̣lːo? > sịlvjo, potrẹj prɛ̣ndere in prɛ̣stito il tụo ombrɛ̣lːo?"},{"n":394,"zh":"你好，我能和Tomas说话吗？——你好，我能和Tomas说话吗？","en":"Hello, can I speak to Tomas, please? > Hello, could I speak to Tomas please?","it":"Pronto, posso parlare con Tommaso, per favore? > Pronto, potrei parlare con Tommaso, per favore?","ipa":"prọnto, pɔ̣sːo parlạre kon tọmːazo, pɛr favọre? > prọnto, potrẹj parlạre kon tọmːazo, pɛr favọre?"},{"n":395,"zh":"你会游泳吗？","en":"Can you swim?","it":"Sai nuotare?","ipa":"sạj nwotạre?"},{"n":396,"zh":"你会滑雪吗？","en":"Can you ski?","it":"Sai sciare?","ipa":"sạj ʃiạre?"},{"n":397,"zh":"你会下棋吗？","en":"Can you play chess?","it":"Sei capace di giocare a scacchi?","ipa":"sɛ̣j kapạʧe di ʤokạre a skạkːi?"},{"n":398,"zh":"你能跑十公里吗？","en":"Can you run ten (10) kilometers?","it":"Sai correre dieci (10) chilometri?","ipa":"sạj kọrːere djẹʧi (10) kilɔ̣metri?"},{"n":399,"zh":"你会开车吗？","en":"Can you drive a car?","it":"Sai guidare?","ipa":"sạj ɡwidạre?"},{"n":400,"zh":"你会骑摩托车吗？","en":"Can you drive a motorcycle?","it":"Sei capace di andare in moto?","ipa":"sɛ̣j kapạʧe di andạre in mọto?"}]},{"lesson":5,"range":[401,500],"items":[{"n":401,"zh":"你会骑马吗？","en":"Can you ride a horse?","it":"Sai andare a cavallo?","ipa":"sạj andạre a kavạlːo?"},{"n":402,"zh":"对不起，但我们下周末不能参加你的派对。","en":"I'm sorry, but we can't come to your party next weekend.","it":"Mi dispiace ma non possiamo venire alla tua festa la settimana prossima.","ipa":"mi dispjạʧe ma non posːjạmo venịre ạlːa tụa fɛ̣sta la setːimạna prɔ̣sːima."},{"n":403,"zh":"我喜欢这个酒店房间。从窗户可以看到山。","en":"I like this hotel room. You can see the mountains from the window.","it":"Mi piace questa camera d'albergo. Si possono vedere le montagne dalla finestra.","ipa":"mi pjạʧe kwɛ̣sta kạmera dalbɛ̣rɡo. si pɔ̣sːono vedẹre le montạɲːe dạlːa finɛ̣stra."},{"n":404,"zh":"你说话声音很小。我听不见你。","en":"You're speaking very quietly. I can't hear you.","it":"Stai parlando troppo a voce bassa. Non riesco a sentirti.","ipa":"stạj parlạndo trɔ̣pːo a vọʧe bạsːa. non rjẹsko a sentịrti."},{"n":405,"zh":"你看到我的行李箱了吗？我找不到它。","en":"Have you seen my suitcase? I can't find it.","it":"Hai visto la mia valigia? Non riesco a trovarla.","ipa":"ạj vịsto la mịa valịʤa? non rjẹsko a trovạrla."},{"n":406,"zh":"奥尔加因为会说五种语言而得到了这份工作。","en":"Olga got the job because she can speak five (5) languages.","it":"Olga ha ottenuto il lavoro perchè parla cinque (5) lingue.","ipa":"ɔ̣lɡ‿ a otːenụto il lavọro perkɛ̣ pạrla ʧịŋkwe (5) lịŋɡwe."},{"n":407,"zh":"我很累，但睡不着。","en":"I was tired, but I couldn't sleep.","it":"Ero stanco, ma non riuscivo a dormire.","ipa":"ẹro stạŋko, ma non riuʃịvo a dormịre."},{"n":408,"zh":"我昨天不饿。我吃不完晚饭。","en":"I wasn't hungry yesterday. I couldn't finish dinner.","it":"Non avevo fame ieri. Non sono riuscito a finire la cena.","ipa":"non avẹvo fạme jẹri. non sọno riuʃịto a finịre la ʧẹna."},{"n":409,"zh":"拉希德不知道该怎么办。他无法决定。","en":"Rashid doesn't know what to do. He can't decide.","it":"Rashid non sa cosa fare. Non riesce a decidersi.","ipa":"(…) non sa kɔ̣za fạre. non rjẹʃe a deʧịdersi."},{"n":410,"zh":"我昨天想和夏奇拉说话，但我找不到她。","en":"I wanted to speak to Shakira yesterday, but I couldn't find her.","it":"Ieri, volevo parlare con Shakira, ma non sono riuscito a trovarla.","ipa":"jẹri, volẹvo parlạre kon sakịra, ma non sọno riuʃịto a trovạrla."},{"n":411,"zh":"维克拉姆下周末不能去音乐会。他得工作。","en":"Vikram can't go to the concert next weekend. He has to work.","it":"Vikram non può andare al concerto il prossimo fine settimana. Deve lavorare.","ipa":"(…) non pwɔ̣ andạre al koɲʧɛ̣rto il prɔ̣sːimo fịne setːimạna. dẹve lavorạre."},{"n":412,"zh":"拉克希米上周不能参加会议。她生病了。","en":"Lakshmi couldn't go to the meeting last week. She was sick.","it":"Lakshmi non è potuto andare all'incontro settimana scorsa. Era ammalata.","ipa":"lạksmi non ɛ̣ potụto andạre alːiŋkọntro setːimạna skọrsa. ẹra amːalạta."},{"n":413,"zh":"你今天工作了十个小时。你一定很累。","en":"You worked ten (10) hours today. You must be tired.","it":"Oggi hai lavorato dieci (10) ore. Devi essere stanco.","ipa":"ɔ̣dʤi ạj lavorạto djẹʧi (10) ọre. dẹvi ɛ̣sːere stạŋko."},{"n":414,"zh":"我的兄弟在你公司工作了好几年。你一定认识他。","en":"My brother has worked at your company for years. You must know him.","it":"Mio fratello lavora in azienda da anni. Devi per forza conoscerlo.","ipa":"mịo fratɛ̣lːo lavọra in aʦjɛ̣nda d‿ ạnːi. dẹvi pɛr fɔ̣rʦa konọʃerlo."},{"n":415,"zh":"我的朋友们和你有同样的邮政编码。他们一定住在你附近。","en":"My friends have the same postal code as you. They must live near you.","it":"I miei amici hanno il tuo stesso codice postale. Devono vivere vicino a te.","ipa":"i mjɛ̣j amịʧi ạnːo il tụo stɛ̣sːo kọdiʧe postạle. dẹvono vịvere viʧịno a tɛ."},{"n":416,"zh":"这不是威尔逊家吗？对不起。我一定是记错了号码。","en":"This isn't the Wilsons? I'm sorry. I must have the wrong number.","it":"Questa non è la casa dei Wilson? Mi scusi, devo avere il numero sbagliato.","ipa":"kwɛ̣sta non ɛ̣ la kạza dẹj (…)? mi skụzi, dẹvo avẹre il nụmero zbaʎːjạto."},{"n":417,"zh":"电话响了八次，萨米亚没有接。她一定不在家。","en":"The phone rang eight (8) times and Samiya didn't answer. She must not be at home.","it":"Il telefono ha suonato otto (8) volte e Samiya non ha risposto. Non deve essere a casa.","ipa":"il telɛ̣fono a swonạt‿ ɔ̣tːo (8) vɔ̣lt‿ e (…) non a rispɔ̣sto. non dẹv‿ ɛ̣sːere a kạza."},{"n":418,"zh":"萨维埃尔到处都坐公交车。他一定没有车。","en":"Xavier takes the bus everywhere. He must not have a car.","it":"Xavier prende l'autobus ovunque si trovi. Non deve avere la macchina.","ipa":"(…) prɛ̣nde lạwtobus ovụŋkwe si trɔ̣vi. non dẹve avẹre la mạkːina."},{"n":419,"zh":"西尔瓦一家总是周五在家。他们那时一定不工作。","en":"The Silvas are always home on Fridays. They must not work then.","it":"I Silva sono sempre a casa di venerdì. Non devono lavorare, quindi.","ipa":"i sịlva sọno sẹmpre a kạza di venerdị. non dẹvono lavorạre, kwịndi."},{"n":420,"zh":"你得小心这把刀。它很锋利。","en":"You must be careful with this knife. It's very sharp.","it":"Devi fare attenzione con questo coltello. È molto affilato.","ipa":"dẹvi fạre atːenʦjọne kon kwɛ̣sto koltɛ̣lːo. ɛ̣ mọlto afːilạto."},{"n":421,"zh":"在这台机器上，工人必须戴安全眼镜。","en":"Workers must wear safety glasses at this machine.","it":"I lavoratori devono indossare gli occhiali protettivi con questa macchina.","ipa":"i lavoratọri dẹvono indosːạre ʎːi okːjạli protetːịvi kon kwɛ̣sta mạkːina."},{"n":422,"zh":"在美国，你必须满18岁才能投票。","en":"In the United States, you must be eighteen (18) to vote.","it":"Negli Stati Uniti bisogna avere diciotto (18) anni per votare.","ipa":"nɛ̣ʎːi stạti unịti bizọɲː‿ avẹre diʧɔ̣tːo (18) ạnːi pɛr votạre."},{"n":423,"zh":"他们处于危险之中，必须小心。","en":"They were in a dangerous situation. They had to be careful.","it":"Si trovavano in una situazione pericolosa. Hanno dovuto prestare attenzione.","ipa":"si trovạvano in ụna sitwaʦjọne perikolọza. ạnːo dovụto prestạre atːenʦjọne."},{"n":424,"zh":"上周我们去工厂参观时，必须戴安全眼镜。","en":"We had to wear safety glasses when we visited the factory last week.","it":"Abbiamo dovuto indossare degli occhiali di protezione, quando abbiamo visitato la fabbrica la settimana scorsa.","ipa":"abːjạmo dovụto indosːạre dẹʎːi okːjạli di proteʦjọne, kwạndo abːjạmo vizitạto la fạbːrika la setːimạna skọrsa."},{"n":425,"zh":"自行车手不得在人行道上骑行。","en":"Bicyclists must not ride on the sidewalk.","it":"I ciclisti non possono andare in bicicletta sul marciapiede.","ipa":"i ʧiklịsti non pɔ̣sːono andạre in biʧiklɛ̣tːa sul marʧapjẹde."},{"n":426,"zh":"你不能再迟到了。","en":"You must not be late for school again.","it":"Non devi arrivare ancora in ritardo a scuola.","ipa":"non dẹvi arːivạre aŋkọra in ritạrdo a skwɔ̣la."},{"n":427,"zh":"现在是晚上，你一整天都没吃东西。你一定饿了。","en":"It's evening, and you haven't eaten anything all day. You must be hungry.","it":"È sera e non hai mangiato niente per tutto il giorno. Devi essere affamato.","ipa":"ɛ̣ sẹra e non ạj maɲʤạto njɛ̣nte pɛr tụtːo il ʤọrno. dẹvi ɛ̣sːere afːamạto."},{"n":428,"zh":"这是镇上最受欢迎的餐厅，所以食物一定很好。","en":"It's the most popular restaurant in town, so the food must be good.","it":"È il ristorante più famoso in città, perciò il cibo deve essere buono.","ipa":"ɛ̣ il ristorạnte piụ famọzo in ʧitːạ, perʧɔ̣ il ʧịbo dẹv‿ ɛ̣sːere bwɔ̣no."},{"n":429,"zh":"我得到这份工作了。——你真的得到了？你一定很兴奋。","en":"I got the job. — You did? You must be excited.","it":"Ho ottenuto il lavoro. — Davvero? Devi essere entusiasta.","ipa":"ɔ otːenụto il lavọro. — davːẹro? dẹvi ɛ̣sːere entuzjạsta."},{"n":430,"zh":"电话在响。我知道不是给我的。一定是给你的。","en":"The phone's ringing. I know it's not for me. It must be for you.","it":"Il telefono sta suonando. So che non è per me. Deve essere per te.","ipa":"il telɛ̣fono sta swonạndo. sɔ ke non ɛ̣ pɛr mɛ. dẹv‿ ɛ̣sːere pɛr tɛ."},{"n":431,"zh":"我的钥匙不在客厅，所以它们一定在厨房。","en":"My keys aren't in the living room, so they must be in the kitchen.","it":"Le mie chiavi non sono in sala, quindi devono essere in cucina.","ipa":"le mịe kjạvi non sọno in sạla, kwịndi dẹvono ɛ̣sːere in kuʧịna."},{"n":432,"zh":"Renata每天都穿蓝色衣服。她一定喜欢蓝色。","en":"Renata wears something blue every day. She must like the color blue.","it":"Renata indossa qualcosa di blu ogni giorno. Deve piacerle il [colore] blu.","ipa":"renạta indɔ̣sːa kwalkɔ̣za di blu ɔ̣ɲːi ʤọrno. dẹve pjaʧẹrle il [kolọre] blu."},{"n":433,"zh":"加西亚家有六个孩子和三只狗。他们一定有一所大房子。","en":"The Garcias have six (6) children and three (3) dogs. They must have a big house.","it":"I Garcia hanno sei (6) figli e tre (3) cani. Devono possedere una casa molto grande.","ipa":"i (…) ạnːo sɛ̣j (6) fịʎːi e trɛ (3) kạni. dẹvono posːẹdere ụna kạza mọlto ɡrạnde."},{"n":434,"zh":"陈太太在商店买了三升牛奶。她的孩子们喝很多牛奶。","en":"Mrs. Chen bought three (3) liters of milk at the store. Her children drink a lot of milk.","it":"La signora Chen ha comprato tre (3) litri di latte al negozio di alimentari. I suoi bambini bevono molto latte.","ipa":"la siɲːọra (…) a komprạto trɛ (3) lịtri di lạtːe al neɡɔ̣ʦjo di alimentạri. i swɔ̣j bambịni bẹvono mọlto lạtːe."},{"n":435,"zh":"我知道汤普森女士有工作，但她白天总是在家。她一定晚上工作。","en":"I know Ms. Thompson has a job, but she's always home during the day. She must work at night.","it":"So che la signora Thompson ha un lavoro, ma durante il giorno è sempre a casa. Deve lavorare di notte.","ipa":"sɔ ke la siɲːọra tɔ̣mpson a un lavọro, ma durạnte il ʤọrno ɛ̣ sẹmpre a kạza. dẹve lavorạre di nɔ̣tːe."},{"n":436,"zh":"这不是卡尔森家吗？我一定是记错了号码。","en":"This isn't the Karlsons? I must have the wrong number.","it":"Questa non è casa Karlson? Devo avere il numero sbagliato.","ipa":"kwɛ̣sta non ɛ̣ kạza (…)? dẹvo avẹre il nụmero zbaʎːjạto."},{"n":437,"zh":"Omar很瘦。他一定吃得不多。","en":"Omar is very thin. He must not eat very much.","it":"Omar è molto magro. Non deve essere uno che mangia molto.","ipa":"ɔ̣mar ɛ̣ mọlto mạɡro. non dẹv‿ ɛ̣sːere ụno ke mạɲʤa mọlto."},{"n":438,"zh":"我早上从不看到我的邻居。他一定很早就去工作了。","en":"I never see my neighbor in the morning. He must leave for work very early.","it":"Non vedo mai il mio vicino la mattina. Deve uscire molto presto per andare al lavoro.","ipa":"non vẹdo mạj il mịo viʧịno la matːịna. dẹve uʃịre mọlto prɛ̣sto pɛr andạre al lavọro."},{"n":439,"zh":"我和Tomoko说话时总是得重复。她一定听力不好。","en":"I always have to repeat things when I talk to Tomoko. She must not hear very well.","it":"Devo sempre ripetere le cose quando parlo con Tomoko. Lei, non deve sentirci bene.","ipa":"dẹvo sẹmpre ripẹtere le kɔ̣ze kwạndo pạrlo kon (…). lɛ̣j, non dẹve sentịrʧi bẹne."},{"n":440,"zh":"Ludwig每天都穿同样的衣服。他一定衣服不多。","en":"Ludwig wears the same clothes every day. He must not have many clothes.","it":"Ludwig indossa gli stessi vestiti ogni giorno. Non deve avere molti vestiti.","ipa":"(…) indɔ̣sːa ʎːi stɛ̣sːi vestịti ɔ̣ɲːi ʤọrno. non dẹve avẹre mọlti vestịti."},{"n":441,"zh":"你感冒发烧了？可怜的人！你一定感觉很难受。","en":"You have a cold and a fever? Poor thing! You must feel awful.","it":"Hai l'influenza e la febbre? Poverino (♀Poverina)! Devi sentirti molto male.","ipa":"ạj linflwẹnʦa e la fẹbːre? poverịno (♀poverịna)! dẹvi sentịrti mọlto mạle."},{"n":442,"zh":"在美国大多数地方，你必须至少16岁才能拿到驾照。","en":"In most of the United States, you must be at least sixteen (16) to get a driver's license.","it":"Nella maggior parte degli Stati Uniti, bisogna avere almeno sedici (16) anni per prendere la patente di guida.","ipa":"nɛ̣lːa madʤọr pạrte dẹʎːi stạti unịti, bizọɲː‿ avẹre almẹno sẹdiʧi (16) ạnːi pɛr prɛ̣ndere la patɛ̣nte di ɡwịda."},{"n":443,"zh":"这份工作要求你会西班牙语和德语。","en":"For this job, you must know both Spanish and German.","it":"Per fare questo lavoro, devi sapere parlare sia lo spagnolo che il tedesco.","ipa":"pɛr fạre kwɛ̣sto lavọro, dẹvi sapẹre parlạre sịa lo spaɲːọlo ke il tedɛ̣sko."},{"n":444,"zh":"汽车前排乘客必须系安全带。","en":"People in the front seat of a car must wear a seat belt.","it":"Le persone sedute sui sedili anteriori di un'autovettura, devono allacciare la cintura di sicurezza.","ipa":"le persọne sedụte sụj sedịli anterjọri di unawtovetːụra, dẹvono alːatʧạre la ʧintụra di sikurɛ̣ʦːa."},{"n":445,"zh":"想上大学的中学学生必须成绩好。","en":"High school students who want to go to college must get good grades.","it":"Gli studenti di scuola superiore che vogliono frequentare l'università devono avere degli ottimi voti.","ipa":"ʎːi studɛ̣nti di skwɔ̣la superjọre ke vɔ̣ʎːjono frekwentạre luniversitạ dẹvono avẹre dẹʎːi ọtːimi vọti."},{"n":446,"zh":"这条高速公路关闭了。司机必须走另一条路。","en":"This highway is closed. Drivers must take another road.","it":"Quest'autostrada è chiusa. Gli automobilisti devono prendere un'altra strada.","ipa":"kwɛstawtostrạda ɛ̣ kiụza. ʎːi awtomobilịsti dẹvono prɛ̣ndere unạltra strạda."},{"n":447,"zh":"一个网球运动员要想职业打球必须非常出色。","en":"A tennis player must be very good to play professionally.","it":"Un giocatore di tennis deve essere davvero bravo per giocare a livello professionale.","ipa":"un ʤokatọre di tɛ̣nːis dẹv‿ ɛ̣sːere davːẹro brạvo pɛr ʤokạre a livɛ̣lːo profesːjonạle."},{"n":448,"zh":"我们别忘了给Rita寄生日卡。","en":"We mustn't forget to send Rita a birthday card.","it":"Non dobbiamo dimenticarci d'inviare a Rita un biglietto d'auguri.","ipa":"non dobːjạmo dimentikạrʧi dinvjạre a rịta un biʎːjɛ̣tːo dawɡụri."},{"n":449,"zh":"我必须快点，不然会迟到的。","en":"I must hurry, or I'll be late.","it":"Devo sbrigarmi o sarò in ritardo.","ipa":"dẹvo zbriɡạrmi o sarɔ̣ in ritạrdo."},{"n":450,"zh":"你为什么这么晚？——我不得不等半个钟头的公交车。","en":"Why were you so late? — I had to wait half an hour for the bus.","it":"Perchè sei arrivato così tardi? — Ho dovuto aspettare per mezz'ora l'autobus.","ipa":"perkɛ̣ sɛ̣j arːivạto kozị tạrdi? — ɔ dovụto aspetːạre pɛr meʣọra lạwtobus."},{"n":451,"zh":"把这些文件放在安全的地方。你绝不能弄丢它们。","en":"Keep these papers in a safe place. You must not lose them.","it":"Custodici questi fogli in un posto sicuro. Non devi perderli.","ipa":"kustɔ̣diʧi kwɛ̣sti fɔ̣ʎː‿ in un pɔ̣sto sikụro. non dẹvi pɛ̣rderli."},{"n":452,"zh":"自行车手必须遵守和司机一样的交通规则。","en":"Bicyclists must follow the same traffic rules as drivers.","it":"I ciclisti devono seguire le stesse regole stradali degli automobilisti.","ipa":"i ʧiklịsti dẹvono seɡwịre le stɛ̣sːe rẹɡole stradạli dẹʎːi awtomobilịsti."},{"n":453,"zh":"我们离开时别忘了关灯。","en":"We must not forget to turn off the lights when we leave.","it":"Non dobbiamo scordarci di spegnere la luce quando ce ne andiamo.","ipa":"non dobːjạmo skordạrʧi di spẹɲːere la lụʧe kwạndo ʧe ne andjạmo."},{"n":454,"zh":"我通常不星期六工作，但上星期六我不得不工作。","en":"I don't usually work on Saturdays, but last Saturday I had to work.","it":"Di solito non lavoro il sabato, ma sabato scorso ho dovuto lavorare.","ipa":"di sɔ̣lito non lavọro il sạbato, ma sạbato skọrs‿ ɔ dovụto lavorạre."},{"n":455,"zh":"Yeonhwa学习不够努力。她应该更用功。","en":"Yeonhwa doesn't study enough. She should study harder.","it":"Yeonhwa non studia abbastanza, dovrebbe studiare di più.","ipa":"(…) non stụdj‿ abːastạnʦa, dovrɛ̣bːe studjạre di piụ."},{"n":456,"zh":"这是一部好电影。你应该去看看。","en":"It's a good movie. You should go and see it.","it":"È un bel film. Dovresti andare a vederlo.","ipa":"ɛ̣ un bɛl film. dovrɛ̣sti andạre a vedẹrlo."},{"n":457,"zh":"打网球时，你应该总是盯着球看。","en":"When you play tennis, you should always watch the ball.","it":"Quando giochi a tennis, dovresti sempre guardare la palla.","ipa":"kwạndo ʤɔ̣ki a tɛ̣nːis, dovrɛ̣sti sẹmpre ɡwardạre la pạlːa."},{"n":458,"zh":"我应该邀请Sara吃饭吗？","en":"Should I invite Sara to dinner?","it":"Dovrei invitare Sara a cena?","ipa":"dovrẹj invitạre sạra a ʧẹna?"},{"n":459,"zh":"我们应该为晚餐准备点特别的吗？","en":"Should we make something special for dinner?","it":"Dovremmo preparare qualcosa di speciale per la cena?","ipa":"dovrɛ̣mːo preparạre kwalkɔ̣za di speʧạle pɛr la ʧẹna?"},{"n":460,"zh":"Leopold不应该睡得太晚。","en":"Leopold shouldn't go to bed so late.","it":"Leopoldo non dovrebbe andare a letto così tardi.","ipa":"leopɔ̣ldo non dovrɛ̣bːe andạre a lɛ̣tːo kozị tạrdi."},{"n":461,"zh":"你总是看电视。你不应该看那么多电视。","en":"You watch TV all the time. You shouldn't watch TV so much.","it":"Guardi la televisione tutto il tempo. Non dovresti guardare la tivù così tanto.","ipa":"ɡwạrdi la televizjọne tụtːo il tẹmpo. non dovrɛ̣sti ɡwardạre la tivụ kozị tạnto."},{"n":462,"zh":"我认为Zahida应该买些新衣服。","en":"I think Zahida should buy some new clothes.","it":"Penso che Zahida dovrebbe comprarsi dei vestiti nuovi.","ipa":"pẹnso ke (…) dovrɛ̣bːe komprạrsi dẹj vestịti nwɔ̣vi."},{"n":463,"zh":"很晚了。我觉得我现在应该回家了。","en":"It's late. I think I should go home now.","it":"È tardi. Penso che dovrei andare a casa adesso.","ipa":"ɛ̣ tạrdi. pẹnso ke dovrẹj andạre a kạz‿ adɛ̣sːo."},{"n":464,"zh":"我该买这件大衣吗？——是的，我觉得你应该。","en":"Shall I buy this coat? — Yes, I think you should.","it":"Che dici, me lo compro questo cappotto? — Sì, penso che dovresti comprartelo.","ipa":"ke dịʧi, mɛ lo kọmpro kwɛ̣sto kapːɔ̣tːo? — sị, pẹnso ke dovrɛ̣sti komprạrtelo."},{"n":465,"zh":"我认为你不应该工作这么辛苦。","en":"I don't think you should work so hard.","it":"Penso che non dovresti lavorare così duramente.","ipa":"pẹnso ke non dovrɛ̣sti lavorạre kozị duramɛ̣nte."},{"n":466,"zh":"我认为我们还不应该走。太早了。","en":"I don't think we should go yet. It's too early.","it":"Non penso che dovremmo già andare. È troppo presto.","ipa":"non pẹnso ke dovrɛ̣mːo ʤạ andạre. ɛ̣ trɔ̣pːo prɛ̣sto."},{"n":467,"zh":"你觉得我应该买这顶帽子吗？","en":"Do you think I should buy this hat?","it":"Pensi che dovrei comprare questo cappello?","ipa":"pẹnsi ke dovrẹj komprạre kwɛ̣sto kapːɛ̣lːo?"},{"n":468,"zh":"你觉得我们什么时候回家比较好？","en":"What time do you think we should go home?","it":"A che ora pensi [che] dovremmo andare a casa?","ipa":"a ke ọra pẹnsi [ke] dovrɛ̣mːo andạre a kạza?"},{"n":469,"zh":"我今晚应该学习，但我可能去看电影。","en":"I should study tonight, but I think I'll go to the movies.","it":"Dovrei studiare stasera, ma penso che andrò al cinema.","ipa":"dovrẹj studjạre stasẹra, ma pẹnso ke andrɔ̣ al ʧịnema."},{"n":470,"zh":"我今晚必须学习，我不能去看电影。","en":"I have to study tonight. I can't go to the movies.","it":"Stasera, devo studiare. Non posso andare al cinema.","ipa":"stasẹra, dẹvo studjạre. non pɔ̣sːo andạre al ʧịnema."},{"n":471,"zh":"我应该学习今晚，但我可能去看电影。","en":"I ought to study tonight, but I think I'll go to the movies.","it":"Dovrei studiare stasera, penso, però, che andrò al cinema.","ipa":"dovrẹj studjạre stasẹra, pẹnso, perɔ̣, ke andrɔ̣ al ʧịnema."},{"n":472,"zh":"我认为Mahmud应该买些新衣服。","en":"I think Mahmud ought to buy some new clothes.","it":"Penso che Mahmud dovrebbe comprarsi dei vestiti nuovi.","ipa":"pẹnso ke mạmud dovrɛ̣bːe komprạrsi dẹj vestịti nwɔ̣vi."},{"n":473,"zh":"很晚了，你也很累了。你应该去睡觉。","en":"It's late, and you're very tired. You should go to bed.","it":"È tardi e tu sei molto stanco. Dovresti andare a letto.","ipa":"ẹ tạrdi e tu sɛ̣j mọlto stạŋko. dovrɛ̣sti andạre a lɛ̣tːo."},{"n":474,"zh":"你应该多吃水果和蔬菜。","en":"You should eat plenty of fruit and vegetables.","it":"Dovresti mangiare frutta e verdura in abbondanza.","ipa":"dovrɛ̣sti maɲʤạre frụtːa e verdụra in abːondạnʦa."},{"n":475,"zh":"如果你有时间，你应该去参观科学博物馆。那里很有趣。","en":"If you have time, you should visit the Science Museum. It's very interesting.","it":"Se hai tempo, dovresti visitare il Museo della Scienza. È molto interessante.","ipa":"se ạj tẹmpo, dovrɛ̣sti vizitạre il muzẹo dɛ̣lːa ʃẹnʦa. ɛ̣ mọlto interesːạnte."},{"n":476,"zh":"你开车时应该系上安全带。","en":"When you're driving, you should wear a seat belt.","it":"Quando guidi, dovresti indossare la cintura di sicurezza.","ipa":"kwạndo ɡwịdi, dovrɛ̣st‿ indosːạre la ʧintụra di sikurɛ̣ʦːa."},{"n":477,"zh":"这本书非常好。你应该读一读。","en":"It's a very good book. You should read it.","it":"È davvero un ottimo libro. Dovresti leggerlo.","ipa":"ɛ̣ davːẹro un ọtːimo lịbro. dovrɛ̣sti lẹdʤerlo."},{"n":478,"zh":"她不应该看那么多电视。","en":"She shouldn't watch TV so much.","it":"Lei non dovrebbe guardare così tanta televisione.","ipa":"lɛ̣j non dovrɛ̣bːe ɡwardạre kozị tạnta televizjọne."},{"n":479,"zh":"他不应该吃太多。","en":"He shouldn't eat too much.","it":"Lui non dovrebbe mangiare troppo.","ipa":"lụj non dovrɛ̣bːe maɲʤạre trɔ̣pːo."},{"n":480,"zh":"你不应该工作这么辛苦。","en":"You shouldn't work so hard.","it":"Non dovresti lavorare così tanto.","ipa":"non dovrɛ̣sti lavorạre kozị tạnto."},{"n":481,"zh":"我不应该开这么快。","en":"I shouldn't drive so fast.","it":"Non dovrei guidare così veloce.","ipa":"non dovrẹj ɡwidạre kozị velɔ̣ʧe."},{"n":482,"zh":"你在试穿夹克：“你觉得我应该买这件夹克吗？”","en":"You're trying on a jacket: \"Do you think I should buy this jacket?\"","it":"Stai provando una giacca: «Pensi che dovrei comprare questa giacca?»","ipa":"stạj provạndo ụna ʤạkːa: «pẹnsi ke dovrẹj komprạre kwɛ̣sta ʤạkːa?»"},{"n":483,"zh":"你不能开车：“你觉得我应该学开车吗？”","en":"You can't drive: \"Do you think I should learn how to drive?\"","it":"Non sai guidare: «Pensi che dovrei imparare a guidare?»","ipa":"non sạj ɡwidạre: «pẹnsi ke dovrẹj imparạre a ɡwidạre?»"},{"n":484,"zh":"你不喜欢你的工作：“你觉得我应该找另一份工作吗？”","en":"You don't like your job: \"Do you think I should get another job?\"","it":"Non ti piace il tuo lavoro: «Pensi che dovrei cambiare lavoro?»","ipa":"non ti pjạʧe il tụo lavọro: «pẹnsi ke dovrẹj kambjạre lavọro?»"},{"n":485,"zh":"你要办派对：“你觉得我应该邀请奥斯卡吗？”","en":"You're going to have a party: \"Do you think I should invite Oskar?\"","it":"Farai una festa: «Pensi che dovrei invitare Oscar?»","ipa":"farạj ụna fɛ̣sta: «pẹnsi ke dovrẹj invitạre ɔ̣skar?»"},{"n":486,"zh":"我们明天得早起。我觉得我们现在应该回家。","en":"We have to get up early tomorrow. I think we should go home now.","it":"Domani, dobbiamo svegliarci presto. Penso che dovremmo andare a casa adesso.","ipa":"domạni, dobːjạmo sveʎːjạrʧi prɛ̣sto. pẹnso ke dovrɛ̣mːo andạre a kạz‿ adɛ̣sːo."},{"n":487,"zh":"那件外套你穿太大。我觉得你不应该买。","en":"That coat is too big for you. I don't think you should buy it.","it":"Quel cappotto è troppo grande per te. Penso che non dovresti comprarlo.","ipa":"kwɛ̣l kapːɔ̣tːo ɛ̣ trɔ̣pːo ɡrạnde pɛr tɛ. pẹnso ke non dovrɛ̣sti komprạrlo."},{"n":488,"zh":"你不需要你的车。你应该卖掉它。","en":"You don't need your car. You should sell it.","it":"Non hai bisogno della [tua] macchina. Dovresti venderla.","ipa":"non ạj bizọɲːo dɛ̣lːa [tụa] mạkːina. dovrɛ̣sti vɛ̣nderla."},{"n":489,"zh":"瓦伦蒂娜需要改变。我觉得她应该去旅行。","en":"Valentina needs a change. I think she should take a trip.","it":"Valentina ha bisogno di una svolta nella sua vita. Penso che dovrebbe farsi un bel viaggio.","ipa":"valentịn‿ a bizọɲːo di ụna svɔ̣lta nɛ̣lːa sụa vịta. pẹnso ke dovrɛ̣bːe fạrsi un bɛl vjạdʤo."},{"n":490,"zh":"纳尔和扎伊娜太年轻了。我觉得他们不应该结婚。","en":"Nur and Zaina are too young. I don't think they should get married.","it":"Nur e Zaina sono troppo giovani. Non penso [che] dovrebbero sposarsi.","ipa":"(…) e ʦaịna sọno trɔ̣pːo ʤọvani. non pẹnso [ke] dovrɛ̣bːero spozạrsi."},{"n":491,"zh":"你还病着。我觉得你不应该去上班。","en":"You're still sick. I don't think you should go to work.","it":"Sei ancora malato. Non penso che dovresti andare al lavoro.","ipa":"sɛ̣j aŋkọra malạto. non pẹnso ke dovrɛ̣sti andạre al lavọro."},{"n":492,"zh":"西蒙今天感觉不舒服。我觉得他应该去看医生。","en":"Simon isn't feeling well today. I think he should go see the doctor.","it":"Oggi Simone non si sente bene. Penso che dovrebbe andare dal dottore.","ipa":"ɔ̣dʤi simọne non si sɛ̣nte bẹne. pẹnso ke dovrɛ̣bːe andạre dal dotːọre."},{"n":493,"zh":"那家酒店对我们来说太贵了。我觉得我们不应该在那里住。","en":"The hotel is too expensive for us. I don't think we should stay there.","it":"L'albergo è troppo caro per noi. Non penso [che] dovremmo alloggiarci.","ipa":"lalbɛ̣rɡo ɛ̣ trɔ̣pːo kạro pɛr nọj. non pẹnso [ke] dovrɛ̣mːo alːodʤạrʧi."},{"n":494,"zh":"我认为每个人都应该学一门外语。","en":"I think everybody should learn another language.","it":"Penso che ognuno dovrebbe imparare un'altra lingua.","ipa":"pẹnso ke oɲːụno dovrɛ̣bːe imparạre unạltra lịŋɡwa."},{"n":495,"zh":"我认为每个人都应该去另一个国家旅行。","en":"I think everybody should travel to another country.","it":"Penso che ognuno dovrebbe viaggiare in un altro paese.","ipa":"pẹnso ke oɲːụno dovrɛ̣bːe vjadʤạre in un ạltro paẹze."},{"n":496,"zh":"我认为人们不应该吸烟。","en":"I don't think people should smoke.","it":"Penso che le persone non dovrebbero fumare.","ipa":"pẹnso ke le persọne non dovrɛ̣bːero fumạre."},{"n":497,"zh":"我觉得我应该存更多钱。","en":"I think I should save more money.","it":"Penso che dovrei risparmiare più soldi.","ipa":"pẹnso ke dovrẹj risparmjạre piụ sɔ̣ldi."},{"n":498,"zh":"我明天上班会迟到。我得去看牙医。","en":"I'll be late for work tomorrow. I have to go to the dentist.","it":"Domani farò tardi al lavoro. Devo andare dal dentista.","ipa":"domạni farɔ̣ tạrdi al lavọro. dẹvo andạre dal dentịsta."},{"n":499,"zh":"约兰达七点开始工作，所以她得六点起床。","en":"Yolanda starts work at seven [o'clock] (7:00), so she has to get up at six [o'clock] (6:00).","it":"Yolanda inizia a lavorare alle sette (7:00) in punto. Per questo deve alzarsi alle sei.","ipa":"(…) inịʦj‿ a lavorạre ạlːe sɛ̣tːe (7:00) in pụnto. pɛr kwɛ̣sto dẹve alʦạrsi ạlːe sɛ̣j."},{"n":500,"zh":"你得通过考试才能拿到驾照。","en":"You have to pass a test before you can get a driver's license.","it":"Devi superare l'esame prima di riuscire a prendere la patente di guida.","ipa":"dẹvi superạre lezạme prịma di riuʃịre a prɛ̣ndere la patɛ̣nte di ɡwịda."}]},{"lesson":6,"range":[501,600],"items":[{"n":501,"zh":"你必须通过考试才能拿到驾照。","en":"You must pass a test before you can get a driver's license.","it":"Devi passare il test prima di poter ottenere la patente di guida.","ipa":"dẹvi pasːạre il tɛ̣st prịma di pọter otːenẹre la patɛ̣nte di ɡwịda."},{"n":502,"zh":"我昨天上班迟到了。我得去看牙医。","en":"I was late for work yesterday. I had to go to the dentist.","it":"Ieri, ho fatto tardi al lavoro. Sono dovuto andare dal dentista.","ipa":"jẹri, ɔ fạtːo tạrdi al lavọro. sọno dovụto andạre dal dentịsta."},{"n":503,"zh":"昨晚我们不得不步行回家。没公交车。","en":"We had to walk home last night. There were no buses.","it":"Siamo dovuti andare a casa a piedi ieri sera. Non c'erano autobus.","ipa":"sjạmo dovụti andạre a kạz‿ a pjẹdi jẹri sẹra. non ʧẹrano ạwtobus."},{"n":504,"zh":"你明天什么时候去看牙医？","en":"What time do you have to go to the dentist tomorrow?","it":"A che ora devi andare dal dentista domani?","ipa":"a ke ọra dẹvi andạre dal dentịsta domạni?"},{"n":505,"zh":"安德玛周六必须工作吗？","en":"Does Amanda have to work on Saturdays?","it":"Amanda deve lavorare di sabato?","ipa":"amạnda dẹve lavorạre di sạbato?"},{"n":506,"zh":"他们为什么得早点离开派对？","en":"Why did they have to leave the party early?","it":"Perchè sono dovuti andare via prima dalla festa?","ipa":"perkɛ̣ sọno dovụti andạre vịa prịma dạlːa fɛ̣sta?"},{"n":507,"zh":"我明天不用上班，所以不用早起。","en":"I'm not working tomorrow, so I don't have to get up early.","it":"Domani non lavoro, quindi non devo alzarmi presto.","ipa":"domạni non lavọro, kwịndi non dẹvo alʦạrmi prɛ̣sto."},{"n":508,"zh":"艾伦不用太努力工作。实际上，他有个轻松的工作。","en":"Alan doesn't have to work very hard. Actually, he's got an easy job.","it":"Alan non deve lavorare sodo. A dire il vero, ha un lavoro davvero semplice.","ipa":"ạlan non dẹve lavorạre sɔ̣do. a dịre il vẹro, a un lavọro davːẹro sẹmpliʧe."},{"n":509,"zh":"我们没等多久就等到公交车了；几分钟就来了。","en":"We didn't have to wait very long for the bus; it came in a few minutes.","it":"Non abbiamo dovuto aspettare a lungo l'autobus, è arrivato in pochi minuti.","ipa":"non abːjạmo dovụto aspetːạre a lụŋɡo lạwtobus, ɛ̣ arːivạto in pɔ̣ki minụti."},{"n":510,"zh":"在很多国家，男人必须服兵役。","en":"In many countries, men must do military service.","it":"In molti paesi, gli uomini devono fare il servizio militare.","ipa":"in mọlti paẹzi, ʎːi wọmini dẹvono fạre il servịʦjo militạre."},{"n":511,"zh":"我的视力不太好。我得戴眼镜。","en":"My eyes are not very good. I have to wear glasses.","it":"Non ci vedo benissimo. Devo mettere gli occhiali.","ipa":"non ʧi vẹdo benịsːimo. dẹvo mɛ̣tːere ʎːi okːjạli."},{"n":512,"zh":"课程结束时所有学生都得参加考试。","en":"At the end of the course all the students had to take a test.","it":"Alla fine del corso tutti gli studenti devono sostenere un esame.","ipa":"ạlːa fịne dɛl kọrso tụtːi ʎːi studɛ̣nti dẹvono sostenẹre un ezạme."},{"n":513,"zh":"莉拉在学文学。她得读很多书。","en":"Layla is studying literature. She has to read a lot of books.","it":"Layla studia letteratura. Deve leggere molti libri.","ipa":"(…) stụdja letːeratụra. dẹve lɛ̣dʤere mọlti lịbri."},{"n":514,"zh":"哈桑不太懂英语。你得慢慢和他说话。","en":"Hassan doesn't understand much English. You have to speak very slowly to him.","it":"Hassan non capisce molto l'inglese. Devi parlare molto lentamente con lui.","ipa":"asːạn non kapịʃe mọlto linɡlẹze. dẹvi parlạre mọlto lentamɛ̣nte kon lụj."},{"n":515,"zh":"巴巴拉很少在家。她得为工作出差。","en":"Barbara isn't at home much. She has to travel a lot for her job.","it":"Barbara non passa molto tempo a casa. Deve viaggiare molto a causa del suo lavoro.","ipa":"bạrbara non pạsːa mọlto tẹmpo a kạza. dẹve vjadʤạre mọlto a kạwza dɛl sụo lavọro."},{"n":516,"zh":"网球你得把球打过网。","en":"In tennis you have to hit the ball over the net.","it":"A tennis devi tirare la palla oltre la rete.","ipa":"a tɛ̣nːis dẹvi tirạre la pạlːa ọltre la rẹte."},{"n":517,"zh":"昨晚我们不得不步行回家。没公交车。","en":"We had to walk home last night. There were no buses.","it":"Siamo dovuti andare a casa a piedi ieri sera. Non c'erano autobus.","ipa":"sjạmo dovụti andạre a kạz‿ a pjẹdi jẹri sẹra. non ʧẹrano ạwtobus."},{"n":518,"zh":"很晚了。我得走了。明天见。","en":"It's late. I have to go now. I'll see you tomorrow.","it":"È tardi. Devo andare adesso. Ci vediamo domani.","ipa":"ɛ̣ tạrdi. dẹvo andạre adɛ̣sːo. ʧi vedjạmo domạni."},{"n":519,"zh":"我昨天下班后去商店了。我得买些食物。","en":"I went to the store after work yesterday. I had to buy some food.","it":"Ieri dopo il lavoro, sono andato al negozio di alimentari. Dovevo comprare del cibo.","ipa":"jẹri dɔ̣po il lavọro, sọno andạto al neɡɔ̣ʦjo di alimentạri. dovẹvo komprạre dɛl ʧịbo."},{"n":520,"zh":"这趟火车不到市中心。你得到下一站换乘。","en":"This train doesn't go all the way downtown. You have to change at the next station.","it":"Questo treno non va fino in centro [città]. Devi cambiare alla prossima stazione.","ipa":"kwɛ̣sto trẹno non va fịno in ʧɛ̣ntro [ʧitːạ]. dẹvi kambjạre ạlːa prɔ̣sːima staʦjọne."},{"n":521,"zh":"昨天我们考试了，要答十道题中的六道。","en":"We took a test yesterday. We had to answer six (6) questions out of ten (10).","it":"Ieri abbiamo sostenuto un esame. Dovevamo rispondere almeno a sei (6) domande su dieci (10).","ipa":"jẹri abːjạmo sostenụto un ezạme. dovevạmo rispọndere almẹno a sɛ̣j (6) domạnde su djẹʧi (10)."},{"n":522,"zh":"我要去睡觉了，明天得早起。","en":"I'm going to bed. I have to get up early tomorrow.","it":"Andrò a letto. Devo svegliarmi presto domani.","ipa":"andrɔ̣ a lɛ̣tːo. dẹvo sveʎːjạrmi prɛ̣sto domạni."},{"n":523,"zh":"拉维和他的表妹塔拉今晚不能和我们一起出去，他们得照顾塔拉的弟弟。","en":"Ravi and his cousin Tara can't go out with us tonight. They have to take care of Tara's little brother.","it":"Ravi e sua cugina Tara non possono uscire con noi stasera. Devono prendersi cura del fratellino di Tara.","ipa":"rạvi e sụa kuʤịna tạra non pɔ̣sːono uʃịre kon nọj stasẹra. dẹvono prɛ̣ndersi kụra dɛl fratɛlːịno di tạra."},{"n":524,"zh":"我明天得早起。——你什么时候得起床？","en":"I have to get up early tomorrow. — What time do you have to get up?","it":"Mi devo alzare presto domani. A che ora ti devi alzare?","ipa":"mi dẹvo alʦạre prɛ̣sto domạni. a ke ọra ti dẹvi alʦạre?"},{"n":525,"zh":"克里斯等了好久。——他得等多久？","en":"Chris had to wait a long time. — How long did he have to wait?","it":"Christian ha dovuto aspettare a lungo. Quanto ha dovuto aspettare?","ipa":"krịstjan a dovụto aspetːạre a lụŋɡo. kwạnto a dovụto aspetːạre?"},{"n":526,"zh":"克莱尔得去某个地方。——她得去哪儿？","en":"Claire has to go somewhere. — Where does she have to go?","it":"Claire deve andare da qualche parte. Dove deve andare?","ipa":"(…) dẹve andạre da kwạlke pạrte. dọve dẹve andạre?"},{"n":527,"zh":"我们得付很多钱。——你们得付多少钱？","en":"We had to pay a lot of money. — How much money did you have to pay?","it":"Abbiamo dovuto pagare un mucchio di soldi. Quanti soldi avete dovuto pagare?","ipa":"abːjạmo dovụto paɡạre un mụkːjo di sɔ̣ldi. kwạnti sɔ̣ldi avẹte dovụto paɡạre?"},{"n":528,"zh":"我得做些工作。——你具体得做什么？","en":"I have to do some work. — What exactly do you have to do?","it":"Devo sbrigare del lavoro. Cosa devi fare esattamente?","ipa":"dẹvo zbriɡạre dɛl lavọro. kɔ̣za dẹvi fạre ezatːamɛ̣nte?"},{"n":529,"zh":"他们得早点离开。——为什么他们得早点离开？","en":"They had to leave early. — Why did they have to leave early?","it":"Sono dovuti andare via prima. Perchè sono dovuti andare via in anticipo?","ipa":"sọno dovụti andạre vịa prịma. perkɛ̣ sọno dovụti andạre vịa in antịʧipo?"},{"n":530,"zh":"矢吹得去莫斯科。——他什么时候得去？","en":"Minoru has to go to Moscow. — When does he have to go?","it":"Minoru deve andare a Mosca. — Quando deve andarci?","ipa":"minɔ̣ru dẹve andạre a mọska. kwạndo dẹve andạrʧi?"},{"n":531,"zh":"你为什么要出去？你不必出去。","en":"Why are you going out? You don't have to go out.","it":"Perchè stai uscendo? Non c'è bisogno che tu esca.","ipa":"perkɛ̣ stạj uʃɛ̣ndo? non ʧɛ̣ bizọɲːo ke tu ẹska."},{"n":532,"zh":"美久米为什么在等？她不必等。","en":"Why is Megumi waiting? She doesn't have to wait.","it":"Perchè Megumi sta aspettando? Non è necessario che aspetti.","ipa":"perkɛ̣ meɡụmi st‿ aspetːạndo? non ɛ̣ neʧesːạrjo ke aspɛ̣tːi."},{"n":533,"zh":"你为什么早起？你不必那么早起床。","en":"Why did you get up early? You didn't have to get up so early.","it":"Perchè ti sei alzato presto? Non dovevi mica svegliarti così presto.","ipa":"perkɛ̣ ti sɛ̣j alʦạto prɛ̣sto? non dovẹvi mịka sveʎːjạrti kozị prɛ̣sto."},{"n":534,"zh":"戴维为什么那么努力工作？他不必那么努力。","en":"Why is David working so hard? He doesn't have to work so hard.","it":"Perchè David sta lavorando così duramente? Non c'è bisogno che lavori così assiduamente.","ipa":"perkɛ̣ dạvid sta lavorạndo kozị duramɛ̣nte? non ʧɛ̣ bizọɲːo ke lavọri kozị asːidwamɛ̣nte."},{"n":535,"zh":"你为什么现在想离开？我们现在不必离开。","en":"Why do you want to leave now? We don't have to leave now.","it":"Perchè vuoi andare via adesso? Non è necessario andare via adesso.","ipa":"perkɛ̣ vwɔ̣j andạre vịa adɛ̣sːo? non ɛ̣ neʧesːạrjo andạre vịa adɛ̣sːo."},{"n":536,"zh":"他们为什么告诉我我知道的事情？他们不必告诉我那个。","en":"Why did they tell me something I already know? They didn't have to tell me that.","it":"Perchè mi hanno detto qualcosa che già so? Non c'era bisogno che me lo dicessero.","ipa":"perkɛ̣ mi ạnːo dɛ̣tːo kwalkɔ̣za ke ʤạ sɔ? non ʧẹra bizọɲːo ke mɛ lo diʧɛ̣sːero."},{"n":537,"zh":"我每天得开车五十英里去上班。> 我每天得开车八十公里去上班。","en":"I have to drive fifty (50) miles to work every day. > I have to drive eighty (80) kilometers to work every day.","it":"Ogni giorno per andare al lavoro, devo guidare per ottanta (80) chilometri.","ipa":"ɔ̣ɲːi ʤọrno pɛr andạre al lavọro, dẹvo ɡwidạre pɛr otːạnta (80) kilɔ̣metri."},{"n":538,"zh":"我每天得坐地铁去上课。","en":"I have to take the subway to class every day.","it":"Per andare a lezione, devo prendere la metro ogni giorno.","ipa":"pɛr andạre a leʦjọne, dẹvo prɛ̣ndere la mẹtro ɔ̣ɲːi ʤọrno."},{"n":539,"zh":"我昨天得和家人吃晚饭。","en":"I had to have dinner with my family yesterday.","it":"Ieri, ho dovuto cenare con la mia famiglia.","ipa":"jẹri, ɔ dovụto ʧenạre kon la mịa famịʎːja."},{"n":540,"zh":"上周我得去医院看望祖父。","en":"I had to visit my grandfather in the hospital last week.","it":"Settimana scorsa, ho dovuto fare visita a mio nonno in ospedale.","ipa":"setːimạna skọrsa, ɔ dovụto fạre vịzit‿ a mịo nɔ̣nːo in ospedạle."},{"n":541,"zh":"我小时候得上的课好多。","en":"I had to take a lot of classes when I was younger.","it":"Ho dovuto prendere molte lezioni quando ero più giovane.","ipa":"ɔ dovụto prɛ̣ndere mọlte leʦjọni kwạndo ẹro piụ ʤọvane."},{"n":542,"zh":"想喝咖啡吗？","en":"Would you like some coffee?","it":"Ti andrebbe un caffè?","ipa":"ti andrɛ̣bːe un kafːɛ̣?"},{"n":543,"zh":"想吃块糖吗？","en":"Would you like a piece of candy?","it":"Vuoi una caramella?","ipa":"vwɔ̣j ụna karamɛ̣lːa?"},{"n":544,"zh":"你想喝什么，茶还是咖啡？","en":"Which would you like, tea or coffee?","it":"Cosa preferisci, il tè o il caffè?","ipa":"kɔ̣za preferịʃi, il tɛ̣ o il kafːɛ̣?"},{"n":545,"zh":"想去散步吗？","en":"Would you like to go for a walk?","it":"Ti va di andare a fare una passeggiata?","ipa":"ti va di andạre a fạre ụna pasːedʤạta?"},{"n":546,"zh":"周日想和我们一起吃晚饭吗？","en":"Would you like to have dinner with us on Sunday?","it":"Ti andrebbe di cenare con noi domenica?","ipa":"ti andrɛ̣bːe di ʧenạre kon nọj domẹnika?"},{"n":547,"zh":"我周日想吃晚饭。","en":"I'd love to have dinner on Sunday.","it":"Mi piacerebbe molto cenare con voi domenica.","ipa":"mi pjaʧerɛ̣bːe mọlto ʧenạre kon vọj domẹnika."},{"n":548,"zh":"今晚你想做什么？","en":"What would you like to do tonight?","it":"Cosa vorresti fare stasera?","ipa":"kɔ̣za vorːɛ̣sti fạre stasẹra?"},{"n":549,"zh":"我渴了，想喝点东西。","en":"I'm thirsty. I'd like a drink.","it":"Ho sete, vorrei qualcosa da bere.","ipa":"ɔ sẹte, vorːẹj kwalkɔ̣za da bẹre."},{"n":550,"zh":"我想了解一下酒店的信息，可以吗？","en":"I'd like some information about hotels, please.","it":"Vorrei avere delle informazioni circa gli hotel, per favore.","ipa":"vorːẹj avẹre dɛ̣lːe informaʦjọni ʧịrka ʎːi ɔtẹl, pɛr favọre."},{"n":551,"zh":"我感觉累了，今晚想待在家里。","en":"I'm feeling tired. I'd like to stay home tonight.","it":"Mi sento stanco. Vorrei stare a casa stasera.","ipa":"mi sɛ̣nto stạŋko. vorːẹj stạre a kạza stasẹra."},{"n":552,"zh":"今晚你想去看电影吗？","en":"Would you like to go to the movies tonight?","it":"Ti andrebbe di andare al cinema stasera?","ipa":"ti andrɛ̣bːe di andạre al ʧịnema stasẹra?"},{"n":553,"zh":"你喜欢看电影吗？——是的，我经常去看电影。","en":"Do you like to go to the movies? — Yes, I go to the movies a lot.","it":"Ti piace andare al cinema? — Sì, ci vado molto spesso.","ipa":"ti pjạʧe andạre al ʧịnema? — sị, ʧi vạdo mọlto spɛ̣sːo."},{"n":554,"zh":"请给我一杯橙汁。> 我能喝橙汁吗？","en":"I'd like an orange juice, please. > Can I have an orange juice?","it":"Vorrei un succo d'arancia, per favore. > Posso avere un succo d'arancia?","ipa":"vorːẹj un sụkːo darạɲʧa, pɛr favọre. > pɔ̣sːo avẹre un sụkːo darạɲʧa?"},{"n":555,"zh":"我喜欢橙汁。","en":"I like orange juice.","it":"Mi piace la spremuta d'arancia.","ipa":"mi pjạʧe la spremụta darạɲʧa."},{"n":556,"zh":"下个周末你想做什么？","en":"What would you like to do next weekend?","it":"Cosa ti piacerebbe fare il prossimo fine settimana?","ipa":"kɔ̣za ti pjaʧerɛ̣bːe fạre il prɔ̣sːimo fịne setːimạna?"},{"n":557,"zh":"你周末喜欢做什么？","en":"What do you like to do on weekends?","it":"Cosa ti piace fare nei fine settimana?","ipa":"kɔ̣za ti pjạʧe fạre nɛ̣j fịne setːimạna?"},{"n":558,"zh":"你今晚想去看电影。也许艾米丽会和你一起去。","en":"You want to go to the movies tonight. Perhaps Emily will go with you.","it":"Tu vuoi andare al cinema stasera. Forse Emilia verrà con te.","ipa":"tu vwɔ̣j andạre al ʧịnema stasẹra. fọrs‿ emịlja verːạ kon tɛ."},{"n":559,"zh":"今晚你想和我一起去看电影吗？","en":"Would you like to go to the movies with me tonight?","it":"Ti piacerebbe andare al cinema con me stasera?","ipa":"ti pjaʧerɛ̣bːe andạre al ʧịnema kon mɛ stasẹra?"},{"n":560,"zh":"你明天想打网球。也许文杰也会去打。","en":"You want to play tennis tomorrow. Perhaps Wenjie will play, too.","it":"Vuoi giocare a tennis domani. Forse anche Wenjie giocherà.","ipa":"vwɔ̣j ʤokạre a tɛ̣nːis domạni. fọrse ạŋke (…) ʤokerạ."},{"n":561,"zh":"明天你想和我打网球吗？","en":"Would you like to play tennis with me tomorrow?","it":"Ti andrebbe di giocare a tennis con me domani?","ipa":"ti andrɛ̣bːe di ʤokạre a tɛ̣nːis kon mɛ domạni?"},{"n":562,"zh":"你下周有张多余的演唱会门票。也许Helen会来。","en":"You have an extra ticket for a concert next week. Perhaps Helen will come.","it":"Hai un biglietto in più per il concerto di settimana prossima. Magari Elena ci verrà.","ipa":"ạj un biʎːjɛ̣tːo in piụ pɛr il koɲʧɛ̣rto di setːimạna prɔ̣sːima. maɡạri ɛ̣lena ʧi verːạ."},{"n":563,"zh":"你想下周和我一起去听音乐会吗？","en":"Would you like to go to a concert with me next week?","it":"Ti va di venire con me a un concerto la settimana prossima?","ipa":"ti va di venịre kon mɛ a un koɲʧɛ̣rto la setːimạna prɔ̣sːima?"},{"n":564,"zh":"正在下雨，Yaqin要出去。她没带伞，但你带了。","en":"It's raining, and Yaqin's going out. She doesn't have an umbrella, but you have one.","it":"Piove e Yaqin sta uscendo. Lei non ha un ombrello, ma tu ne hai uno.","ipa":"pjɔ̣v‿ e (…) sta uʃɛ̣ndo. lɛ̣j non a un ombrɛ̣lːo, ma tu ne ạj ụno."},{"n":565,"zh":"你想借我的伞吗？","en":"Would you like to borrow my umbrella?","it":"Vuoi prendere in prestito il mio ombrello?","ipa":"vwɔ̣j prɛ̣ndere in prɛ̣stito il mịo ombrɛ̣lːo?"},{"n":566,"zh":"你想喝点什么？","en":"What would you like to drink?","it":"Cosa prendi da bere?","ipa":"kɔ̣za prɛ̣ndi da bẹre?"},{"n":567,"zh":"你想出去散步吗？","en":"Would you like to go out for a walk?","it":"Desideri uscire a fare una passeggiata?","ipa":"dezịderi uʃịre a fạre ụna pasːedʤạta?"},{"n":568,"zh":"我喜欢洋葱，但不常吃。","en":"I like onions, but I don't eat them very often.","it":"Mi piacciono le cipolle, ma non le mangio molto spesso.","ipa":"mi pjạtʧono le ʧipọlːe, ma non le mạɲʤo mọlto spɛ̣sːo."},{"n":569,"zh":"你想今晚什么时候吃饭？","en":"What time would you like to have dinner tonight?","it":"A che ora vorresti cenare stasera?","ipa":"a ke ọra vorːɛ̣sti ʧenạre stasẹra?"},{"n":570,"zh":"你想吃点什么吗？","en":"Would you like something to eat?","it":"Desideri qualcosa da mangiare?","ipa":"dezịderi kwalkɔ̣za da maɲʤạre?"},{"n":571,"zh":"你喜欢你的新工作吗？","en":"Do you like your new job?","it":"Ti piace il tuo nuovo lavoro?","ipa":"ti pjạʧe il tụo nwɔ̣vo lavọro?"},{"n":572,"zh":"我累了，我想现在就去睡觉。","en":"I'm tired. I'd like to go to bed now.","it":"Sono stanco (♀stanca). Adesso, vorrei andare a letto.","ipa":"sọno stạŋko (♀stạŋka). adɛ̣sːo, vorːẹj andạre a lɛ̣tːo."},{"n":573,"zh":"请给我一些饺子。","en":"I'd like some dumplings, please.","it":"Vorrei dei ravioli, per favore.","ipa":"vorːẹj dẹj ravjɔ̣li, pɛr favọre."},{"n":574,"zh":"你喜欢什么类型的音乐？","en":"What kind of music do you like?","it":"Che tipo di musica ti piace?","ipa":"ke tịpo di mụzika ti pjạʧe?"},{"n":575,"zh":"Heuiyeon喜欢坐在地上。她不想坐在椅子上。","en":"Heuiyeon likes to sit on the floor. She doesn't want to sit on a chair.","it":"A Heuiyeon piace sedersi per terra. Lei non vuole sedersi sulla sedia.","ipa":"a (…) pjạʧe sedẹrsi pɛr tɛ̣rːa. lɛ̣j non vwɔ̣le sedẹrsi sụlːa sẹdja."},{"n":576,"zh":"我宁愿坐在地上。> 我更愿意坐在地上。","en":"I'd rather sit on the floor. > I would prefer to sit on the floor.","it":"Preferisco sedermi sul pavimento. > Preferirei sedermi per terra.","ipa":"preferịsko sedẹrmi sul pavimɛ̣nto. > preferirẹj sedẹrmi pɛr tɛ̣rːa."},{"n":577,"zh":"我其实不想出去。我宁愿待在家里。","en":"I don't really want to go out. I'd rather stay at home.","it":"Non ho molta voglia di uscire. Preferisco stare a casa.","ipa":"non ɔ mọlta vọʎːja di uʃịre. preferịsko stạre a kạza."},{"n":578,"zh":"我们现在走吗？—— 不，还不行。我宁愿稍后再走。","en":"Should we go now? — No, not yet. I'd rather wait until later.","it":"Dobbiamo andare adesso? — No, non ancora. Preferirei aspettare ancora.","ipa":"dobːjạmo andạre adɛ̣sːo? — nɔ, non aŋkọra. preferirẹj aspetːạre aŋkọra."},{"n":579,"zh":"我现在想走，但Gary宁愿稍后再走。","en":"I'd like to go now, but Gary would rather wait until later.","it":"Vorrei andare adesso, però Gary preferirebbe attendere ulteriormente.","ipa":"vorːẹj andạre adɛ̣sːo, perɔ̣ (…) preferirɛ̣bːe atːɛ̣ndere ulterjormɛ̣nte."},{"n":580,"zh":"我不喜欢迟到。我宁愿早点到。","en":"I don't like to be late. I'd rather be early.","it":"Non mi piace essere in ritardo. Preferirei essere in anticipo.","ipa":"non mi pjạʧ‿ ɛ̣sːere in ritạrdo. preferirẹj ɛ̣sːere in antịʧipo."},{"n":581,"zh":"我感觉累了。今晚不想出去。","en":"I'm feeling tired. I'd rather not go out tonight.","it":"Sono stanco. Preferirei non uscire stasera.","ipa":"sọno stạŋko. preferirẹj non uʃịre stasẹra."},{"n":582,"zh":"吉桑感觉累了。他今晚不想出去。","en":"Jisang is feeling tired. He'd rather not go out tonight.","it":"Jisang si sente stanco. Preferirebbe non uscire stasera.","ipa":"(…) si sɛ̣nte stạŋko. preferirɛ̣bːe non uʃịre stasẹra."},{"n":583,"zh":"我们不饿。现在不想吃东西。","en":"We're not hungry. We'd rather not eat yet.","it":"Non abbiamo fame. Per adesso, preferiamo non mangiare.","ipa":"non abːjạmo fạme. pɛr adɛ̣sːo, preferjạmo non maɲʤạre."},{"n":584,"zh":"你今晚想出去吗？——不想。","en":"Would you like to go out tonight? — I'd rather not.","it":"Ti andrebbe di uscire stasera? — Preferirei di no.","ipa":"ti andrɛ̣bːe di uʃịre stasẹra? — preferirẹj di nɔ."},{"n":585,"zh":"你想喝牛奶还是果汁？——请给我果汁。","en":"Would you rather have milk or juice? — Juice, please.","it":"Preferiresti bere del latte o del succo? — Del succo, per favore.","ipa":"preferirɛ̣sti bẹre dɛl lạtːe o dɛl sụkːo? — dɛl sụkːo, pɛr favọre."},{"n":586,"zh":"你宁愿去看电影还是在家看DVD？","en":"Which would you rather do: go to the movies or watch a DVD at home?","it":"Cosa preferiresti fare: andare al cinema o guardare un DVD a casa?","ipa":"kɔ̣za preferirɛ̣sti fạre: andạre al ʧịnema o ɡwardạre un (…) a kạza?"},{"n":587,"zh":"我宁愿站着也不愿坐着。","en":"I'd rather stand than sit.","it":"Preferirei stare in piedi anzichè sedermi.","ipa":"preferirẹj stạre in pjẹdi anʦikɛ̣ sedẹrmi."},{"n":588,"zh":"詹尼莎不想出去。","en":"Jessica would rather not go out.","it":"Jessica preferisce non uscire.","ipa":"(…) preferịʃe non uʃịre."},{"n":589,"zh":"我宁愿坐着也不愿站着。","en":"I'd prefer to sit than stand.","it":"Preferirei sedermi che stare in piedi.","ipa":"preferirẹj sedẹrmi ke stạre in pjẹdi."},{"n":590,"zh":"我宁愿坐着而不是站着。","en":"I'd prefer to sit rather than stand.","it":"Preferirei sedermi piuttosto che stare in piedi.","ipa":"preferirẹj sedẹrmi piutːɔ̣sto ke stạre in pjẹdi."},{"n":591,"zh":"赵蓉宁愿不去。","en":"Zhirong would prefer not to go out.","it":"Zhirong preferirebbe non uscire.","ipa":"(…) preferirɛ̣bːe non uʃịre."},{"n":592,"zh":"我宁愿出去也不愿待在家。","en":"I'd rather go out than stay home.","it":"Preferirei uscire invece che stare a casa.","ipa":"preferirẹj uʃịre invẹʧe ke stạre a kạza."},{"n":593,"zh":"我宁愿要狗也不愿要猫。","en":"I'd rather have a dog than a cat.","it":"Preferirei avere un cane al posto di un gatto.","ipa":"preferirẹj avẹre un kạne al pɔ̣sto di un ɡạtːo."},{"n":594,"zh":"我们宁愿去看电影也不愿在家看DVD。","en":"We'd rather go to the movies than watch a DVD at home.","it":"Più che guardare un DVD a casa, preferiremmo andare al cinema.","ipa":"piụ ke ɡwardạre un (…) a kạza, preferirɛ̣mːo andạre al ʧịnema."},{"n":595,"zh":"我现在宁愿在家而不是在这里。","en":"I'd rather be at home right now than here.","it":"Preferirei essere a casa in questo istante anziché qui.","ipa":"preferirẹj ɛ̣sːere a kạza in kwɛ̣sto istạnte anʦikɛ̣ kwị."},{"n":596,"zh":"你不想看电视吗？——不，我宁愿读我的小说。","en":"Don't you want to watch TV? — No, I'd rather read my novel.","it":"Non vuoi guardare la televisione? — No, preferirei leggere il mio romanzo.","ipa":"non vwɔ̣j ɡwardạre la televizjọne? — nɔ, preferirẹj lɛ̣dʤere il mịo romạnʦo."},{"n":597,"zh":"你想喝点茶吗？——嗯，如果你有，我宁愿喝咖啡。","en":"Would you like some tea? — Well, I'd rather have coffee if you have some.","it":"Desideri del tè? — Mah, se ne hai un po', preferirei del caffè.","ipa":"dezịderi dɛl tɛ̣? — ma, se ne ạj un pɔ, preferirẹj dɛl kafːɛ̣."},{"n":598,"zh":"我们现在出去好吗？——我宁愿等到雨停了再出去。","en":"Should we go out now? — I'd rather wait until it stops raining.","it":"Dovremmo uscire adesso? — Preferirei aspettare fino a che non smetta di piovere.","ipa":"dovrɛ̣mːo uʃịre adɛ̣sːo? — preferirẹj aspetːạre fịno a ke non smɛ̣tːa di pjɔ̣vere."},{"n":599,"zh":"我们现在吃饭，还是稍后再吃？","en":"Should we have dinner now, or wait until later?","it":"Dovremmo cenare adesso o aspettare ancora un po'?","ipa":"dovrɛ̣mːo ʧenạre adɛ̣sː‿ o aspetːạre aŋkọra un pɔ?"},{"n":600,"zh":"你想喝杯果汁还是水？","en":"Would you like a glass of juice, or some water?","it":"Cosa preferisci un succo o dell'acqua?","ipa":"kɔ̣za preferịʃi un sụkː‿ o dɛlːạkwa?"}]},{"lesson":7,"range":[601,700],"items":[{"n":601,"zh":"想去看电影还是只看会儿电视？","en":"Do you want to go to the movies, or just watch TV?","it":"Vuoi andare al cinema o soltanto guardare la televisione?","ipa":"vwɔ̣j andạre al ʧịnema, o soltạnto ɡwardạre la televizjọne?"},{"n":602,"zh":"我们今晚给哥哥打电话，还是你宁愿明天早上再打？","en":"Should we call your brother tonight, or would you rather wait until tomorrow morning?","it":"Dovremmo chiamare tuo fratello stasera, o preferisci aspettare fino a domani?","ipa":"dovrɛ̣mːo kjamạre tụo fratɛ̣lːo stasẹra, o preferịʃi aspetːạre fịno a domạni?"},{"n":603,"zh":"我今晚宁愿待在家里。我不想去外面。","en":"I'd rather stay home tonight. I'd prefer not to go out.","it":"Mi piacerebbe stare a casa stasera. Preferirei non uscire.","ipa":"mi pjaʧerɛ̣bːe stạre a kạza stasẹra. preferirẹj non uʃịre."},{"n":604,"zh":"我们步行回家，还是你宁愿打车？","en":"Should we walk home, or would you rather take a taxi?","it":"Dobbiamo andare a casa a piedi o preferisci prendere un taxi?","ipa":"dobːjạmo andạre a kạz‿ a pjẹdi o preferịʃi prɛ̣ndere un tạksi?"},{"n":605,"zh":"你想让我陪你一起去，还是你更愿意自己一个人去？","en":"Do you want me to come with you, or would you prefer to go alone?","it":"Vuoi che venga con te, o preferisci andare da solo (♀sola)?","ipa":"vwɔ̣j ke vẹŋɡa kon tɛ, o preferịʃi andạre da sọlo (♀sọla)?"},{"n":606,"zh":"艾婷不想上大学。她宁愿找份工作。","en":"Yiting doesn't want to go to college. She'd rather get a job.","it":"Yiting non vuole frequentare l'università. Preferirebbe trovare un impiego.","ipa":"(…) non vwɔ̣le frekwentạre luniversitạ. preferirɛ̣bːe trovạre un impjẹɡo."},{"n":607,"zh":"我能帮你拿行李吗？——不用了，谢谢。我宁愿自己来。","en":"Can I help you with your suitcase? — No, thank you. I'd rather do it myself.","it":"Posso aiutarti con la [tua] valigia? — No, grazie. Preferirei fare da me.","ipa":"pɔ̣sːo ajutạrti kon la [tụa] valịʤa? — nɔ, ɡrạʦje. preferirẹj fạre da mɛ."},{"n":608,"zh":"我不想给他打电话。我宁愿给他发个邮件。","en":"I'd rather not call him. I'd prefer to write him an email.","it":"Preferirei non chiamarlo. Preferiei scrivergli una mail.","ipa":"preferirẹj non kjamạrlo. preferirẹj skrịverʎːi ụna mạil."},{"n":609,"zh":"你更想成为什么：公交车司机还是飞行员？","en":"Which would you prefer to be: a bus driver or an airplane pilot?","it":"Cosa preferiresti essere: un autista (♀un'autista) di autobus o un pilota (♀una pilota) di aerei?","ipa":"kɔ̣za preferirɛ̣sti ɛ̣sːere: un awtịsta (♀unawtịsta) di ạwtobus o un pilɔ̣ta (♀ụna pilɔ̣ta) di aɛ̣rej?"},{"n":610,"zh":"我宁愿成为飞行员，而不是公交车司机。","en":"I'd rather be an airplane pilot than a bus driver.","it":"Preferirei essere un pilota (♀una pilota) di aerei che un autista (♀un'autista) di autobus.","ipa":"preferirẹj ɛ̣sːere un pilɔ̣ta (♀ụna pilɔ̣ta) di aɛ̣rej ke un awtịsta (♀unawtịsta) di ạwtobus."},{"n":611,"zh":"你更想成为什么：记者还是老师？","en":"Which would you prefer to be: a journalist or a school teacher?","it":"Cosa preferiresti essere: un giornalista (♀una giornalista) o un insegnante (♀un'insegnante)?","ipa":"kɔ̣za preferirɛ̣sti ɛ̣sːere: un ʤornalịsta (♀ụna ʤornalịsta) o un inseɲːạnte (♀uninseɲːạnte)?"},{"n":612,"zh":"我宁愿成为记者，而不是老师。","en":"I'd rather be a journalist than a school teacher.","it":"Più che un insegnante (♀un'insegnante), preferirei essere un giornalista (♀una giornalista).","ipa":"piụ ke un inseɲːạnte (♀uninseɲːạnte), preferirẹj ɛ̣sːere un ʤornalịsta (♀ụna ʤornalịsta)."},{"n":613,"zh":"你更愿意住在哪里：大城市还是小城镇？","en":"Where would you prefer to live: in a big city or a small town?","it":"Dove preferiresti vivere: in una grande città o in un paesino?","ipa":"dọve preferirɛ̣sti vịvere: in ụna ɡrạnde ʧitːạ o in un paezịno?"},{"n":614,"zh":"我宁愿住在大城市，而不是小城镇。","en":"I'd rather live in a big city than a small town.","it":"Preferirei vivere in una grande città rispetto a un paese piccolo.","ipa":"preferirẹj vịvere in ụna ɡrạnde ʧitːạ rispɛ̣tːo a un paẹze pịkːolo."},{"n":615,"zh":"你更想拥有什么：小房子还是大房子？","en":"Which would you prefer to have: a small house or a big one?","it":"Cosa preferiresti avere: una casa piccola o grande?","ipa":"kɔ̣za preferirɛ̣sti avẹre: ụna kạza pikːɔ̣la o ɡrạnde?"},{"n":616,"zh":"我宁愿有大房子，而不是小房子。","en":"I'd rather have a big house than a small one.","it":"Preferirei avere una casa grande piuttosto che piccola.","ipa":"preferirẹj avẹre ụna kạza ɡrạnde piutːɔ̣sto ke pikːɔ̣la."},{"n":617,"zh":"你更想学习什么：电子学还是哲学？","en":"Which would you prefer to study: electronics or philosophy?","it":"Cosa preferiresti studiare: elettronica o filosofia?","ipa":"kɔ̣za preferirɛ̣sti studjạre: eletːrɔ̣nika o filozofịa?"},{"n":618,"zh":"我宁愿学习哲学，而不是电子学。","en":"I'd rather study philosophy than electronics.","it":"Preferirei studiare filosofia al posto di elettronica.","ipa":"preferirẹj studjạre filozofịa al pɔ̣sto di eletːrɔ̣nika."},{"n":619,"zh":"你更想看什么：足球比赛还是电影？","en":"Which would you prefer to watch: a football game or a movie?","it":"Cosa preferiresti guardare: una partita di calcio o un film?","ipa":"kɔ̣za preferirɛ̣sti ɡwardạre: ụna partịta di kạlʧ‿ o un film?"},{"n":620,"zh":"我宁愿看电影，而不是足球比赛。","en":"I'd rather watch a movie than a football game.","it":"Preferirei guardare un film invece di una partita di calcio.","ipa":"preferirẹj ɡwardạre un film invẹʧe di ụna partịta di kạlʧo."},{"n":621,"zh":"过来看看这个。——这是什么？","en":"Come here and look at this. — What is it?","it":"Vieni qua e guarda qui. — Cos'è?","ipa":"vjẹni kwa e ɡwạrda kwị. — kozɛ̣?"},{"n":622,"zh":"我不想和你说话。走开！","en":"I don't want to talk to you. Go away!","it":"Non voglio parlare con te. Vai via!","ipa":"non vɔ̣ʎːjo parlạre kon tɛ. vạj vịa!"},{"n":623,"zh":"我还没准备好。请等我。","en":"I'm not ready yet. Please wait for me.","it":"Non sono ancora pronto. Aspettami, per favore.","ipa":"non sọno aŋkọra prọnto. aspɛ̣tːami, pɛr favọre."},{"n":624,"zh":"请安静。我正在努力集中注意力。","en":"Please be quiet. I'm trying to concentrate.","it":"Fai silenzio per favore. Sto cercando di concentrarmi.","ipa":"fạj silɛ̣nʦjo pɛr favọre. stɔ ʧerkạndo di koɲʧentrạrmi."},{"n":625,"zh":"旅途愉快。玩得开心。旅途愉快。祝你好运！","en":"Have a good trip. Have a nice time. Have a good flight. Have fun!","it":"Fai buon viaggio. Passala alla grande. Buon volo. Divertiti.","ipa":"fạj bwɔ̣n vjạdʤo. pạsːal‿ ạlːa ɡrạnde. bwɔ̣n vọlo. divɛ̣rtiti."},{"n":626,"zh":"这里，吃点糖果。","en":"Here, have some candy.","it":"Ecco, prendi delle caramelle (dei dolcetti).","ipa":"ɛ̣kːo, prɛ̣ndi dɛ̣lːe karamɛ̣lːe (dẹj dolʧɛ̣tːi)."},{"n":627,"zh":"小心！别摔倒了！","en":"Be careful! Don't fall!","it":"Fai attenzione! Non cadere!","ipa":"fạj atːenʦjọne! non kadẹre!"},{"n":628,"zh":"请别走。和我呆在这里。","en":"Please don't go. Stay here with me.","it":"Per favore, non andare. Stai qui con me.","ipa":"pɛr favọre, non andạre. stạj kwị kon mɛ."},{"n":629,"zh":"准时到这里。别迟到。","en":"Be here on time. Don't be late.","it":"Sii puntuale. Non arrivare in ritardo.","ipa":"sịj puntwạle. non arːivạre in ritạrdo."},{"n":630,"zh":"今天天气不错。我们出去吧。","en":"It's a nice day. Let's go out.","it":"È una bella giornata. Usciamo.","ipa":"ɛ̣ ụna bɛ̣lːa ʤornạta. uʃạmo."},{"n":631,"zh":"来吧！让我们跳舞。","en":"Come on! Let's dance.","it":"Dai! Balliamo.","ipa":"dạj! balːjạmo."},{"n":632,"zh":"你准备好了吗？我们走吧。","en":"Are you ready? Let's go.","it":"Sei pronto? Andiamo.","ipa":"sɛ̣j prọnto? andjạmo."},{"n":633,"zh":"今晚让我们吃鱼吧。","en":"Let's have fish for dinner tonight.","it":"Mangiamo pesce stasera per cena.","ipa":"maɲʤạmo pẹʃe stasẹra pɛr ʧẹna."},{"n":634,"zh":"我们今晚出去吗？——不，我累了。我们待在家里吧。","en":"Should we go out tonight? — No, I'm tired. Let's stay home.","it":"Dovremmo uscire stasera? — No, sono stanco. Restiamo a casa.","ipa":"dovrɛ̣mːo uʃịre stasẹra? — nɔ, sọno stạŋko. restjạmo a kạza."},{"n":635,"zh":"天冷。我们别出去。我们待在家里吧。","en":"It's cold. Let's not go out. Let's stay home.","it":"Fa freddo. Non usciamo. Restiamo a casa.","ipa":"fa frɛ̣dːo. non uʃạmo. restjạmo a kạza."},{"n":636,"zh":"我们今晚别吃鱼了。我们吃鸡肉吧。","en":"Let's not have fish for dinner tonight. Let's have chicken.","it":"Non mangiamo pesce stasera per cena. Mangiamo il pollo.","ipa":"non maɲʤạmo pẹʃe stasẹra pɛr ʧẹna. maɲʤạmo il pọlːo."},{"n":637,"zh":"我厌倦了争论。我们不要再做了。","en":"I'm tired of arguing. Let's not do it any more.","it":"Sono stanco di litigare (discutere). Non facciamolo più.","ipa":"sọno stạŋko di litiɡạre (diskụtere). non fatʧạmolo piụ."},{"n":638,"zh":"你想打网球吗？——不，我们去游泳吧。","en":"Would you like to play tennis? — No, let's go for a swim.","it":"Ti andrebbe di giocare a tennis? — No, andiamo a farci una nuotata.","ipa":"ti andrɛ̣bːe di ʤokạre a tɛ̣nːis? — nɔ, andjạmo a fạrʧi ụna nwotạta."},{"n":639,"zh":"你想步行回家吗？——不，我们坐公交车吧。","en":"Do you want to walk home? — No, let's take the bus.","it":"Vuoi andare a casa a piedi? — No, prendiamo l'autobus.","ipa":"vwɔ̣j andạre a kạz‿ a pjẹdi? — nɔ, prendjạmo lạwtobus."},{"n":640,"zh":"我放点音乐吗？——不，我们看部电影吧。","en":"Shall I put some music on? — No, let's watch a movie.","it":"Metto un po' di musica? — No, guardiamo un film.","ipa":"mɛ̣tːo un pɔ di mụzika? — nɔ, ɡwardjạmo un film."},{"n":641,"zh":"我们在家吃晚饭吗？——不，我们去餐馆吧。","en":"Should we have dinner at home? — No, let's go to a restaurant.","it":"Dovremmo cenare a casa? — No, andiamo al ristorante.","ipa":"dovrɛ̣mːo ʧenạre a kạza? — nɔ, andjạmo al ristorạnte."},{"n":642,"zh":"你现在想去吗？——不，我们等等吧。","en":"Would you like to go now? — No, let's wait a while.","it":"Vuoi andare adesso? — No, aspettiamo un po'.","ipa":"vwɔ̣j andạre adɛ̣sːo? — nɔ, aspetːjạmo un pɔ."},{"n":643,"zh":"我等你吗？——不，不用等我。","en":"Shall I wait for you? — No, don't wait for me.","it":"Ti aspetto? — No, non aspettarmi.","ipa":"ti aspɛ̣tːo? — nɔ, non aspetːạrmi."},{"n":644,"zh":"我们现在回家吗？——不，现在还不回家。","en":"Should we go home now? — No, let's not go home yet.","it":"Dovremmo andare a casa, adesso? — No, non ancora.","ipa":"dovrɛ̣mːo andạre a kạza, adɛ̣sːo? — nɔ, non aŋkọra."},{"n":645,"zh":"我们出去吗？——不，我们不出去。","en":"Shall we go out? — No, let's not go out.","it":"Usciamo? — No, non usciamo.","ipa":"uʃạmo? — nɔ, non uʃạmo."},{"n":646,"zh":"你想让我关窗户吗？——不，窗户开着吧。","en":"Do you want me to close the window? — No, leave the window open.","it":"Vuoi che chiuda la finestra? — No, lascia la finestra aperta.","ipa":"vwɔ̣j ke kiụda la finɛ̣stra? — nɔ, lạʃa la finɛ̣stra apɛ̣rta."},{"n":647,"zh":"我今晚给你打电话吗？——不，早上打吧。","en":"Should I call you tonight? — No, call me in the morning.","it":"Dovrei chiamarti stasera? — No, chiamami di mattina.","ipa":"dovrẹj kjamạrti stasẹra? — nɔ, kjamạmi di matːịna."},{"n":648,"zh":"你认为我们应该等霍华德吗？——不，我们不等他。","en":"Do you think we should wait for Howard? — No, let's not wait for him.","it":"Pensi che dovremmo aspettare Howard? — No, non aspettiamolo.","ipa":"pẹnsi ke dovrɛ̣mːo aspetːạre (…)? — nɔ, non aspetːjạmolo."},{"n":649,"zh":"你想让我开灯吗？——不，灯别开。","en":"Do you want me to turn on the light? — No, leave the light off.","it":"Vuoi che accenda la luce? — No, lascia la luce spenta.","ipa":"vwɔ̣j ke atʧɛ̣nda la lụʧe? — nɔ, lạʃa la lụʧe spɛ̣nta."},{"n":650,"zh":"我们打车吗？——不，我们坐公交车吧。","en":"Should we take a taxi? — No, let's take a bus.","it":"Dovremmo prendere un taxi? — No, prendiamo l'autobus.","ipa":"dovrɛ̣mːo prɛ̣ndere un tạksi? — nɔ, prendjạmo lạwtobus."},{"n":651,"zh":"屋顶上有个男人。","en":"There's a man on the roof.","it":"C'è un uomo sul tetto.","ipa":"ʧɛ̣ un wọmo sul tɛ̣tːo."},{"n":652,"zh":":30有一列火车过来。","en":"There's a train coming at ten thirty (10:30).","it":"C'è un treno che arriva alle dieci e trenta (10:30).","ipa":"ʧɛ̣ un trẹno ke arːịv‿ ạlːe djẹʧi e trɛ̣nta (10:30)."},{"n":653,"zh":"一周有七天。","en":"There are seven (7) days in a week.","it":"Ci sono sette (7) giorni in una settimana.","ipa":"ʧi sọno sɛ̣tːe (7) ʤọrn‿ in ụna setːimạna."},{"n":654,"zh":"院子里有一棵大树。","en":"There's a big tree in the yard.","it":"C'è un grande albero nel cortile di casa.","ipa":"ʧɛ̣ un ɡrạnde ạlbero nɛl kortịle di kạza."},{"n":655,"zh":"今晚电视上没有节目。","en":"There's nothing on TV tonight.","it":"Non c'è niente alla tele stasera.","ipa":"non ʧɛ̣ njɛ̣nte ạlːa tẹle stasẹra."},{"n":656,"zh":"你有钱吗？——有，我钱包里有一些。","en":"Do you have any money? — Yes, there's some in my wallet.","it":"Hai dei soldi? — Sì, c'è qualcosa nel mio portafogli.","ipa":"ạj dẹj sɔ̣ldi? — sị, ʧɛ̣ kwalkɔ̣za nɛl mịo portafọʎːi."},{"n":657,"zh":"抱歉，附近有酒店吗？——有。> 没有。","en":"Excuse me, is there a hotel near here? — Yes, there is. > No, there isn't.","it":"Scusi, c'è forse un albergo qui nelle vicinanze? — Sì, c'è. > No, non c'è.","ipa":"skụzi, ʧɛ̣ fọrse un albɛ̣rɡo kwị nɛ̣lːe viʧinạnʦe? — sị, ʧɛ̣. > nɔ, non ʧɛ̣."},{"n":658,"zh":"我们不能去滑雪。没雪。","en":"We can't go skiing. There isn't any snow.","it":"Non possiamo andare a sciare. Non c'è neve.","ipa":"non posːjạmo andạre a ʃiạre. non ʧɛ̣ nẹve."},{"n":659,"zh":"院子里有几棵大树。","en":"There are some big trees in the yard.","it":"Ci sono degli alberi enormi nel giardino.","ipa":"ʧi sọno dẹʎːi ạlberi enɔ̣rmi nɛl ʤardịno."},{"n":660,"zh":"这条路上有很多事故。","en":"There are a lot of accidents on this road.","it":"Ci sono molti incidenti su questa strada.","ipa":"ʧi sọno mọlt‿ iɲʧidɛ̣nti su kwɛ̣sta strạda."},{"n":661,"zh":"这附近有餐馆吗？——有的。/ 没有的。","en":"Are there any restaurants near here? — Yes, there are. > No, there aren't.","it":"Ci sono dei ristoranti nei paraggi? — Sì, ce ne sono. > No, non ce ne sono.","ipa":"ʧi sọno dẹj ristorạnti nɛ̣j parạdʤi? — sị, ʧe ne sọno. > nɔ, non ʧe ne sọno."},{"n":662,"zh":"这家餐馆很安静。这里人不多。","en":"This restaurant is very quiet. There aren't many people here.","it":"Questo ristorante è molto tranquillo. Non ci sono molte persone qui.","ipa":"kwɛ̣sto ristorạnt‿ ɛ̣ mọlto traŋkwịlːo. non ʧi sọno mọlte persọne kwị."},{"n":663,"zh":"足球队有多少名球员？","en":"How many players are there on a football team?","it":"Quanti giocatori ci sono in una squadra di calcio?","ipa":"kwạnti ʤokatọri ʧi sọno in ụna skwạdra di kạlʧo?"},{"n":664,"zh":"足球队有11名球员。","en":"There are eleven (11) players on a football team.","it":"Ci sono undici (11) giocatori in una squadra di calcio.","ipa":"ʧi sọno ụndiʧi (11) ʤokatọri in ụna skwạdra di kạlʧo."},{"n":665,"zh":"桌上有一本书。","en":"There's a book on the table.","it":"C'è un libro sul tavolo.","ipa":"ʧɛ̣ un lịbro sul tạvolo."},{"n":666,"zh":":30有一趟火车。是快车。","en":"There's a train at ten thirty (10:30). It's an express train.","it":"C'è un treno alle dieci e trenta (10:30). È un treno espresso.","ipa":"ʧɛ̣ un trẹno ạlːe djẹʧi e trɛ̣nta (10:30). ɛ̣ un trẹno esprɛ̣sːo."},{"n":667,"zh":"这汤里盐很多。","en":"There's a lot of salt in this soup.","it":"C'è molto sale in questa zuppa.","ipa":"ʧɛ̣ mọlto sạle in kwɛ̣sta ʣụpːa."},{"n":668,"zh":"我不喜欢这汤。太咸了。","en":"I don't like this soup. It's too salty.","it":"Non mi piace questa zuppa. È troppo salata.","ipa":"non mi pjạʧe kwɛ̣sta ʣụpːa. ɛ̣ trɔ̣pːo salạta."},{"n":669,"zh":"贝德福德不是个古城。这里没有老建筑。","en":"Bedford isn't an old town. There aren't any old buildings.","it":"Bedford non è una città antica. Non c'è alcun edificio d'epoca.","ipa":"(…) non ɛ̣ ụna ʧitːạ antịka. non ʧɛ̣ alkụn edifịʧo dẹpoka."},{"n":670,"zh":"看！报纸上有你哥哥的照片！","en":"Look! There's a photo of your brother in the newspaper!","it":"Guarda! C'è una foto di tuo fratello sul giornale!","ipa":"ɡwạrda! ʧɛ̣ ụna fọto di tụo fratɛ̣lːo sul ʤornạle!"},{"n":671,"zh":"抱歉，这附近有银行吗？——有的，在街尾。","en":"Excuse me, is there a bank near here? — Yes, at the end of the block.","it":"Scusi, c'è una banca qui vicino? — Sì, alla fine dell'isolato.","ipa":"skụzi, ʧɛ̣ ụna bạŋka kwị viʧịno? — sị, ạlːa fịne dɛlːizolạto."},{"n":672,"zh":"我家里有5个人：我父母、我两个姐妹和我自己。","en":"There are five (5) people in my family: my parents, my two (2) sisters, and me.","it":"La mia famiglia è composta da cinque (5) persone: i miei genitori, le mie due (2) sorelle e io.","ipa":"la mịa famịʎːja ɛ̣ kompɔ̣sta da ʧịŋkwe (5) persọne: i mjɛ̣j ʤenitọri, le mịe dụe (2) sorɛ̣lː‿ e ịo."},{"n":673,"zh":"班里有多少学生？——20个。","en":"How many students are there in the class? — Twenty.","it":"Quanti studenti ci sono a lezione? — Venti.","ipa":"kwạnti studɛ̣nti ʧi sọno a leʦjọne? — vɛ̣nti."},{"n":674,"zh":"这条路通常很安静。车不多。","en":"The road is usually very quiet. There isn't much traffic.","it":"La strada, di solito, è davvero silenziosa. Non c'è molto traffico.","ipa":"la strạda, di sɔ̣lito, ɛ̣ davːẹro silenʦjọza. non ʧɛ̣ mọlto trạfːiko."},{"n":675,"zh":"市中心到机场有公交车吗？——有的，每20分钟一趟。","en":"Is there a bus from downtown to the airport? — Yes, every twenty (20) minutes.","it":"C'è un autobus dal centro per l'aeroporto? — Sì, ogni venti (20) minuti.","ipa":"ʧɛ̣ un ạwtobus dal ʧɛ̣ntro pɛr laeropɔ̣rto? — sị, ɔ̣ɲːi vɛ̣nti (20) minụti."},{"n":676,"zh":"有问题吗？——没有，都挺好的。","en":"Are there any problems? — No, everything is okay.","it":"Ci sono problemi? — No, va tutto bene.","ipa":"ʧi sọno problẹmi? — nɔ, va tụtːo bẹne."},{"n":677,"zh":"没地方坐。没椅子。","en":"There's nowhere to sit down. There aren't any chairs.","it":"Non c'è un posto per sedersi. Non ci sono sedie.","ipa":"non ʧɛ̣ un pɔ̣sto pɛr sedẹrsi. non ʧi sọno sẹdje."},{"n":678,"zh":"太阳系里有8颗行星。","en":"There are eight (8) planets in the solar system.","it":"Ci sono otto (8) pianeti nel Sistema Solare.","ipa":"ʧi sọn‿ ɔ̣tːo (8) pjanẹti nɛl sistẹma solạre."},{"n":679,"zh":"英语字母表里有26个字母。","en":"There are twenty-six (26) letters in the English alphabet.","it":"Ci sono ventisei (26) lettere nell'alfabeto inglese.","ipa":"ʧi sọno ventisẹj (20) lɛ̣tːere nɛlːalfabẹto inɡlẹze."},{"n":680,"zh":"九月有30天。","en":"There are thirty (30) days in September.","it":"Ci sono trenta (30) giorni nel mese di settembre.","ipa":"ʧi sọno trɛ̣nta (30) ʤọrni nɛl mẹze di setːẹmbre."},{"n":681,"zh":"美国有五十个州。","en":"There are fifty (50) states in the United States.","it":"Ci sono cinquanta (50) stati negli Stati Uniti.","ipa":"ʧi sọno ʧiŋkwạnta (50) stạti nɛ̣ʎːi stạti unịti."},{"n":682,"zh":"篮球队有五名球员。","en":"There are five (5) players on a basketball team.","it":"Ci sono cinque (5) giocatori in una squadra di pallacanestro.","ipa":"ʧi sọno ʧịŋkwe (5) ʤokatọri in ụna skwạdra di palːakanɛ̣stro."},{"n":683,"zh":"有十点半的航班。——是直飞吗？","en":"There's a flight at ten thirty (10:30). — Is it a non-stop flight?","it":"C'è un volo alle dieci e trenta (10:30). — È un volo diretto?","ipa":"ʧɛ̣ un vọlo ạlːe djẹʧi e trɛ̣nta (10:30). — ɛ̣ un vọlo dirɛ̣tːo?"},{"n":684,"zh":"我不买这件衬衫，太贵了。","en":"I'm not going to buy this shirt. It's too expensive.","it":"Non comprerò questa maglietta. È troppo cara.","ipa":"non komprerɔ̣ kwɛ̣sta maʎːjɛ̣tːa. ɛ̣ trɔ̣pːo kạra."},{"n":685,"zh":"怎么了？——我眼睛里进了东西。","en":"What's wrong? — There's something in my eye.","it":"Cos'hai? — Ho qualcosa nell'occhio!","ipa":"kozạj? — ɔ kwalkɔ̣za nɛlːɔ̣kːjo!"},{"n":686,"zh":"你家外面有一辆红色轿车，是你的吗？","en":"There's a red car outside your house. Is it yours?","it":"C'è una macchina rossa davanti [a] casa tua. È tua?","ipa":"ʧɛ̣ ụna mạkːina rọsːa davạnti [a] kạza tụa. ɛ̣ tụa?"},{"n":687,"zh":"今晚电视上有好节目吗？——是的，八点有一部电影。","en":"Is there anything good on TV tonight? — Yes, there's a movie at eight [o'clock] (8:00).","it":"C'è qualcosa di bello alla tivù stasera? — Sì, c'è un film alle otto (8:00).","ipa":"ʧɛ̣ kwalkɔ̣za di bɛ̣lːo ạlːa tivụ stasẹra? — sị, ʧɛ̣ un film ạlːe ɔ̣tːo (8:00)."},{"n":688,"zh":"那座楼是什么？——是所学校。","en":"What's that building? — It's a school.","it":"Cos'è quel palazzo? — È una scuola.","ipa":"kozɛ̣ kwɛ̣l palạʦːo? — ɛ̣ ụna skwɔ̣la."},{"n":689,"zh":"这家酒店里有餐厅吗？——没有，恐怕没有。","en":"Is there a restaurant in this hotel? — No, I'm afraid not.","it":"C'è un ristorante in questo albergo? — No, temo di no.","ipa":"ʧɛ̣ un ristorạnte in kwɛ̣sto albɛ̣rɡo? — nɔ, tẹmo di nɔ."},{"n":690,"zh":"每小时都有一趟火车。","en":"There's a train every hour.","it":"C'è un treno ogni ora.","ipa":"ʧɛ̣ un trẹn‿ ɔ̣ɲːi ọra."},{"n":691,"zh":"现在是十一点十五分。刚才十一点有一趟火车。","en":"The time now is eleven fifteen (11:15) . There was a train at eleven [o'clock] (11:00).","it":"Adesso sono le undici e quindici (11:15) minuti. C'era un treno alle undici (11:00).","ipa":"adɛ̣sːo sọno le ụndiʧi e kwịndiʧi (11:15) minụti. ʧẹra un trẹno ạlːe ụndiʧi (11:00)."},{"n":692,"zh":"今晚电视上有很好的自然纪录片。","en":"There's a good nature program on TV tonight.","it":"Stasera, c'è un bel documentario alla televisione.","ipa":"stasẹra, ʧɛ̣ un bɛl dokumentạrjo ạlːa televizjọne."},{"n":693,"zh":"昨晚电视上有很好的自然纪录片。","en":"There was a good nature program on TV last night.","it":"Ieri sera, c'era un bel documentario in tivù.","ipa":"jẹri sẹra, ʧẹra un bɛl dokumentạrjo in tivụ."},{"n":694,"zh":"我们住在一个非常大的酒店，有一千二百五十间房。","en":"We're staying at a very big hotel. There are one thousand two hundred fifty (1,250) rooms.","it":"Soggiorneremo in un albergo davvero grande. Ci sono milleduecentocinquanta (1.250) stanze.","ipa":"sodʤornerẹmo in un albɛ̣rɡo davːẹro ɡrạnde. ʧi sọno milːedweʧentoʧiŋkwạnta (1.) stạnʦe."},{"n":695,"zh":"我们住过一个非常大的酒店，有一千二百五十间房。","en":"We stayed at a very big hotel. There were one thousand two hundred fifty (1,250) rooms.","it":"Abbiamo soggiornato in un albergo davvero grande. C'erano milleduecentocinquanta (1.250) stanze.","ipa":"abːjạmo sodʤornạto in un albɛ̣rɡo davːẹro ɡrạnde. ʧẹrano milːedweʧentoʧiŋkwạnta (1.) stạnʦe."},{"n":696,"zh":"今天早上有我的电话留言吗？","en":"Are there any phone messages for me this morning?","it":"Ci sono dei messaggi per me in segreteria, stamattina?","ipa":"ʧi sọno dẹj mesːạdʤi pɛr mɛ in seɡreterịa, stamatːịna?"},{"n":697,"zh":"昨天有我的电话留言吗？","en":"Were there any phone messages for me yesterday?","it":"C'erano dei messaggi per me in segreteria, ieri?","ipa":"ʧẹrano dẹj mesːạdʤi pɛr mɛ in seɡreterịa, jẹri?"},{"n":698,"zh":"我饿了，但没东西吃。","en":"I'm hungry, but there isn't anything to eat.","it":"Ho fame, ma non c'è niente da mangiare.","ipa":"ɔ fạme, ma non ʧɛ̣ njɛ̣nte da maɲʤạre."},{"n":699,"zh":"我回到家饿了，但没东西吃。","en":"I was hungry when I got home, but there wasn't anything to eat.","it":"Avevo fame quando sono arrivato a casa, ma non c'era niente da mangiare.","ipa":"avẹvo fạme kwạndo sọno arːivạto a kạza, ma non ʧẹra njɛ̣nte da maɲʤạre."},{"n":700,"zh":"看！出事故了。","en":"Look! There's been an accident.","it":"Guarda! C'è stato un incidente.","ipa":"ɡwạrda! ʧɛ̣ stạto un iɲʧidɛ̣nte."}]},{"lesson":8,"range":[701,800],"items":[{"n":701,"zh":"这条路非常危险，上面已经发生了很多事故。","en":"This road is very dangerous. There have been many accidents on it.","it":"Questa strada è davvero pericolosa. Ci sono stati molti incidenti.","ipa":"kwɛ̣sta strạda ɛ̣ davːẹro perikolọza. ʧi sọno stạti mọlt‿ iɲʧidɛ̣nti."},{"n":702,"zh":"昨晚发生了一起事故。","en":"There was an accident last night.","it":"C'è stato un incidente ieri notte.","ipa":"ʧɛ̣ stạto un iɲʧidɛ̣nte jẹri nɔ̣tːe."},{"n":703,"zh":"你觉得周六的派对会上会有很多人吗？","en":"Do you think there will be a lot of people at the party on Saturday?","it":"Pensi che ci saranno molte persone alla festa sabato?","ipa":"pẹnsi ke ʧi sarạnːo mọlte persọne ạlːa fɛ̣sta sạbato?"},{"n":704,"zh":"公司经理要离职了，所以很快就会有一位新经理上任。","en":"The manager of the company is leaving, so there will be a new manager soon.","it":"Il direttore sta lasciando l'azienda, perciò ci sarà presto un nuovo responsabile.","ipa":"il diretːọre sta laʃạndo laʦjɛ̣nda, perʧɔ̣ ʧi sarạ prɛ̣sto un nwɔ̣vo responsạbile."},{"n":705,"zh":"我明天要去外地，所以我今天在打包东西，因为明天没时间了。","en":"I'm going out of town tomorrow. I'm packing my things today because there won't be time tomorrow.","it":"Domani vado fuori città. Preparo la valigia oggi perché domani non ci sarà tempo.","ipa":"domạni vạdo fwɔ̣ri ʧitːạ. prepạro la valịʤa ɔ̣dʤi perkɛ̣ domạni non ʧi sarạ tẹmpo."},{"n":706,"zh":"明天下午会下雨。","en":"There will be rain tomorrow afternoon.","it":"Ci sarà la pioggia domani pomeriggio.","ipa":"ʧi sarạ la pjɔ̣dʤa domạni pomerịdʤo."},{"n":707,"zh":"本周末将有台风。","en":"There will be a typhoon this weekend.","it":"Ci sarà un tifone questo fine settimana.","ipa":"ʧi sarạ un tifọne kwɛ̣sto fịne setːimạna."},{"n":708,"zh":"今年夏天已经发生了三次（3次）飓风。","en":"There's already been three (3) hurricanes this summer.","it":"Ci sono già stati tre (3) uragani quest'estate.","ipa":"ʧi sọno ʤạ stạti trɛ (3) uraɡạni kwɛstestạte."},{"n":709,"zh":"墙上靠近窗户的地方有一只钟。","en":"There was a clock on the wall near the window.","it":"C'era un orologio sul muro vicino alla finestra.","ipa":"ʧẹra un orolɔ̣ʤo sul mụro viʧịno ạlːa finɛ̣stra."},{"n":710,"zh":"桌子上有一个花瓶，里面有一些花。","en":"There were some flowers in a vase on the table.","it":"C'erano dei fiori in un vaso sul tavolo.","ipa":"ʧẹrano dẹj fjọri in un vạzo sul tạvolo."},{"n":711,"zh":"书架上有一些书。","en":"There were some books on the shelves.","it":"C'erano alcuni libri sulle mensole.","ipa":"ʧẹrano alkụni lịbri sụlːe mẹnsole."},{"n":712,"zh":"门角靠近门的地方有一把扶手椅。","en":"There was an armchair in the corner near the door.","it":"C'era una poltrona nell'angolo vicino alla porta.","ipa":"ʧẹra ụna poltrọna nɛlːạŋɡolo viʧịno ạlːa pɔ̣rta."},{"n":713,"zh":"扶手椅对面有一张沙发。","en":"There was a sofa opposite the armchair.","it":"C'era un divano di fronte alla poltrona.","ipa":"ʧẹra un divạno di frọnte ạlːa poltrọna."},{"n":714,"zh":"我打开了信封，但里面是空的，什么都没有。","en":"I opened the envelope, but it was empty. There was nothing in it.","it":"Ho aperto la busta, ma era vuota. Non c'era dentro niente.","ipa":"ɔ apɛ̣rto la bụsta, ma ẹra vwɔ̣ta. non ʧẹra dɛ̣ntro njɛ̣nte."},{"n":715,"zh":"我们住在一个非常不错的酒店。 —— 真的吗？有游泳池吗？","en":"We stayed at a very nice hotel. — Really? Was there a swimming pool?","it":"Siamo stati in un albergo proprio carino. — Davvero? C'era la piscina?","ipa":"sjạmo stạt‿ in un albɛ̣rɡo prɔ̣prjo karịno. — davːẹro? ʧẹra la piʃịna?"},{"n":716,"zh":"你买樱桃了吗？ —— 没有，店里没有卖。","en":"Did you buy any cherries? — No, there weren't any at the store.","it":"Hai comprato delle ciliegie? — No, non ce n'erano più dal fruttivendolo.","ipa":"ạj komprạto dɛ̣lːe ʧiljẹʤe? — nɔ, non ʧe nẹrano piụ dal frutːivɛ̣ndolo."},{"n":717,"zh":"钱包是空的，里面没有钱。","en":"The wallet was empty. There wasn't any money in it.","it":"Il portafoglio era vuoto. Non c'era alcun denaro al suo interno.","ipa":"il portafɔ̣ʎːjo ẹra vwɔ̣to. non ʧẹra alkụn denạro al sụo intɛ̣rno."},{"n":718,"zh":"会议上有很多人吗？ —— 没有，很少。","en":"Were there many people at the meeting? — No, very few.","it":"C'era molta gente all'incontro? — No, davvero poche.","ipa":"ʧẹra mọlta ʤɛ̣nte alːiŋkọntro? — nɔ, davːẹro pɔ̣ke."},{"n":719,"zh":"我们没有参观博物馆，因为时间不够。","en":"We didn't visit the museum. There wasn't enough time.","it":"Non abbiamo visitato il museo. Non c'era abbastanza tempo.","ipa":"non abːjạmo vizitạto il muzẹo. non ʧẹra abːastạnʦa tẹmpo."},{"n":720,"zh":"对不起，我迟到了，因为交通太堵了。","en":"I'm sorry I'm late. There was a lot of traffic.","it":"Scusa sono in ritardo. C'era molto traffico.","ipa":"skụza sọno in ritạrdo. ʧẹra mọlto trạfːiko."},{"n":721,"zh":"二十年前这里没多少游客，现在可多了。","en":"Twenty years ago there weren't many tourists here. Now there are a lot.","it":"Ventanni fa non c'erano molti turisti qui. Ora ce ne sono molti.","ipa":"ventạnːi fa non ʧẹrano mọlti turịsti kwị. ọra ʧe ne sọno mọlti."},{"n":722,"zh":"一天有24个小时。","en":"There are twenty-four (24) hours in a day.","it":"Ci sono ventiquattro (24) ore in un giorno.","ipa":"ʧi sọno ventikwạtːro (24) ọre in un ʤọrno."},{"n":723,"zh":"上周五公司有个聚会，但我没去。","en":"There was a party at work last Friday, but I didn't go.","it":"Venerdì scorso al lavoro c'è stata una festa, ma non ci sono andato.","ipa":"venerdị skọrso al lavọro ʧɛ̣ stạta ụna fɛ̣sta, ma non ʧi sọno andạto."},{"n":724,"zh":"我在哪能买到一瓶水？——街区尽头有个便利店。","en":"Where can I buy a bottle of water? — There's a convenience store at the end of the block.","it":"Dove posso comprare una bottiglia d'acqua? — C'è un minimarket alla fine della strada.","ipa":"dọve pɔ̣sːo komprạre ụna botːịʎːja dạkwa? — ʧɛ̣ un minimạrket ạlːa fịne dɛ̣lːa strạda."},{"n":725,"zh":"为什么警察在银行外面？——刚才发生了抢劫。","en":"Why are the police outside the bank? — There was a robbery.","it":"Perchè la polizia è fuori dalla banca? — C'è stata una rapina.","ipa":"perkɛ̣ la poliʦịa ɛ̣ fwɔ̣ri dạlːa bạŋka? — ʧɛ̣ stạta ụna rapịna."},{"n":726,"zh":"我们到剧院时，外面排着长队。","en":"When we got to the theater, there was a long line outside.","it":"Quando siamo arrivati a teatro, c'era una lunga coda fuori.","ipa":"kwạndo sjạmo arːivạti a teạtro, ʧẹra ụna lụŋɡa kọda fwɔ̣ri."},{"n":727,"zh":"你明天到了，机场会有人接你。","en":"When you arrive tomorrow, there will be somebody at the airport to meet you.","it":"Quando arrivi domani, ci sarà qualcuno all'aeroporto ad aspettarti.","ipa":"kwạndo arːịvi domạni, ʧi sarạ kwalkụno alːaeropɔ̣rto ad aspetːạrti."},{"n":728,"zh":"十年前学校有五百个孩子，现在超过一千了。","en":"Ten years ago there were five hundred (500) children in the school. Now there are more than a thousand.","it":"Dieci anni fa c'erano cinquecento (500) bambini nella scuola. Adesso ce ne sono più di mille.","ipa":"djẹʧi ạnːi fa ʧẹrano ʧiŋkweʧɛ̣nto () bambịni nɛ̣lːa skwɔ̣la. adɛ̣sːo ʧe ne sọno piụ di mịlːe."},{"n":729,"zh":"上周我回到了我出生的镇上，现在变化很大，变化很多。","en":"Last week I went back to the town where I was born. It's very different now. There have been a lot of changes.","it":"Settimana scorsa sono ritornato (♀ritornata) nella città in cui sono nato (♀nata). È molto diversa adesso. Sono cambiate molte cose.","ipa":"setːimạna skọrsa sọno ritornạto (♀ritornạta) nɛ̣lːa ʧitːạ in kwị sọno nạto (♀nạta). ɛ̣ mọlto divɛ̣rs‿ adɛ̣sːo. sọno kambjạte mọlte kɔ̣ze."},{"n":730,"zh":"我想一切都会好起来的，我觉得不会有问题。","en":"I think everything will be okay. I don't think there will be any problems.","it":"Penso che andrà tutto per il meglio. Non penso che ci saranno [dei] problemi.","ipa":"pẹnso ke andrạ tụtːo pɛr il mẹʎːjo. non pẹnso ke ʧi sarạnːo [dẹj] problẹmi."},{"n":731,"zh":"你真的要搬到柏林去吗？","en":"Is it true that you're moving to Berlin?","it":"È vero che ti straferirai a Berlino?","ipa":"ɛ̣ vẹro ke ti straferirạj a berlịno?"},{"n":732,"zh":"我们现在得走了，已经很晚了。","en":"We have to go now. It's very late.","it":"Adesso dobbiamo andare. È davvero tardi.","ipa":"adɛ̣sːo dobːjạmo andạre. ɛ̣ davːẹro tạrdi."},{"n":733,"zh":"吉罗真的能开直升机吗？","en":"Is it true that Jirou can fly a helicopter?","it":"È vero che Jirou sa pilotare un elicottero?","ipa":"ɛ̣ vẹro ke jiroụ sa pilotạre un elikɔ̣tːero?"},{"n":734,"zh":"今天星期几？星期二吗？——不，今天是星期三。","en":"What day is it today? Tuesday? — No, today's Wednesday.","it":"Che giorno è oggi? Martedì? — No, oggi è mercoledì.","ipa":"ke ʤọrno ɛ̣ ɔ̣dʤi? martedị? — nɔ, ɔ̣dʤi ɛ̣ merkolẹdị."},{"n":735,"zh":"从市中心到机场有10公里。","en":"It's ten (10) kilometers from downtown to the airport.","it":"Sono dieci (10) chilometri dal centro città all'areoporto.","ipa":"sọno djẹʧi (10) kilɔ̣metri dal ʧɛ̣ntro ʧitːạ alːareopɔ̣rto."},{"n":736,"zh":"我现在给你办公室打电话可以吗？","en":"Is it okay to call you at the office?","it":"Va bene se ti chiamo in ufficio?","ipa":"va bẹne se ti kjạmo in ufːịʧo?"},{"n":737,"zh":"你想步行去酒店吗？——我不知道，有多远？","en":"Do you want to walk to the hotel? — I don't know. How far is it?","it":"Vuoi andare in albergo a piedi? — Non lo so. Quanto è distante?","ipa":"vwɔ̣j andạre in albɛ̣rɡo a pjẹdi? — non lo sɔ. kwạnto ɛ̣ distạnte?"},{"n":738,"zh":"今天是凯利的生日，她27岁。","en":"It's Kelly's birthday today. She's twenty-seven (27).","it":"Oggi e il compleanno di Kelly. Ha ventisette (27) anni.","ipa":"ɔ̣dʤi ɛ̣ il kompleạnːo di (…). a ventisɛ̣tːe (27) ạnːi."},{"n":739,"zh":"我不信！那不可能。","en":"I don't believe it! That's impossible.","it":"Non ci credo! È impossibile.","ipa":"non ʧi krẹdo! ɛ̣ imposːịbile."},{"n":740,"zh":"从这里到火车站有多远？","en":"How far is it from here to the train station?","it":"Quanto dista da qui la stazione?","ipa":"kwạnto dịsta da kwị la staʦjọne?"},{"n":741,"zh":"从酒店到海滩有多远？","en":"How far is it from the hotel to the beach?","it":"Quanto è lontano l'albergo dalla spiaggia?","ipa":"kwạnto ɛ̣ lontạno lalbɛ̣rɡo dạlːa spjạdʤa?"},{"n":742,"zh":"台北到东京有多远？","en":"How far is it from Taipei to Tokyo?","it":"Quant'è distante Taipei da Tokio?","ipa":"kwantɛ̣ distạnte taipẹj da tɔ̣kjo?"},{"n":743,"zh":"你家到机场有多远？","en":"How far is it from your house to the airport?","it":"Quanto ci vuole da casa tua all'areoporto?","ipa":"kwạnto ʧi vwɔ̣le da kạza tụa alːareopɔ̣rto?"},{"n":744,"zh":"今天天气不太好，多云。","en":"The weather isn't so nice today. It's cloudy.","it":"Il tempo non è così bello oggi. È nuvoloso.","ipa":"il tẹmpo non ɛ̣ kozị bɛ̣lː‿ ɔ̣dʤi. ɛ̣ nuvolọzo."},{"n":745,"zh":"昨天风很大。","en":"There was strong wind yesterday.","it":"C'era un forte vento ieri.","ipa":"ʧẹra un fɔ̣rte vɛ̣nto jẹri."},{"n":746,"zh":"这房间好热，开个窗户吧。","en":"It's hot in this room. Open a window.","it":"Fa caldo in questa stanza. Apri la finestra.","ipa":"fa kạldo in kwɛ̣sta stạnʦa. ạpri la finɛ̣stra."},{"n":747,"zh":"昨天是个好天气，又暖和又阳光。","en":"It was a nice day yesterday. It was warm and sunny.","it":"È stata una bella giornata ieri. Faceva caldo e c'era il sole.","ipa":"ɛ̣ stạta ụna bɛ̣lːa ʤornạta jẹri. faʧẹva kạldo e ʧẹra il sọle."},{"n":748,"zh":"昨晚有暴风雨，你听到了吗？","en":"There was a storm last night. Did you hear it?","it":"C'è stato un temporale ieri notte. L'hai sentito?","ipa":"ʧɛ̣ stạto un temporạle jẹri nɔ̣tːe. lạj sentịto?"},{"n":749,"zh":"我很害怕，因为太黑了。","en":"I was afraid because it was very dark.","it":"Avevo paura perché era davvero buio.","ipa":"avẹvo paụra perkɛ̣ ẹra davːẹro bụjo."},{"n":750,"zh":"这里经常很冷，但雨不多。","en":"It's often cold here, but there isn't much rain.","it":"Qui fa spesso freddo, però non piove molto.","ipa":"kwị fa spɛ̣sːo frɛ̣dːo, perɔ̣ non pjɔ̣ve mọlto."},{"n":751,"zh":"从这里到最近的加油站好远。","en":"It's a long way from here to the nearest gas station.","it":"È un bel po' di strada, da qui al più vicino distributore di benzina.","ipa":"ɛ̣ un bɛl pɔ di strạda, da kwị al piụ viʧịno distributọre di benzịna."},{"n":752,"zh":"如果你睡得晚，早上早起就困难了。","en":"If you go to bed late, it's difficult to get up early in the morning.","it":"Se vai a letto tardi, è difficile, poi, alzarsi presto la mattina.","ipa":"se vạj a lɛ̣tːo tạrdi, ɛ̣ difːịʧile, pɔ̣j, alʦạrsi prɛ̣sto la matːịna."},{"n":753,"zh":"嗨，Junko，很高兴再次见到你。你怎么样？","en":"Hello, Junko. It's nice to see you again. How are you?","it":"Ciao, Junko. È bello rivederti. Come stai?","ipa":"ʧạo, (…). ɛ̣ bɛ̣lːo rivedẹrti. kọme stạj?"},{"n":754,"zh":"在这个办公室工作不可能，噪音太大。","en":"It's impossible to work in this office. There's too much noise.","it":"È impossibile lavorare in questo ufficio. C'è troppa confusione.","ipa":"ɛ̣ imposːịbile lavorạre in kwɛ̣sto ufːịʧo. ʧɛ̣ trɔ̣pːa konfuzjọne."},{"n":755,"zh":"工作中每个人都很好，很容易交朋友。","en":"Everybody's very nice at work. It's easy to make friends.","it":"Sono tutti gentili al lavoro. È facile fare amicizia.","ipa":"sọno tụtːi ʤentịli al lavọro. ɛ̣ fạʧile fạre amiʧịʦja."},{"n":756,"zh":"我喜欢旅行，去不同的地方很有趣。","en":"I like traveling. It's interesting to visit different places.","it":"Mi piace viaggiare. È interessante visitare posti diversi.","ipa":"mi pjạʧe vjadʤạre. ẹ interesːạnte vizitạre pɔ̣sti divẹrsi."},{"n":757,"zh":"有些城市晚上不安全，很危险。","en":"Some cities are not safe. It's dangerous at night.","it":"Alcune città non sono sicure. Di notte è pericoloso.","ipa":"alkụne ʧitːạ non sọno sikụre. di nɔ̣tː‿ ɛ̣ perikolọzo."},{"n":758,"zh":"她不累，但他累了。","en":"She isn't tired, but he is.","it":"Lei non è stanca, però lui sì.","ipa":"lɛ̣j non ɛ̣ stạŋka, perɔ̣ lụj sị."},{"n":759,"zh":"她喜欢喝茶，但他不喜欢。","en":"She likes tea, but he doesn't.","it":"A lei piace il tè, però a lui no.","ipa":"a lɛ̣j pjạʧe il tɛ̣, perɔ̣ a lụj nɔ."},{"n":760,"zh":"我没看过这部电影，但我妹妹看过了。","en":"I haven't seen the movie, but my sister has.","it":"Non ho visto il film, ma mia sorella sì.","ipa":"non ɔ vịsto il film, ma mịa sorɛ̣lːa sị."},{"n":761,"zh":"请帮帮我。——抱歉，我做不到。","en":"Please help me. — I'm sorry, I can't.","it":"Per favore aiutami. — Mi dispiace, non posso.","ipa":"pɛr favọre ajụtami. — mi dispjạʧe, non pɔ̣sːo."},{"n":762,"zh":"你累了吗？——我之前是，但现在不累了。","en":"Are you tired? — I was, but I'm not now.","it":"Sei stanco (♀stanca)? — Lo ero, però adesso no.","ipa":"sɛ̣j stạŋko (♀stạŋka)? — lo ẹro, perɔ̣ adɛ̣sːo nɔ."},{"n":763,"zh":"你觉得露西今晚会打电话吗？——可能会吧。","en":"Do you think Lucy will call tonight? — She might.","it":"Pensi che Lucia chiamerà stasera? — Potrebbe darsi.","ipa":"pẹnsi ke luʧịa kjamerạ stasẹra? — potrɛ̣bːe dạrsi."},{"n":764,"zh":"你今晚要学习吗？——我应该会，但可能不会。","en":"Are you going to study tonight? — I should, but I probably won't.","it":"Studierai stasera? — Dovrei, ma probabilmente non lo farò.","ipa":"studjerạj stasẹra? — dovrẹj, ma probabilmɛ̣nte non lo farɔ̣."},{"n":765,"zh":"我妹妹看过那部电影了，但我没看过。","en":"My sister has seen the movie, but I haven't.","it":"Mia sorella ha visto il film, però io no.","ipa":"mịa sorɛ̣lː‿ a vịsto il film, perɔ̣ ịo nɔ."},{"n":766,"zh":"你和杰克明天要工作吗？——我要，但杰克不。","en":"Are you and Jack working tomorrow? — I am, but Jack isn't.","it":"Tu e Giacomo lavorate domani? — Io sì, ma Giacomo no.","ipa":"tu e ʤạkomo lavorạte domạni? — ịo sị, ma ʤạkomo nɔ."},{"n":767,"zh":"你累了吗？——是的，我累了。/ 不，我不累。","en":"Are you tired? — Yes, I am. > No, I'm not.","it":"Sei stanco? — Sì, sono stanco. > No, non sono stanco.","ipa":"sɛ̣j stạŋko? — sị, sọno stạŋko. > nɔ, non sọno stạŋko."},{"n":768,"zh":"加内什明天会在这里吗？——是的，他会。/ 不，他不会。","en":"Will Ganesh be here tomorrow? — Yes, he will. > No, he won't.","it":"Ganesh sarà qui domani? — Sì, sarà qui. > No, non sarà qui.","ipa":"ɡạnez sarạ kwị domạni? — sị, sarạ kwị. > nɔ, non sarạ kwị."},{"n":769,"zh":"有去机场的公交车吗？——有的。/ 没有的。","en":"Is there a bus to the airport? — Yes, there is. > No, there isn't.","it":"C'è un autobus per l'aeroporto? — Sì, c'è. > No, non c'è.","ipa":"ʧɛ̣ un ạwtobus pɛr laeropɔ̣rto? — sị, ʧɛ̣. > nɔ, non ʧɛ̣."},{"n":770,"zh":"我不喜欢热天气，但莉拉喜欢。","en":"I don't like hot weather, but Lila does.","it":"Non mi piace quando fa caldo, però a Lila sì.","ipa":"non mi pjạʧe kwạndo fa kạldo, perɔ̣ a lịla sị."},{"n":771,"zh":"马丁工作很努力，但我没有。","en":"Martin works hard, but I don't.","it":"Martino lavora duro, io no.","ipa":"martịno lavọra dụro, ịo nɔ."},{"n":772,"zh":"你喜欢你的工作吗？——是的，我喜欢。","en":"Do you enjoy your work? — Yes, I do.","it":"Ti piace il tuo lavoro? — Sì, mi piace.","ipa":"ti pjạʧe il tụo lavọro? — sị, mi pjạʧe."},{"n":773,"zh":"你和妮可喜欢那部电影吗？——我喜欢，但妮可不喜欢。","en":"Did you and Nicole like the movie? — I did, but Nicole didn't.","it":"A te e Nicola è piaciuto il film? — A me è piaciuto, a Nicola no.","ipa":"a t‿ e nikɔ̣la ɛ̣ pjaʧụto il film? — a m‿ ɛ̣ pjaʧụto, a nikɔ̣la nɔ."},{"n":774,"zh":"我玩得很开心。——我也是。","en":"I had a good time. — I did, too.","it":"Mi sono divertito. — Anch'io.","ipa":"mi sọno divertịto. — aŋkịo."},{"n":775,"zh":"法蒂玛不饿，但我们饿了。","en":"Fatima wasn't hungry, but we were.","it":"Fatima non aveva fame, al contrario noi ne avevamo.","ipa":"fạtima non avẹva fạme, al kontrạrjo nọj ne avevạmo."},{"n":776,"zh":"我没结婚，但我哥哥结婚了。","en":"I'm not married, but my brother is.","it":"Io non sono sposato, mentre mio fratello sì.","ipa":"ịo non sọno spozạto, mɛ̣ntre mịo fratɛ̣lːo sị."},{"n":777,"zh":"法希姆帮不了你，但我可以。","en":"Fahim can't help you, but I can.","it":"Fahim non può aiutarti, però io sì.","ipa":"(…) non pwɔ̣ ajutạrti, perɔ̣ ịo sị."},{"n":778,"zh":"我没读过那本书，但保罗读过了。","en":"I haven't read the book, but Paul has.","it":"Non ho letto il libro, Paolo invece sì.","ipa":"non ɔ lɛ̣tːo il lịbro, pạolo invẹʧe sị."},{"n":779,"zh":"瑞贝卡不会在这里，但安东尼奥会。","en":"Rebecca won't be here, but Antonio will.","it":"Rebecca non sarà qui, però Antonio sì.","ipa":"rebɛ̣kːa non sarạ kwị, perɔ̣ antɔ̣njo sị."},{"n":780,"zh":"你没迟到，但我迟到了。","en":"You weren't late, but I was.","it":"Tu non eri in ritardo, ma io sì.","ipa":"tu non ẹri in ritạrdo, ma ịo sị."},{"n":781,"zh":"我妹妹会弹钢琴，但我不会。","en":"My sister can play the piano, but I can't.","it":"Mia sorella sa suonare il pianoforte, ma io no.","ipa":"mịa sorɛ̣lːa sa swonạre il pjanofɔ̣rte, ma ịo nɔ."},{"n":782,"zh":"安娜贝尔今天上班，但我没上班。","en":"Anabel's working today, but I'm not.","it":"Annabella oggi lavora, io no.","ipa":"anːabɛ̣lːa ɔ̣dʤi lavọra, ịo nɔ."},{"n":783,"zh":"我在工作，但我的朋友们没在。","en":"I was working, but my friends weren't.","it":"Stavo lavorando, invece i miei amici no.","ipa":"stạvo lavorạndo, invẹʧe i mjɛ̣j amịʧi nɔ."},{"n":784,"zh":"理查德去过中国，但我没去过。","en":"Richard has been to China, but I haven't.","it":"Riccardo è stato in Cina, però io no.","ipa":"rikːạrdo ɛ̣ stạto in ʧịna, perɔ̣ ịo nɔ."},{"n":785,"zh":"我准备好了要走，但索尼娅没准备好。","en":"I'm ready to go, but Sonia isn't.","it":"Sono pronto per andare, invece Sonia no.","ipa":"sọno prọnto pɛr andạre, invẹʧe sɔ̣nja nɔ."},{"n":786,"zh":"我看过那部电影，但恩佐没看过。","en":"I've seen the movie, but Enzo hasn't.","it":"Ho visto il film, ma Enzo no.","ipa":"ɔ vịsto il film, ma ẹnʦo nɔ."},{"n":787,"zh":"我不喜欢热天气，但塞西莉亚喜欢。","en":"I don't like hot weather, but Cecilia does.","it":"Non mi piace il [clima] caldo, però a Cecilia sì.","ipa":"non mi pjạʧe il [klịma] kạldo, perɔ̣ a ʧeʧịlja sị."},{"n":788,"zh":"史蒂夫喜欢热天气，但我不喜欢。","en":"Steve likes hot weather, but I don't.","it":"A Stefano piace quando fa caldo, ma a me no.","ipa":"a stẹfano pjạʧe kwạndo fa kạldo, m‿ a mɛ nɔ."},{"n":789,"zh":"我妈妈戴眼镜，但我爸爸不戴。","en":"My mother wears glasses, but my father doesn't.","it":"Mia madre porta gli occhiali, al contrario di mio padre.","ipa":"mịa mạdre pɔ̣rta ʎːi okːjạli, al kontrạrjo di mịo pạdre."},{"n":790,"zh":"你不太了解瓦内萨，但我了解。","en":"You don't know Vanessa very well, but I do.","it":"Tu non conosci Vanessa molto bene, però io sì.","ipa":"tu non konọʃi vanɛ̣sːa mọlto bẹne, perɔ̣ ịo sị."},{"n":791,"zh":"我没享受那个派对，但我的朋友们享受了。","en":"I didn't enjoy the party, but my friends did.","it":"Io non mi sono divertito alla festa, però i miei amici sì.","ipa":"ịo non mi sọno divertịto ạlːa fɛ̣sta, perɔ̣ i mjɛ̣j amịʧi sị."},{"n":792,"zh":"我不太看电视，但厄哈德看很多。","en":"I don't watch TV much, but Erhard does.","it":"Non guardo molta televisione, invece Erhard sì.","ipa":"non ɡwạrdo mọlta televizjọne, invẹʧe (…) sị."},{"n":793,"zh":"赫安娜住在瑞士，但她的父母不住。","en":"Hannah lives in Switzerland, but her parents don't.","it":"Anna vive in Svizzera, ma non i suoi genitori.","ipa":"ạnːa vịve in svịʦːera, ma non i swɔ̣j ʤenitọri."},{"n":794,"zh":"你今早吃了早餐，但我没吃。","en":"You had breakfast this morning, but I didn't.","it":"Tu hai fatto colazione stamattina, però io no.","ipa":"tu ạj fạtːo kolaʦjọne stamatːịna, perɔ̣ ịo nɔ."},{"n":795,"zh":"我昨晚没出去，但我的朋友们出去了。","en":"I didn't go out last night, but my friends did.","it":"Non sono uscito ieri sera, i miei amici invece sì.","ipa":"non sọno uʃịto jẹri sẹra, i mjɛ̣j amịʧ‿ invẹʧe sị."},{"n":796,"zh":"我喜欢运动，但我的妹妹不喜欢。","en":"I like sports, but my sister doesn't.","it":"Mi piacciono gli sport, a mia sorella, al contrario, non piacciono.","ipa":"mi pjạtʧono ʎːi spɔrt, a mịa sorɛ̣lːa, al kontrạrjo, non pjạtʧono."},{"n":797,"zh":"我不吃肉，但汤姆吃。","en":"I don't eat meat, but Tom does.","it":"Io non mangio carne, Tom sì.","ipa":"ịo non mạɲʤo kạrne, tɔm sị."},{"n":798,"zh":"我是日本人，但我的丈夫不是。","en":"I'm Japanese, but my husband isn't.","it":"Io sono giapponese, ma non mio marito.","ipa":"ịo sọno ʤapːonẹze, ma non mịo marịto."},{"n":799,"zh":"我没去过墨西哥，但佐伊去过。","en":"I haven't been to Mexico, but Zoe has.","it":"Non sono stato in Messico, mentre Zoe ci è stata.","ipa":"non sọno stạto in mɛ̣sːiko, mɛ̣ntre ʦoɛ ʧi ɛ̣ stạta."},{"n":800,"zh":"你累了吗？——我之前累了，但现在不累了。","en":"Are you tired? — I was earlier, but I'm not now.","it":"Sei stanco? — Lo ero prima, adesso no.","ipa":"sɛ̣j stạŋko? — lo ẹro prịma, adɛ̣sːo nɔ."}]},{"lesson":9,"range":[801,900],"items":[{"n":801,"zh":"法比安今天很开心，但昨天不是。","en":"Fabian's happy today, but he wasn't yesterday.","it":"Oggi Fabiano è felice, però non lo era ieri.","ipa":"ɔ̣dʤi fabjạno ɛ̣ felịʧe, perɔ̣ non lo ẹra jẹri."},{"n":802,"zh":"商店还没开门，但博物馆已经开了。","en":"The stores aren't open yet, but the museum is.","it":"I negozi non sono ancora aperti, ma il museo sì.","ipa":"i neɡɔ̣ʦi non sọno aŋkọra apɛ̣rti, ma il muzẹo sị."},{"n":803,"zh":"我没有望远镜，但我知道有人有。","en":"I don't have a telescope, but I know somebody who does.","it":"Non ho un telescopio, però conosco qualcuno che ce l'ha.","ipa":"non ɔ un teleskɔ̣pjo, perɔ̣ konọsko kwalkụno ke ʧe la."},{"n":804,"zh":"我想帮你，但很抱歉我做不到。","en":"I would like to help you, but I'm sorry I can't.","it":"Mi piacerebbe aiutarti, ma, mi dispiace, non posso.","ipa":"mi pjaʧerɛ̣bːe ajutạrti, ma, mi dispjạʧe, non pɔ̣sːo."},{"n":805,"zh":"我通常不开车上班，但昨天开了。","en":"I don't usually drive to work, but I did yesterday.","it":"Di solito non vado al lavoro in macchina, però ieri l'ho fatto.","ipa":"di sɔ̣lito non vạdo al lavọro in mạkːina, perɔ̣ jẹri lɔ fạtːo."},{"n":806,"zh":"你去过秘鲁吗？——没，但伊夫琳去过。她去年去那里度假了。","en":"Have you ever been to Peru? — No, but Eveline has. She went there on vacation last year.","it":"Sei mai stato in Perù? — No, ma Evelina sì. Ci è andata in vacanza l'anno scorso.","ipa":"sɛ̣j mạj stạto in perụ? — nɔ, ma evelịna sị. ʧi ɛ̣ andạta in vakạnʦa lạnːo skọrso."},{"n":807,"zh":"你和法usto经常看电视吗？——我看了，但他没看。","en":"Do you and Fausto watch TV a lot? — I do, but he doesn't.","it":"Tu e Fausto guardate molta televisione? — Io sì, lui invece no.","ipa":"tu e faụsto ɡwardạte mọlta televizjọne? — ịo sị, lụj invẹʧe nɔ."},{"n":808,"zh":"我被邀请去格哈德的婚礼了，但伊维塔没被邀请。","en":"I've been invited to Gerhard's wedding, but Evita hasn't.","it":"Sono stato invitato al matrimonio di Gerardo, mentre Evita no.","ipa":"sọno stạto invitạto al matrimɔ̣njo di ʤerạrdo, mɛ̣ntre ẹvita nɔ."},{"n":809,"zh":"你认为英格丽会通过驾驶考试吗？——是的，我肯定她会。","en":"Do you think Ingrid will pass her driving test? — Yes, I'm sure she will.","it":"Pensi che Ingrid supererà il suo esame di guida? — Sì, sono sicura che lo passerà.","ipa":"pẹnsi ke ịnɡrid supererạ il sụo ezạme di ɡwịda? — sị, sọno sikụra ke lo pasːerạ."},{"n":810,"zh":"你今晚出去吗？——可能吧，我不确定。","en":"Are you going out tonight? — I might. I don't know for sure.","it":"Uscirai stasera? — Può darsi. Non ne sono sicuro (♀sicura).","ipa":"uʃirạj stasẹra? — pwɔ̣ dạrsi. non ne sọno sikụro (♀sikụra)."},{"n":811,"zh":"你是巴西人吗？——不是。","en":"Are you Brazilian? — No, I'm not.","it":"Sei brasiliano (♀brasiliana)? — No, non sono brasiliano (♀brasiliana).","ipa":"sɛ̣j braziljạno (♀braziljạna)? — nɔ, non sọno braziljạno (♀braziljạna)."},{"n":812,"zh":"你有车吗？——没有。","en":"Do you have a car? — No, I don't.","it":"Possiedi un'autovettura? — No, non ce l'ho.","ipa":"posːjẹdi unawtovetːụra? — nɔ, non ʧe lɔ."},{"n":813,"zh":"你感觉好吗？——是的，我感觉很好。","en":"Do you feel okay? — Yes, I do.","it":"Ti senti bene? — Sì, mi sento bene.","ipa":"ti sɛ̣nti bẹne? — sị, mi sɛ̣nto bẹne."},{"n":814,"zh":"下雪了吗？——没有，没下。","en":"Is it snowing? — No, it isn't.","it":"Nevica? — No, non sta nevicando.","ipa":"nẹvika? — nɔ, non sta nevikạndo."},{"n":815,"zh":"你饿了吗？——是的，我饿了。","en":"Are you hungry? — Yes, I am.","it":"Hai fame? — Sì, ho fame.","ipa":"ạj fạme? — sị, ɔ fạme."},{"n":816,"zh":"你喜欢古典音乐吗？——是的，我喜欢。","en":"Do you like classical music? — Yes, I do.","it":"Ti piace la musica classica? — Sì, mi piace.","ipa":"ti pjạʧe la mụzika klạsːika? — sị, mi pjạʧe."},{"n":817,"zh":"你明天会在迈阿密吗？——不会。","en":"Will you be in Miami tomorrow? — No, I won't.","it":"Domani sarai a Miami? — No, non sarò lì.","ipa":"domạni sarạj a mjạmi? — nɔ, non sarɔ̣ lị."},{"n":818,"zh":"你以前打断过手臂吗？——是的，我打断过。","en":"Have you ever broken your arm? — Yes, I have.","it":"Ti sei mai rotto un braccio? — Sì, me lo sono rotto.","ipa":"ti sɛ̣j mạj rọtːo un brạtʧo? — sị, mɛ lo sọno rọtːo."},{"n":819,"zh":"你昨天买了什么吗？——是的，我买了。","en":"Did you buy anything yesterday? — Yes, I did.","it":"Hai comprato qualcosa ieri? — Sì, ho comprato qualcosa.","ipa":"ạj komprạto kwalkɔ̣za jẹri? — sị, ɔ komprạto kwalkɔ̣za."},{"n":820,"zh":"你凌晨三点（3:00）在睡觉吗？——是的，我在睡觉。","en":"Were you asleep at three am (3:00)? — Yes, I was.","it":"Stavi dormendo alle tre (3:00) del mattino? — Sì, dormivo.","ipa":"stạvi dormɛ̣ndo ạlːe trɛ (3:00) dɛl matːịno? — sị, dormịvo."},{"n":821,"zh":"你迟到了。——我吗？抱歉。","en":"You're late. — I am? Sorry.","it":"Sei in ritardo. — Davvero [sono in ritardo]? Mi dispiace.","ipa":"sɛ̣j in ritạrdo. — davːẹro [sọno in ritạrdo]? mi dispjạʧe."},{"n":822,"zh":"我上周生病了。——你吗？我不知道。","en":"I was sick last week. — You were? I didn't know that.","it":"Settimana scorsa ero malato. — Eri malato? Non lo sapevo.","ipa":"setːimạna skọrsa ẹro malạto. — ẹri malạto? non lo sapẹvo."},{"n":823,"zh":"又下雨了。——是吗？十分钟前还晴朗呢。","en":"It's raining again. — It is? It was sunny ten (10) minutes ago.","it":"Ricomincia a piovere. — Davvero sta piovendo di nuovo? Dieci (10:00) minuti fa c'era il sole.","ipa":"rikomịɲʧ‿ a pjɔ̣vere. — davːẹro sta pjovɛ̣ndo di nwɔ̣vo? djẹʧi (10:00) minụti fa ʧẹra il sọle."},{"n":824,"zh":"有你的留言。——有吗？在哪里？","en":"There's a message for you. — There is? Where is it?","it":"C'è un messaggio per te? — Sì? Dov'è?","ipa":"ʧɛ̣ un mesːạdʤo pɛr tɛ? — sị? dovɛ̣?"},{"n":825,"zh":"乔治尼奥不会开车。——不会吗？我不知道。","en":"Giovanni can't drive. — He can't? I didn't know that.","it":"Giovanni non sa guidare. — No? Non lo sapevo.","ipa":"ʤovạnːi non sa ɡwidạre. nɔ? non lo sapẹvo."},{"n":826,"zh":"我不饿。——你不饿？我饿了。","en":"I'm not hungry. — You're not? I am.","it":"Non ho fame. — Non hai fame? Io sì.","ipa":"non ɔ fạme. — non ạj fạme? ịo sị."},{"n":827,"zh":"艾米莉亚今天没上班。——没吗？她生病了吗？","en":"Emilia isn't at work today. — She isn't? Is she sick?","it":"Emilia non è al lavoro oggi. — No? È ammalata?","ipa":"emịlja non ɛ̣ al lavọro ɔ̣dʤi. — nɔ? ɛ̣ amːalạta?"},{"n":828,"zh":"我会说四种语言。——你会？哪四种？","en":"I speak four (4) languages. — You do? Which ones?","it":"Parlo quattro (4) lingue. — Sul serio? Quali?","ipa":"pạrlo kwạtːro (4) lịŋɡwe. — sul sẹrjo? kwạli?"},{"n":829,"zh":"卢卡不吃肉。——不吃？他吃鱼吗？","en":"Luka doesn't eat meat. — He doesn't? Does he eat fish?","it":"Luca non mangia [la] carne. — Non la mangia? E il pesce, lo mangia?","ipa":"lụka non mạɲʤa [la] kạrne. — non la mạɲʤa? e il pẹʃe, lo mạɲʤa?"},{"n":830,"zh":"纳迪亚上周结婚了。——真的吗？","en":"Nadya got married last week. — She did? Really?","it":"Nadia si è sposata settimana scorsa. — Si è sposata? Davvero?","ipa":"nạdja si ɛ̣ spozạta setːimạna skọrsa. — si ɛ̣ spozạta? davːẹro?"},{"n":831,"zh":"我买了一辆新车。——哦，你买了？","en":"I've bought a new car. — Oh, you have?","it":"Ho comprato la macchina nuova. — Oh, veramente [l'hai comprata]?","ipa":"ɔ komprạto la mạkːina nwɔ̣va. — o, veramɛ̣nte [lạj komprạta]?"},{"n":832,"zh":"我在写一本书。——你在写？关于什么的？","en":"I'm writing a book. — You are? What about?","it":"Sto scrivendo un libro. — Sul serio? Di cosa parla?","ipa":"stɔ skrivɛ̣ndo un lịbro. — sul sẹrjo? di kɔ̣za pạrla?"},{"n":833,"zh":"我不喜欢德米特里。——你不喜欢？为什么？","en":"I don't like Dmitry. — You don't? Why not?","it":"Non mi piace Dmitry. — Non ti piace? Perché no?","ipa":"non mi pjạʧe (…). — non ti pjạʧe? perkɛ̣ nɔ?"},{"n":834,"zh":"今天天气不错，不是吗？——是的，太完美了。","en":"It's a nice day, isn't it? — Yes, it's perfect.","it":"È una bella giornata, non è vero? — Sì, è perfetta.","ipa":"ɛ̣ ụna bɛ̣lːa ʤornạta, non ɛ̣ vẹro? — sị, ɛ̣ perfɛ̣tːa."},{"n":835,"zh":"圣托住米兰，不是吗？——是的，没错。","en":"Santo lives in Milan, doesn't he? — Yes, that's right.","it":"Santo vive a Milano, vero? — Sì, esatto.","ipa":"sạnto vịve a milạno, vẹro? — sị, ezạtːo."},{"n":836,"zh":"你关窗户了，不是吗？——是的，我想是的。","en":"You closed the window, didn't you? — Yes, I think so.","it":"Hai chiuso la finestra, no? — Sì, penso di sì.","ipa":"ạj kiụzo la finɛ̣stra, nɔ? — sị, pẹnso di sị."},{"n":837,"zh":"那双鞋很好看，不是吗？——是的，很漂亮。","en":"Those shoes are nice, aren't they? — Yes, very nice.","it":"Quelle scarpe sono carine, o no? — Sì, sono molto carine.","ipa":"kwɛ̣lːe skạrpe sọno karịne, o nɔ? — sị, sọno mọlto karịne."},{"n":838,"zh":"马尔塔很快就会来，不是吗？——是的，可能吧。","en":"Marta will be here soon, won't she? — Yes, probably.","it":"Marta sarà presto qui, giusto? — Sì, probabilmente.","ipa":"mạrta sarạ prɛ̣sto kwị, ʤụsto? — sị, probabilmɛ̣nte."},{"n":839,"zh":"那不是你的车，是吗？——不是，是我妈妈的。","en":"That isn't your car, is it? — No, it's my mother's.","it":"Quella non è la tua macchina, vero? — No, è di mia madre.","ipa":"kwɛ̣lːa non ɛ̣ la tụa mạkːina, vẹro? — nɔ, ɛ̣ di mịa mạdre."},{"n":840,"zh":"你还没见过我妈妈，是吗？——没有，我没见过。","en":"You haven't met my mother, have you? — No, I haven't.","it":"Non hai incontrato mia madre, giusto? — No, non l'ho incontrata.","ipa":"non ạj iŋkontrạto mịa mạdre, ʤụsto? — nɔ, non lɔ iŋkontrạta."},{"n":841,"zh":"克拉拉很少出门，是吧？——不，她不常出门。","en":"Clara doesn't go out much, does she? — No, she doesn't.","it":"Clara non esce molto, o sì? — No, non esce molto.","ipa":"klạra non ẹʃe mọlto, o sị? — nɔ, non ẹʃe mọlto."},{"n":842,"zh":"你不会迟到吧？——不会，我从不迟到。","en":"You won't be late, will you? — No, I'm never late.","it":"Non sarai in ritardo, vero? — No, non sono mai in ritardo.","ipa":"non sarạj in ritạrdo, vẹro? — nɔ, non sọno mạj in ritạrdo."},{"n":843,"zh":"我在银行工作。——真的吗？我也在银行工作。","en":"I work in a bank. — You do? I work in a bank, too.","it":"Lavoro in banca. — Davvero? Anch'io lavoro in banca.","ipa":"lavọro in bạŋka. — davːẹro? aŋkịo lavọro in bạŋka."},{"n":844,"zh":"我昨天没去上班。——是吗？你生病了吗？","en":"I didn't go to work yesterday. — You didn't? Were you sick?","it":"Non sono andato al lavoro ieri. — Non ci sei andato? Eri ammalato?","ipa":"non sọno andạto al lavọro jẹri. — non ʧi sɛ̣j andạto? ẹri amːalạto?"},{"n":845,"zh":"丹尼斯不喜欢我。——是吗？为什么？","en":"Dennis doesn't like me. — He doesn't? Why not?","it":"Non piaccio a Dennis. — Non gli piaci? Perché no?","ipa":"non pjạtʧo a dɛ̣nːis. — non ʎːi pjạʧi? perkɛ̣ nɔ?"},{"n":846,"zh":"你看起来很累。——是吗？我感觉很好。","en":"You look tired. — I do? I feel fine.","it":"Hai l'aria stanca. — Sì? Mi sento bene.","ipa":"ạj lạrja stạŋka. — sị? mi sɛ̣nto bẹne."},{"n":847,"zh":"莉拉昨晚给我打电话了。——是吗？她说了什么？","en":"Lara called me last night. — She did? What did she say?","it":"Lara mi ha chiamato ieri sera. — Ti ha chiamato (♀chiamata)? E che cosa ha detto?","ipa":"lạra mi a kjamạto jẹri sẹra. — ti a kjamạto (♀kjamạta)? e ke kɔ̣z‿ a dɛ̣tːo?"},{"n":848,"zh":"我买了一辆新车。——真的吗？是什么型号的？","en":"I've bought a new car. — You have? What kind is it?","it":"Ho comprato una macchina nuova. — [Hai comprato] una macchina nuova? Che modello è?","ipa":"ɔ komprạto ụna mạkːina nwɔ̣va. — [ạj komprạto] ụna mạkːina nwɔ̣va? ke modɛ̣lːo ɛ̣?"},{"n":849,"zh":"阿尔伯特不吃肉。——是吗？他吃鸡蛋吗？","en":"Albert doesn't eat meat. — He doesn't? Does he eat eggs?","it":"Alberto non mangia carne. — No? Mangia le uova?","ipa":"albɛ̣rto non mạɲʤa kạrne. — nɔ? mạɲʤa le wɔ̣va?"},{"n":850,"zh":"我丢了钥匙。——是吗？你上次什么时候有？","en":"I've lost my key. — You have? When did you have it last?","it":"Ho perso la [mia] chiave. — Sul serio? Quando l'avevi con te l'ultima volta?","ipa":"ɔ pɛ̣rso la [mịa] kjạve. — sul sẹrjo? kwạndo lavẹvi kon tɛ lultịma vɔ̣lta?"},{"n":851,"zh":"安吉拉不会开车。——是吗？她应该学学。","en":"Angela can't drive. — She can't? She should learn.","it":"Angela non sa guidare. — Non sa guidare? Dovrebbe imparare.","ipa":"ạɲʤela non sa ɡwidạre. — non sa ɡwidạre? dovrɛ̣bːe imparạre."},{"n":852,"zh":"我出生在意大利。——是吗？我不知道这个。","en":"I was born in Italy. — You were? I didn't know that.","it":"Sono nato in Italia. — [Sei nato] in Italia? Non lo sapevo.","ipa":"sọno nạto in itạlja. — [sɛ̣j nạto] in itạlja? non lo sapẹvo."},{"n":853,"zh":"我昨晚没睡好。——是吗？床不舒服吗？","en":"I didn't sleep well last night. — You didn't? Was the bed uncomfortable?","it":"Non ho dormito bene ieri notte. — No? Il letto non era comodo?","ipa":"non ɔ dormịto bẹne jẹri nɔ̣tːe. — nɔ? il lɛ̣tːo non ẹra kɔ̣modo?"},{"n":854,"zh":"今晚电视上有足球比赛。——是吗？你要看吗？","en":"There's a football game on TV tonight. — There is? Are you going to watch it?","it":"Stasera danno una partita di calcio alla televisione. — C'è una partita di calcio? La guarderai?","ipa":"stasẹra dạnːo ụna partịta di kạlʧo ạlːa televizjọne. — ʧɛ̣ ụna partịta di kạlʧo? la ɡwarderạj?"},{"n":855,"zh":"我不高兴。——是吗？为什么？","en":"I'm not happy. — You're not? Why not?","it":"Non sono felice. — Non sei felice? Perché no?","ipa":"non sọno felịʧe. — non sɛ̣j felịʧe? perkɛ̣ nɔ?"},{"n":856,"zh":"我上周看到了卡利德。——是吗？他怎么样？","en":"I saw Khalid last week. — You did? How is he?","it":"Ho visto Khalid settimana scorsa. — L'hai visto? Come sta?","ipa":"ɔ vịsto kạlid setːimạna skọrsa. — lạj vịsto? kọme sta?"},{"n":857,"zh":"萨科拉在工厂工作。——是吗？什么类型的工厂？","en":"Shakira works in a factory. — She does? What kind of factory?","it":"Shakira lavora in fabbrica. — [Lavora] in fabbrica? Di che tipo?","ipa":"(…) lavọra in fạbːrika. — [lavọra] in fạbːrika? di ke tịpo?"},{"n":858,"zh":"我下周不会在这里。——是吗？你会在哪里？","en":"I won't be here next week. — You won't? Where will you be?","it":"Settimana prossima, non ci sarò. — Non ci sarai? Dove sarai?","ipa":"setːimạna prɔ̣sːima, non ʧi sarɔ̣. — non ʧi sarạj? dọve sarạj?"},{"n":859,"zh":"表不走了。——是吗？昨天还走得呢。","en":"The clock isn't working. — It isn't? It was working yesterday.","it":"L'orologio non funziona. — Non funziona? Ieri funzionava.","ipa":"lorolɔ̣ʤo non funʦjọna. — non funʦjọna? jẹri funʦjonạva."},{"n":860,"zh":"今天天气真好，不是吗？——是的，很美。","en":"It's a nice day, isn't it? — Yes, it's beautiful.","it":"È una bella giornata, non è vero? — Sì, è stupenda.","ipa":"ɛ̣ ụna bɛ̣lːa ʤornạta, non ɛ̣ vẹro? — sị, ɛ̣ stupɛ̣nda."},{"n":861,"zh":"这些花真漂亮，不是吗？——是的，是什么花？","en":"These flowers are nice, aren't they? — Yes, what kind are they?","it":"Questi fiori sono belli, vero? — Sì, che tipo di fiori sono?","ipa":"kwɛ̣sti fjọri sọno bɛ̣lːi, vẹro? — sị, ke tịpo di fjọri sọno?"},{"n":862,"zh":"伯纳德参加了派对，不是吗？——是的，但我没跟他说过话。","en":"Bernard was at the party, wasn't he? — Yes, but I didn't speak to him.","it":"Bernardo era alla festa, giusto? — Sì, ma non ci ho parlato.","ipa":"bernạrdo ẹra ạlːa fɛ̣sta, ʤụsto? — sị, ma non ʧi ɔ parlạto."},{"n":863,"zh":"你去过巴西，对吧？——是的，好多次了。","en":"You've been to Brazil, haven't you? — Yes, many times.","it":"Sei stato in Brasile, è corretto? — Sì, molte volte.","ipa":"sɛ̣j stạto in brazịle, ɛ̣ korːɛ̣tːo? — sị, mọlte vɔ̣lte."},{"n":864,"zh":"你会说中文，对吧？——是的，但不太好。","en":"You speak Chinese, don't you? — Yes, but not very well.","it":"Parli il cinese, no? — Sì, ma non molto bene.","ipa":"pạrl‿ il ʧinẹze, nɔ? — sị, ma non mọlto bẹne."},{"n":865,"zh":"卡罗琳看起来很累，不是吗？——是的，她工作很努力。","en":"Caroline looks tired, doesn't she? — Yes, she works very hard.","it":"Carolina ha l'aria stanca, non è vero? — Sì, lavora davvero sodo.","ipa":"karolịn‿ a lạrja stạŋka, non ɛ̣ vẹro? — sị, lavọra davːẹro sɔ̣do."},{"n":866,"zh":"你会帮我的，对吧？——当然会。","en":"You'll help me, won't you? — Yes, of course I will.","it":"Mi aiuterai, vero? — Sì, certo.","ipa":"mi ajutẹraj, vẹro? — sị, ʧɛ̣rto."},{"n":867,"zh":"你还没吃饭吧？——没有，我不饿。","en":"You haven't eaten yet, have you? — No, I'm not hungry.","it":"Non hai ancora mangiato, corretto? — No, non ho fame.","ipa":"non ạj aŋkọra maɲʤạto, korːɛ̣tːo? — nɔ, non ɔ fạme."},{"n":868,"zh":"你不累吧？——不，我感觉很好。","en":"You aren't tired, are you? — No, I feel fine.","it":"Non sei stanco, vero? — No, mi sento bene.","ipa":"non sɛ̣j stạŋko, vẹro? — nɔ, mi sɛ̣nto bẹne."},{"n":869,"zh":"伊戈尔是个很好的人，不是吗？——是的，大家都喜欢他。","en":"Igor's a very nice person, isn't he? — Yes, everybody likes him.","it":"Igor è davvero una bella persona, no? — Sì, piace a tutti.","ipa":"ịɡor ɛ̣ davːẹro ụna bɛ̣lːa persọna, nɔ? — sị, pjạʧe a tụtːi."},{"n":870,"zh":"你会弹钢琴，对吧？——是的，但我不太擅长。","en":"You can play the piano, can't you? — Yes, but I'm not very good.","it":"Sai suonare il pianoforte, vero? — Sì, ma non sono molto bravo.","ipa":"sạj swonạre il pjanofɔ̣rte, vẹro? — sị, ma non sọno mọlto brạvo."},{"n":871,"zh":"你不认识拉里萨的妹妹，对吧？——不，我从来没见过她。","en":"You don't know Larisa's sister, do you? — No, I've never met her.","it":"Non conosci la sorella di Larisa, giusto? — No, non l'ho mai incontrata.","ipa":"non konọʃi la sorɛ̣lːa di larịza, ʤụsto? — nɔ, non lɔ mạj iŋkontrạta."},{"n":872,"zh":"克劳德上了大学，不是吗？——是的，他学心理学。","en":"Claude went to college, didn't he? — Yes, he studied psychology.","it":"Claudio è andato all'università, corretto? — Sì, ha studiato psicologia.","ipa":"klạwdjo ɛ̣ andạto alːuniversitạ, korːɛ̣tːo? — sị, a studjạto psikoloʤịa."},{"n":873,"zh":"这部电影不太好，不是吗？——不，太糟糕了。","en":"The movie wasn't very good, was it? — No, it was terrible.","it":"Il film non era particolarmente bello, o no? — No, era terribile.","ipa":"il film non ẹra partikolarmɛ̣nte bɛ̣lːo, o nɔ? — nɔ, ẹra terːịbile."},{"n":874,"zh":"夏洛特住在你附近，对吧？——是的，就隔几个街区。","en":"Charlotte lives near you, doesn't she? — Yes, just a few blocks away.","it":"Carlotta vive vicino a te, vero? — Sì, giusto qualche isolato più in là.","ipa":"karlɔ̣tːa vịve viʧịno a tɛ, vẹro? — sị, ʤụsto kwạlke izolạto piụ in lạ."},{"n":875,"zh":"你不会告诉任何人我说的，对吧？——当然不会。","en":"You won't tell anybody what I said, will you? — No, of course not.","it":"Non dirai a nessuno quello che ti ho detto, non è vero? — No, ovviamente no.","ipa":"non dirạj a nesːụno kwɛ̣lːo ke ti ɔ dɛ̣tːo, non ɛ̣ vẹro? — nɔ, ovːjamɛ̣nte nɔ."},{"n":876,"zh":"戴安娜工作非常努力。据说她一天工作16个小时。","en":"Diane works very hard. It's said that she works sixteen (16) hours a day.","it":"Diana lavora davvero sodo. Si dice che lavori sedici (16) ore al giorno.","ipa":"djạna lavọra davːẹro sɔ̣do. si dịʧe ke lavọri sẹdiʧi (16) ọre al ʤọrno."},{"n":877,"zh":"警察正在寻找一个失踪男孩。据说他最后一次被看到是在回家的路上。","en":"The police are looking for a missing boy. It's believed that he was last seen walking home.","it":"La polizia sta cercando un bambino scomparso. Si ritiene che sia stato visto per l'ultima volta mentre camminava verso casa.","ipa":"la poliʦịa sta ʧerkạndo un bambịno skompạrso. si ritjẹne ke sịa stạto vịsto pɛr lultịma vɔ̣lta mɛ̣ntre kamːinạva vɛ̣rso kạza."},{"n":878,"zh":"罢工是从三周前开始的。预计很快就会结束。","en":"The strike started three (3) weeks ago. It's expected that it'll end soon.","it":"Lo sciopero è iniziato tre settimane fa. Si prevede che finirà presto.","ipa":"lo ʃɔ̣pero ɛ̣ iniʦjạto trɛ setːimạne fa. si prevẹde ke finirạ prɛ̣sto."},{"n":879,"zh":"我的 一个朋友被逮捕了。据说他打了警察。","en":"A friend of mine has been arrested. It's alleged that he hit a police officer.","it":"Un mio amico è stato arrestato. Si presume che abbia colpito un ufficiale della polizia.","ipa":"un mịo amịko ɛ̣ stạto arːestạto. si prezụme ke ạbːja kolpịto un ufːiʧạle dɛ̣lːa poliʦịa."},{"n":880,"zh":"报道称，爆炸中有两个人受伤。","en":"It's reported that two (2) people were injured in the explosion.","it":"Hanno riferito che due (2) persone si sono ferite durante l'esplosione.","ipa":"ạnːo riferịto ke dụe (2) persọne si sọno ferịte durạnte lesplozjọne."},{"n":881,"zh":"我们去看那部电影吧，听说不错。","en":"Let's go and see that movie. It's supposed to be good.","it":"Andiamo a vedere quel film. Dovrebbe essere un bel film.","ipa":"andjạmo a vedẹre kwɛ̣l film. dovrɛ̣bː‿ ɛ̣sːere un bɛl film."},{"n":882,"zh":"据说艾米尔打了警察，但我不信。","en":"Emil is supposed to have hit a police officer, but I don't believe it.","it":"A quanto pare Emilio avrebbe colpito l'ufficiale di polizia, ma io non ci credo.","ipa":"a kwạnto pạre ẹmiljo avrɛ̣bːe kolpịto lufːiʧạle di poliʦịa, ma ịo non ʧi krẹdo."},{"n":883,"zh":"计划应该是保密的，但好像每个人都知道。","en":"The plan is supposed to be a secret, but everybody seems to know about it.","it":"Il programma dovrebbe essere un segreto, ma tutti sembrano esserne a conoscenza.","ipa":"il proɡrạmːa dovrɛ̣bː‿ ɛ̣sːere un seɡrẹto, ma tụtːi sẹmbrano ɛ̣sːerne a konoʃẹnʦa."},{"n":884,"zh":"你在工作做什么？你该去度假了。","en":"What are you doing at work? You're supposed to be on vacation.","it":"Cosa stai facendo al lavoro? Dovresti essere in vacanza.","ipa":"kɔ̣za stạj faʧɛ̣ndo al lavọro? dovrɛ̣sti ɛ̣sːere in vakạnʦa."},{"n":885,"zh":"斯维特兰娜昨晚应该给我打电话，但她没打。","en":"Svetlana was supposed to call me last night, but she didn't.","it":"Svetlana avrebbe dovuto chiamarmi ieri sera, ma non lo ha fatto.","ipa":"(…) avrɛ̣bːe dovụto kjamạrmi jẹri sẹra, ma non lo a fạtːo."},{"n":886,"zh":"我们的客人原定七点半到（7:30），但他们迟到了。","en":"Our guests were supposed to arrive at seven thirty (7:30), but they were late.","it":"I nostri ospiti sarebbero dovuti arrivare alle sette (7:30) e mezza, però erano in ritardo.","ipa":"i nɔ̣stri ɔ̣spiti sarɛ̣bːero dovụti arːivạre ạlːe sɛ̣tː‿ e mɛ̣ʣa (7:30), perɔ̣ ẹrano in ritạrdo."},{"n":887,"zh":"我最好快点。我十分钟后要见马克斯姆。","en":"I'd better hurry. I'm supposed to meet Maksim in ten (10) minutes.","it":"È meglio che mi sbrighi. Devo incontrarmi con Maksim fra dieci (10) minuti.","ipa":"ɛ̣ mẹʎːjo ke mi zbrịɡi. dẹvo iŋkontrạrmi kon maksịm fra djẹʧi (10) minụti."},{"n":888,"zh":"你不该把车停在这里。这里只限私人停车。","en":"You're not supposed to park your car here. It's private parking only.","it":"Non dovresti parcheggiare qui la tua vettura. È un parcheggio privato.","ipa":"non dovrɛ̣sti parkedʤạre kwị la tụa vetːụra. ɛ̣ un parkẹdʤo privạto."},{"n":889,"zh":"吉尔达手术后感觉好多了，但他还是不应该做重活。","en":"Gerard is feeling much better after his operation, but he's still not supposed to do any heavy lifting.","it":"Gerardo si sente molto meglio dopo l'operazione, tuttavia non dovrebbe ancora fare sforzi.","ipa":"ʤerạrdo si sɛ̣nte mọlto mẹʎːjo dɔ̣po loperaʦjọne, tutːavịa non dovrɛ̣bːe aŋkọra fạre sfọrʦi."},{"n":890,"zh":"这件外套很脏，你应该去洗一下。","en":"This coat is dirty. You should get it cleaned.","it":"Questo cappotto è sporco. Dovresti pulirlo.","ipa":"kwɛ̣sto kapːɔ̣tːo ɛ̣ spọrko. dovrɛ̣sti pulịrlo."},{"n":891,"zh":"我认为你应该把头发剪得很短。","en":"I think you should get your hair cut really short.","it":"Penso che dovresti tagliarti i capelli molto corti.","ipa":"pẹnso ke dovrɛ̣sti taʎːjạrt‿ i kapɛ̣lːi mọlto kọrti."},{"n":892,"zh":"你多久给车做一次保养？","en":"How often do you have your car serviced?","it":"Quanto spesso viene revisionata la tua automobile?","ipa":"kwạnto spɛ̣sːo vjẹne revizjonạta la tụa awtomɔ̣bile?"},{"n":893,"zh":"我不喜欢拍照。","en":"I don't like having my picture taken.","it":"Non mi piace essere fotografato (♀fotografata).","ipa":"non mi pjạʧ‿ ɛ̣sːere fotoɡrafạto (♀fotoɡrafạta)."},{"n":894,"zh":"我们邻居刚在他们家安装了空调。","en":"Our neighbor just got air conditioning installed in their house.","it":"Hanno appena installato l'aria condizionata in casa del nostro vicino.","ipa":"ạnːo apːẹna instalːạto lạrja kondiʦjonạta in kạza dɛl nọstro viʧịno."},{"n":895,"zh":"卡斯珀因为再次超速驾驶，驾照被没收了。","en":"Casper had his license taken away for driving too fast again.","it":"Hanno ritirato di nuovo la patente a Casper per eccesso di velocità.","ipa":"ạnːo ritirạto di nwɔ̣vo la patɛ̣nte a kạsper pɛr etʧɛ̣sːo di veloʧitạ."},{"n":896,"zh":"奥利维亚的护照被偷了。","en":"Olivia got her passport stolen.","it":"Hanno rubato il passaporto a Olivia.","ipa":"ạnːo rubạto il pasːapọrto a olịvja."},{"n":897,"zh":"你有没有经历过航班取消？","en":"Have you ever had your flight canceled?","it":"Ti è mai successo che il tuo volo venga cancellato?","ipa":"ti ɛ̣ mạj sutʧɛ̣sːo ke il tụo vọlo vẹŋɡa kaɲʧelːạto?"},{"n":898,"zh":"我告诉你关于路易莎的事了吗？她上周的包被偷了。","en":"Did I tell you about Luisa? She got her purse stolen last week.","it":"Ti ho detto di Luisa? Le hanno rubato il portafogli la settimana scorsa.","ipa":"ti ɔ dɛ̣tːo di lwịza? le ạnːo rubạto il portafọʎːi la setːimạna skọrsa."},{"n":899,"zh":"胡伯特昨晚打架了，鼻子被打断了。","en":"Hubert was in a fight last night. He got his nose broken.","it":"Hubert è stato coinvolto in una rissa, ieri sera. Si è rotto il naso.","ipa":"ụbert ɛ̣ stạto koinvɔ̣lto in ụna rịsːa, jẹri sẹra. si ɛ̣ rọtːo il nạzo."},{"n":900,"zh":"奥利维亚说她要出去几天，回来后会给我打电话。","en":"Olivia said that she was going away for a few days and would call me when she got back.","it":"Olivia ha detto che sarebbe andata via [per] qualche giorno e che mi avrebbe chiamato quando sarebbe tornata.","ipa":"olịvj‿ a dɛ̣tːo ke sarɛ̣bːe andạta vịa [pɛr] kwạlke ʤọrno e ke mi avrɛ̣bːe kjamạto kwạndo sarɛ̣bːe tornạta."}]},{"lesson":10,"range":[901,1000],"items":[{"n":901,"zh":"今晚莱昂纳多要来参加派对。——真的吗？我还以为你说他不来了。","en":"Leonardo's coming to the party tonight. — He is? I thought you said he wasn't coming.","it":"Leonardo verrà alla festa stasera. — Verrà? Pensavo avessi detto che non sarebbe venuto.","ipa":"leonạrdo verːạ ạlːa fɛ̣sta stasẹra. — verːạ? pensạvo avɛ̣sːi dɛ̣tːo ke non sarɛ̣bːe venụto."},{"n":902,"zh":"我认识很多人。——真的吗？我还以为你一个都不认识呢。","en":"I know lots of people. — You do? I thought you said you didn't know anybody.","it":"Conosco molta gente. — Davvero conosci molta gente? Pensavo avessi detto che non conoscessi nessuno.","ipa":"konọsko mọlta ʤɛ̣nte. — davːẹro konọʃi mọlta ʤɛ̣nte? pensạvo avɛ̣sːi dɛ̣tːo ke non konoʃɛ̣sːi nesːụno."},{"n":903,"zh":"伊莎贝尔下周会来这儿。——真的吗？但你不是说她不会来吗？","en":"Isabelle will be here next week. — She will? But didn't you say she wouldn't be here?","it":"Settimana prossima, Isabella sarà qui. — Sarà qui? Ma non avevi detto che non ci sarebbe stata?","ipa":"setːimạna prɔ̣sːima, izabɛ̣lːa sarạ kwị. — sarạ kwị? ma non avẹvi dɛ̣tːo ke non ʧi sarɛ̣bːe stạta?"},{"n":904,"zh":"我今晚要出去。——真的吗？你不是说你要待在家里的吗？","en":"I'm going out tonight. — You are? But you said you were staying home.","it":"Stasera esco. — Esci? Ma non avevi detto che saresti stato a casa.","ipa":"stasẹra ẹsko. — ẹʃi? ma non avẹvi dɛ̣tːo ke sarɛ̣sti stạto a kạza."},{"n":905,"zh":"我会一点法语。——真的吗？之前你不是说你不会吗？","en":"I can speak a little French. — You can? But earlier you said you couldn't.","it":"Parlo un po' di francese. — Davvero lo parli? Prima, però, avevi detto di non saperlo parlare.","ipa":"pạrlo un pɔ di fraɲʧẹze. — davːẹro lo pạrli? prịma, perɔ̣, avẹvi dɛ̣tːo di non sapẹrlo parlạre."},{"n":906,"zh":"我很久没看过电影了。——真的吗？我还以为你几天前刚看过呢。","en":"I haven't been to the movies in ages. — You haven't? I thought you said you had just gone a few days ago.","it":"Non vado al cinema da secoli. — No? Credevo avessi detto di esserci appena stato (♀stata), qualche giorno fa.","ipa":"non vạdo al ʧịnema da sẹkoli. nɔ? kredẹvo avɛ̣sːi dɛ̣tːo di ɛ̣sːerʧi apːẹna stạto (♀stạta), kwạlke ʤọrno fa."},{"n":907,"zh":"马利克说他醒来感觉不舒服，所以没去上班。","en":"Maalik said he had woken up feeling sick, so he hadn't gone to work.","it":"Maalik ha detto di essersi svegliato con la nausea, perciò non è andato al lavoro.","ipa":"(…) a dɛ̣tːo di ɛ̣sːersi sveʎːjạto kon la nạwzea, perʧɔ̣ non ɛ̣ andạto al lavọro."},{"n":908,"zh":"茉莉说她的新工作挺有趣的。","en":"Jasmine said that her new job is pretty interesting. > Jasmine said that her new job was pretty interesting.","it":"Jasmine ha detto che il suo nuovo lavoro è molto interessante. > Jasmine ha detto che il suo nuovo lavoro era molto interessante.","ipa":"(…) a dɛ̣tːo ke il sụo nwɔ̣vo lavọro ɛ̣ mọlto interesːạnte. > (…) a dɛ̣tːo ke il sụo nwɔ̣vo lavọro ẹra mọlto interesːạnte."},{"n":909,"zh":"她告诉我她明年想去南美洲。","en":"She told me that she wants to go to South America next year. > She told me that she wanted to go to South America next year.","it":"Lei mi ha detto che, l'anno prossimo, vuole andare in Sud America. > Lei mi ha detto che, l'anno prossimo, voleva andare in Sud America.","ipa":"lɛ̣j mi a dɛ̣tːo ke, lạnːo prɔ̣sːimo, vwɔ̣le andạre in sud amẹrika. > lɛ̣j mi a dɛ̣tːo ke, lạnːo prɔ̣sːimo, volẹv‿ andạre in sud amẹrika."},{"n":910,"zh":"医生让我卧床休息几天。","en":"The doctor told me to stay in bed for a few days.","it":"Il dottore mi ha detto di stare a letto per qualche giorno.","ipa":"il dotːọre mi a dɛ̣tːo di stạre a lɛ̣tːo pɛr kwạlke ʤọrno."},{"n":911,"zh":"我告诉卢西安不要大喊。","en":"I told Lucien not to shout.","it":"Ho detto a Luciano di non gridare.","ipa":"ɔ dɛ̣tːo a luʧạno di non ɡridạre."},{"n":912,"zh":"米奇科让我不要告诉任何人发生了什么事。","en":"Michiko asked me not to tell anybody what had happened.","it":"Michiko mi ha chiesto di non dire a nessuno quello che è accaduto.","ipa":"(…) mi a kjɛ̣sto di non dịre a nesːụno kwɛ̣lːo k‿ ɛ̣ akːadụto."},{"n":913,"zh":"野村准备得很慢，所以我让他快点。","en":"Noboru was taking a long time to get ready, so I told him to hurry up.","it":"Noboru ci stava mettendo molto tempo per prepararsi, così gli ho detto di sbrigarsi.","ipa":"nobọru ʧi stạva metːɛ̣ndo mọlto tẹmpo pɛr preparạrsi, kozị ʎːi ɔ dɛ̣tːo di zbriɡạrsi."},{"n":914,"zh":"莉莉安对情况感到紧张，所以我让她放松点，别紧张。","en":"Lilianne was nervous about the situation, so I told her to relax and take it easy.","it":"Liliana era nervosa per la situazione, le ho detto, quindi, di rilassarsi e stare tranquilla.","ipa":"liljạna ẹra nervọza pɛr la sitwaʦjọne, le ɔ dɛ̣tːo, kwịndi, di rilasːạrsi e stạre traŋkwịlːa."},{"n":915,"zh":"海关官员怀疑地看着我，让我打开包。","en":"The customs officer looked at me suspiciously and asked me to open my bag.","it":"Gli agenti alla dogana mi hanno guardato con aria sospetta e mi hanno chiesto di aprire la [mia] borsa.","ipa":"ʎːi aʤɛ̣nti ạlːa doɡạna mi ạnːo ɡwardạto kon ạrja sospɛ̣tːa e mi ạnːo kjɛ̣sto di aprịre la [mịa] bọrsa."},{"n":916,"zh":"你昨晚怎么了？","en":"What happened to you last night?","it":"Cosa ti è successo ieri notte?","ipa":"kɔ̣za ti ɛ̣ sutʧɛ̣sːo jẹri nɔ̣tːe?"},{"n":917,"zh":"有多少人参加了会议？","en":"How many people came to the meeting?","it":"Quante persone sono venute all'incontro?","ipa":"kwạnte persọne sọno venụte alːiŋkọntro?"},{"n":918,"zh":"哪辆公交车去市中心？","en":"Which bus goes downtown?","it":"Quale autobus va in centro [città]?","ipa":"kwạle ạwtobus va in ʧɛ̣ntro [ʧitːạ]?"},{"n":919,"zh":"你想和谁说话？","en":"Who do you want to speak to?","it":"Con chi vuoi parlare?","ipa":"kon ki vwɔ̣j parlạre?"},{"n":920,"zh":"昨天的天气怎么样？","en":"What was the weather like yesterday?","it":"Com'era il tempo ieri?","ipa":"komẹra il tẹmpo jẹri?"},{"n":921,"zh":"你想和谁说话？","en":"To whom do you wish to speak?","it":"A chi desideri parlare?","ipa":"a ki dezịderi parlạre?"},{"n":922,"zh":"我们以前没在哪里见过吗？","en":"Haven't we met somewhere before?","it":"Non ci siamo visti da qualche parte prima d'ora?","ipa":"non ʧi sjạmo vịsti da kwạlke pạrte prịma dọra?"},{"n":923,"zh":"你不想去派对吗？——不，我不想去。","en":"Don't you want to go to the party? — No, I don't want to go.","it":"Non vuoi andare alla festa? — No, non voglio andarci.","ipa":"non vwɔ̣j andạre ạlːa fɛ̣sta? — nɔ, non vɔ̣ʎːjo andạrʧi."},{"n":924,"zh":"我们今晚出去吃饭怎么样？","en":"Why don't we go out for a meal tonight?","it":"Perchè non usciamo a cena stasera?","ipa":"perkɛ̣ non uʃạmo a ʧẹna stasẹra?"},{"n":925,"zh":"昨天尼古拉斯为什么没上班？","en":"Why wasn't Nicholas at work yesterday?","it":"Perchè Nicola non era al lavoro ieri?","ipa":"perkɛ̣ nikɔ̣la non ẹra al lavọro jẹri?"},{"n":926,"zh":"我们今晚见不到米里亚姆了。——为什么？她不来吗？","en":"We won't see Miriam tonight. — Why not? Isn't she coming?","it":"Non vedremo Miriam stasera. — Perché no? Non verrà?","ipa":"non vedrẹmo mịrjam stasẹra. — perkɛ̣ nɔ? non verːạ?"},{"n":927,"zh":"我得借点钱。——为什么？你没有吗？","en":"I'll have to borrow some money. — Why? Don't you have any?","it":"Devo prendere in prestito dei soldi. — Perché? Non ne hai?","ipa":"dẹvo prɛ̣ndere in prɛ̣stito dẹj sɔ̣ldi. — perkɛ̣? non ne ạj?"},{"n":928,"zh":"现在几点了？——你知道现在几点了吗？","en":"What time is it? > Do you know what time it is?","it":"Che ore sono? > Sai che ore sono?","ipa":"ke ọre sọno? > sạj ke ọre sọno?"},{"n":929,"zh":"那些人是谁？——我不知道那些人是谁。","en":"Who are those people? — I don't know who those people are.","it":"Chi sono quelle persone? — Non so chi siano quelle persone.","ipa":"ki sọno kwɛ̣lːe persọne? — non sɔ ki sịano kwɛ̣lːe persọne."},{"n":930,"zh":"我在哪里能找到奥利弗？——你能告诉我我在哪里能找到奥利弗吗？","en":"Where can I find Oliver? > Can you tell me where I can find Oliver?","it":"Dove posso trovare Oliver? > Sai dirmi dove posso trovare Oliver?","ipa":"dọve pɔ̣sːo trovạre ɔ̣liver? > sạj dịrmi dọve pɔ̣sːo trovạre ɔ̣liver?"},{"n":931,"zh":"这要花多少钱？——你知道这要花多少钱吗？","en":"How much will it cost? > Do you have any idea how much it'll cost?","it":"Quanto costerà? > Hai una minima idea di quanto costerà?","ipa":"kwạnto kosterạ? > ạj ụna mịnima idẹa di kwạnto kosterạ?"},{"n":932,"zh":"电影什么时候开始？——你知道电影什么时候开始吗？","en":"What time does the movie begin? > Do you know what time the movie begins?","it":"A che ora inizia il film? > Sai a che ora inizia il film?","ipa":"a ke ọra inịʦja il film? > sạj a ke ọra inịʦja il film?"},{"n":933,"zh":"你是什么意思？——请解释一下你的意思。","en":"What do you mean? > Please explain what you mean.","it":"Che cosa vuoi dire? > Per favore, spiega cosa intendi dire.","ipa":"ke kɔ̣za vwɔ̣j dịre? > pɛr favọre, spjẹɡa kɔ̣za intɛ̣ndi dịre."},{"n":934,"zh":"她为什么提前走了？——我想知道她为什么提前走了。","en":"Why did she leave early? > I wonder why she left early.","it":"Perché è andata via prima? > Mi chiedo perché sia andata via in anticipo.","ipa":"perkɛ̣ ɛ̣ andạta vịa prịma? > mi kjɛ̣do perkɛ̣ sịa andạta vịa in antịʧipo."},{"n":935,"zh":"到机场有多远？——你能告诉我到机场有多远吗？","en":"How far is it to the airport? > Can you tell me how far it is to the airport?","it":"Quanto è lontano l'aeroporto? > Sai dirmi quanto dista l'aeroporto?","ipa":"kwạnto ɛ̣ lontạno laeropɔ̣rto? > sạj dịrmi kwạnto dịsta laeropɔ̣rto?"},{"n":936,"zh":"在这里停车要多少钱？——你能告诉我在这里停车要多少钱吗？","en":"How much does it cost to park here? > Could you tell me how much it costs to park here?","it":"Quanto costa parcheggiare qui? > Potresti dirmi quanto costa parcheggiare qui?","ipa":"kwạnto kɔ̣sta parkedʤạre kwị? > potrɛ̣sti dịrmi kwạnto kɔ̣sta parkedʤạre kwị?"},{"n":937,"zh":"她问我是否愿意出差。","en":"She asked if I was willing to travel.","it":"Lei mi ha chiesto se ero disposto a viaggiare.","ipa":"lɛ̣j mi a kjɛ̣sto s‿ ẹro dispɔ̣sto a vjadʤạre."},{"n":938,"zh":"她想知道我在业余时间做什么。","en":"She wanted to know what I did in my spare time.","it":"Lei voleva sapere che cosa facessi durante il mio tempo libero.","ipa":"lɛ̣j volẹva sapẹre ke kɔ̣za faʧɛ̣sːi durạnte il mịo tẹmpo lịbero."},{"n":939,"zh":"她问我在这份工作干了多久。","en":"She asked how long I had been working at my present job.","it":"Lei mi ha chiesto da quanto tempo stessi svolgendo il mio attuale lavoro.","ipa":"lɛ̣j mi a kjɛ̣sto da kwạnto tẹmpo stɛ̣sːi svolʤɛ̣ndo il mịo atːwạle lavọro."},{"n":940,"zh":"她问我为什么申请这份工作。","en":"She asked why I had applied for the job.","it":"Lei mi ha chiesto perchè avessi fatto domanda per quel lavoro.","ipa":"lɛ̣j mi a kjɛ̣sto perkɛ̣ avɛ̣sːi fạtːo domạnda pɛr kwɛ̣l lavọro."},{"n":941,"zh":"她想知道我会不会说其他语言。","en":"She wanted to know if I could speak another language.","it":"Lei voleva sapere se ero capace di parlare un'altra lingua.","ipa":"lɛ̣j volẹva sapẹre s‿ ẹro kapạʧe di parlạre unạltra lịŋɡwa."},{"n":942,"zh":"她问我有驾照吗？","en":"She asked if I had a driver's license.","it":"Lei mi ha chiesto se avevo la patente [di guida].","ipa":"lɛ̣j mi a kjɛ̣sto se avẹvo la patɛ̣nte [di ɡwịda]."},{"n":943,"zh":"纳塔莉没有车，奥利弗也没有。","en":"Natalie doesn't have a car, and neither does Oliver.","it":"Natalia non ha una macchina e Oliver, neanche.","ipa":"natạlja non a ụna mạkːina e ɔ̣liver, neạŋke."},{"n":944,"zh":"要下雨吗？——我希望不会。","en":"Is it going to rain? — I hope not.","it":"Pioverà? — Spero di no.","ipa":"pjoverạ? — spẹro di nɔ."},{"n":945,"zh":"你觉得雷米会得到这份工作吗？——我想会的。","en":"Do you think Remy will get the job? — I guess so.","it":"Pensi che Remy otterrà il lavoro? — Immagino di sì.","ipa":"pẹnsi ke (…) otːerːạ il lavọro? — imːạʤino di sị."},{"n":946,"zh":"保罗琳结婚了？——我觉得她没结婚。","en":"Is Pauline married? — I don't think she is.","it":"Paulina è sposata? — Penso di no.","ipa":"pawlịna ɛ̣ spozạta? — pẹnso di nɔ."},{"n":947,"zh":"你觉得你很快会涨工资吗？——我希望会。","en":"Do you think you'll get a raise soon? — I hope so.","it":"Pensi che presto riceverai un aumento? — Lo spero.","ipa":"pẹnsi ke prɛ̣sto riʧeverạj un awmɛ̣nto? — lo spẹro."},{"n":948,"zh":"你今晚有空房吗？——恐怕没有。","en":"Do you have a room for tonight? — I'm afraid not.","it":"Hai una stanza per stanotte? — Temo di no.","ipa":"ạj ụna stạnʦa pɛr stạnotːe? — tẹmo di nɔ."},{"n":949,"zh":"你真的要走吗？——恐怕是的。","en":"Do you have to leave already? — I'm afraid so.","it":"Devi già andare? — Ho paura di sì.","ipa":"dẹvi ʤạ andạre? — ɔ paụra di sị."},{"n":950,"zh":"你觉得约翰会参加派对吗？——我希望不会。","en":"Do you think John will be at the party? — I hope not.","it":"Pensi che Giovanni verrà alla festa? — Spero di no.","ipa":"pẹnsi ke ʤovạnːi verːạ ạlːa fɛ̣sta? — spẹro di nɔ."},{"n":951,"zh":"音乐会是在七点半（7:30）吗？——我想是的。","en":"Is the concert at seven thirty (7:30)? — I think so.","it":"Il concerto è alle diciannove e trenta (7:30)? — Penso di sì.","ipa":"il koɲʧɛ̣rto ɛ̣ ạlːe diʧanːɔ̣v‿ e trɛ̣nta (7:30)? — pẹnso di sị."},{"n":952,"zh":"志保明天上班吗？——我想是的。","en":"Is Hitomi working tomorrow? — I suppose so.","it":"Hitomi domani lavora? — Suppongo di sì.","ipa":"itọmi domạni lavọra? — supːọŋɡo di sị."},{"n":953,"zh":"你注意到天空是蓝色的，太阳在照耀。你说：“今天天气真好，不是吗？”","en":"You notice the sky is blue and the sun is shining. You say, \"It's a beautiful day isn't it?\"","it":"Noti che il cielo è blu e il sole splende. Dici: «È una splendida giornata, non è vero?»","ipa":"nɔ̣ti ke il ʧɛ̣lo ɛ̣ blu e il sọle splɛ̣nde. dịʧi: «ɛ̣ ụna splɛ̣ndida ʤornạta, non ɛ̣ vẹro?»"},{"n":954,"zh":"你注意到餐厅的价格很高。你说：“这里很贵，不是吗？”","en":"You notice the restaurant prices are very high. You say, \"It's pretty expensive, isn't it?\"","it":"Ti accorgi che i prezzi del ristorante sono molto alti. Dici, «È davvero caro, non trovi?»","ipa":"ti akːɔ̣rʤi ke i prɛ̣ʦːi dɛl ristorạnte sọno mọlto ạlti. dịʧi, «ɛ̣ davːẹro kạro, non trɔ̣vi?»"},{"n":955,"zh":"你真的很喜欢你的培训课程。你说：“这个课程很棒，不是吗？”","en":"You really enjoyed your training course. You say, \"The course was great, wasn't it?\"","it":"Il corso di formazione ti è proprio piaciuto. Dici, «Il corso è stato favoloso, no?»","ipa":"il kọrso di formaʦjọne ti ɛ̣ prɔ̣prjo pjaʧụto. dịʧi, «il kọrso ɛ̣ stạto favolọzo, nɔ?»"},{"n":956,"zh":"你注意到你朋友的头发比上次短多了。你说：“你剪头发了，不是吗？”","en":"You notice your friend's hair is much shorter than last time. You say, \"You had your hair cut, didn't you?\"","it":"Noti che i capelli del tuo amico sono molto più corti rispetto all'ultima volta. Gli dici, «Ti sei tagliato i capelli, giusto?»","ipa":"nɔ̣ti ke i kapɛ̣lːi dɛl tụo amịko sọno mọlto piụ kọrti rispɛ̣tːo alːụltima vɔ̣lta. ʎːi dịʧi, «ti sɛ̣j taʎːjạto i kapɛ̣lːi, ʤụsto?»"},{"n":957,"zh":"你注意到唱歌的女士声音很好听。你说：“她声音真好，不是吗？”","en":"You notice the woman singing has a nice voice. You say, \"She has a good voice, doesn't she?\"","it":"Ti accorgi che la donna che stava cantando ha una bella voce. Dici, «Lei ha una bella voce, vero?»","ipa":"ti akːɔ̣rʤi ke la dɔ̣nːa ke stạva kantạndo a ụna bɛ̣lːa vọʧe. dịʧi, «lɛ̣j a ụna bɛ̣lːa vọʧe, vẹro?»"},{"n":958,"zh":"你试穿了一件新夹克，但不喜欢。你说：“这件夹克我穿起来不好看，不是吗？”","en":"You're trying on a new jacket and don't like it. You say, \"This doesn't look very good on me, does it?\"","it":"Stai provando una giacca nuova e non ti piace. Dici: «Non mi sta molto bene, o sì?»","ipa":"stạj provạndo ụna ʤạkːa nwɔ̣va e non ti pjạʧe. dịʧi: «non mi sta mọlto bẹne, o sị?»"},{"n":959,"zh":"收银员正把你的杂货装进塑料袋。你说：“打扰一下，你们没有纸袋吗？”","en":"The cashier is putting your groceries in a plastic bag. You say, \"Excuse me, don't you have any paper bags?\"","it":"Il cassiere sta mettendo la tua spesa in una borsa di plastica. Dici: «Scusi, non ha delle borse di carta?»","ipa":"il kasːjẹre sta metːɛ̣ndo la tụa spẹza in ụna bọrsa di plạstika. dịʧi: «skụzi, non a dɛ̣lːe bọrse di kạrta?»"},{"n":960,"zh":"你在找你的钥匙。也许一郎见过它们。你问：“你没有看到我的钥匙，对吧？”","en":"You're looking for your keys. Maybe Ichirou has seen them. You ask, \"You haven't seen my keys, have you?\"","it":"Stai cercando le [tue] chiavi. Forse Ichirou le ha viste. Gli chiedi: «Non hai visto le mie chiavi, vero?»","ipa":"stạj ʧerkạndo le [tụe] kjạvi. fọrse (…) le a vịste. ʎːi kjɛ̣di: «non ạj vịsto le mịe kjạvi, vẹro?»"},{"n":961,"zh":"萨尔热有车，你需要搭车去车站。你问：“你能载我去车站吗？”","en":"Serge has a car and you need a ride to the station. You ask, \"Could you give me a ride to the station?\"","it":"Sergio ha la macchina e hai bisogno di un passaggio alla stazione. Gli chiedi: «Potresti darmi un passaggio alla stazione?»","ipa":"sɛ̣rʤo a la mạkːina e ạj bizọɲːo di un pasːạdʤo ạlːa staʦjọne. ʎːi kjɛ̣di: «potrɛ̣sti dạrmi un pasːạdʤo ạlːa staʦjọne?»"},{"n":962,"zh":"你介意关上门吗？","en":"Would you mind closing the door?","it":"Ti dispiacerebbe chiudere la porta?","ipa":"ti dispjaʧerɛ̣bːe kiụdere la pɔ̣rta?"},{"n":963,"zh":"你介意关灯吗？","en":"Would you mind turning off the lights?","it":"Ti spiace spegnere le luci?","ipa":"ti spjạʧe spẹɲːere le lụʧi?"},{"n":964,"zh":"丽妮建议去看电影。","en":"Renee suggested going to the movies.","it":"Renée ha proposto di andare al cinema.","ipa":"(…) a propɔ̣sto di andạre al ʧịnema."},{"n":965,"zh":"突然大家都停止了说话。一片寂静。","en":"Suddenly everybody stopped talking. There was silence.","it":"Improvvisamente, tutti hanno smesso di parlare. C'era il silenzio totale.","ipa":"improvːizamɛ̣nte, tụtːi ạnːo smɛ̣sːo di parlạre. ʧẹra il silɛ̣nʦjo totạle."},{"n":966,"zh":"我打扫完公寓后就去购物。","en":"I'll do the shopping when I've finished cleaning the apartment.","it":"Farò la spesa quando avrò finito di pulire l'appartamento.","ipa":"farɔ̣ la spẹza kwạndo avrɔ̣ finịto di pulịre lapːartamɛ̣nto."},{"n":967,"zh":"他试图回避回答我的问题。","en":"He tried to avoid answering my question.","it":"Lui ha cercato di evitare di rispondere alla mia domanda.","ipa":"lụj a ʧerkạto di evitạre di rispọndere ạlːa mịa domạnda."},{"n":968,"zh":"你考虑过搬到另一个国家生活吗？——当然，但我不知道要花多少钱。","en":"Have you ever considered going to live in another country? — Sure, but I don't know how much it would cost.","it":"Hai mai preso in considerazione di andare a vivere in un altro paese? — Certamente, ma non so quanto mi costerebbe.","ipa":"ạj mạj prẹzo in konsideraʦjọne di andạre a vịvere in un ạltro paẹze? — ʧertamɛ̣nte, ma non sɔ kwạnto mi kosterɛ̣bːe."},{"n":969,"zh":"我度假时喜欢不用早起。","en":"When I'm on vacation, I enjoy not having to get up early.","it":"Quando sono in vacanza, mi piace non dovermi alzare presto.","ipa":"kwạndo sọno in vakạnʦa, mi pjạʧe non dovẹrmi alʦạre prɛ̣sto."},{"n":970,"zh":"拉什米已经放弃尝试减肥了。","en":"Rashmi has given up trying to lose weight.","it":"Rashmi ha rinunciato a tentare di perdere peso.","ipa":"(…) a rinuɲʧạto a tentạre di pɛ̣rdere pẹzo."},{"n":971,"zh":"尼拉不想退休。他想要继续工作。","en":"Niraj doesn't want to retire. He wants to go on working.","it":"Niraj non vuole andare in pensione. Lui vuole continuare a lavorare.","ipa":"(…) non vwɔ̣le andạre in pensjọne. lụj vwɔ̣le kontinwạre a lavorạre."},{"n":972,"zh":"我说话时你总是打断我。","en":"You keep interrupting when I'm talking.","it":"Continui a interrompermi quando io sto parlando.","ipa":"kontịnwi a interːọmpermi kwạndo ịo stɔ parlạndo."},{"n":973,"zh":"我想象不出西奥骑摩托车的样子。","en":"I can't imagine Theo riding a motorcycle.","it":"Non riesco a immaginarmi Theo che guidi una moto.","ipa":"non rjẹsko a imːaʤinạrmi tẹo ke ɡwịdi ụna mọto."},{"n":974,"zh":"我不介意被等人。","en":"I don't mind being kept waiting.","it":"Non fa niente se qualcuno mi fa aspettare.","ipa":"non fa njɛ̣nte se kwalkụno mi f‿ aspetːạre."},{"n":975,"zh":"他们承认偷了钱。","en":"They admitted to having stolen the money.","it":"Hanno ammesso di avere rubato il denaro.","ipa":"ạnːo amːɛ̣sːo di avẹre rubạto il denạro."},{"n":976,"zh":"我现在后悔我说的话了。","en":"I now regret saying what I said.","it":"Adesso mi pento di aver detto quello che ho detto.","ipa":"adɛ̣sːo mi pɛ̣nto di avẹr dɛ̣tːo kwɛ̣lːo ke ɔ dɛ̣tːo."},{"n":977,"zh":"她否认她偷了钱。","en":"She denied that she had stolen the money.","it":"Lei ha negato di avere rubato i soldi.","ipa":"lɛ̣j a neɡạto di avẹre rubạto i sɔ̣ldi."},{"n":978,"zh":"萨宾建议我们去看电影。","en":"Sabine suggested that we go to the movies.","it":"Sabina ha consigliato di andare al cinema.","ipa":"sabịn‿ a konsiʎːjạto di andạre al ʧịnema."},{"n":979,"zh":"我们应该把今天的出发时间推迟到明天吗？——不，我们应该尽快离开。","en":"Should we postpone leaving today until tomorrow? — No, we should try leaving as soon as possible.","it":"Dovremmo posticipare la partenza di oggi, a domani? — No, dovremmo cercare di partire il più presto possibile.","ipa":"dovrɛ̣mːo postiʧipạre la partẹnʦa di ɔ̣dʤi, a domạni? — nɔ, dovrɛ̣mːo ʧerkạre di partịre il piụ prɛ̣sto posːịbile."},{"n":980,"zh":"我的汽车不是很可靠。它总是出故障。","en":"My car isn't very reliable. It keeps breaking down.","it":"La mia macchina non è molto affidabile. Continua a rompersi.","ipa":"la mịa mạkːina non ɛ̣ mọlto afːidạbile. kontịnw‿ a rọmpersi."},{"n":981,"zh":"非常好笑，我笑得停不下来。","en":"It was very funny. I couldn't stop laughing.","it":"È stato molto divertente. Non riuscivo a smettere di ridere.","ipa":"ɛ̣ stạto mọlto divertɛ̣nte. non riuʃịvo a smɛ̣tːere di rịdere."},{"n":982,"zh":"时间晚了，所以我们决定打车回家。","en":"It was late, so we decided to take a taxi home.","it":"Era tardi, così abbiamo deciso di prendere un taxi per tornare a casa.","ipa":"ẹra tạrdi, kozị abːjạmo deʧịzo di prɛ̣ndere un tạksi pɛr tornạre a kạza."},{"n":983,"zh":"文森特处境困难，所以我答应帮他。","en":"Vincent was in a difficult situation, so I agreed to help him.","it":"Vincenzo si trovava in una situazione difficile, perciò ho accettato di aiutarlo.","ipa":"viɲʧɛ̣nʦo si trovạva in ụna sitwaʦjọne difːịʧile, perʧɔ̣ ɔ atʧetːạto di ajutạrlo."},{"n":984,"zh":"你学开车的时候多大了？","en":"How old were you when you learned to drive?","it":"Quanti anni avevi quando hai imparato a guidare?","ipa":"kwạnti ạnːi avẹvi kwạndo ạj imparạto a ɡwidạre?"},{"n":985,"zh":"瓦莱丽在面试中没有留下好印象。","en":"Valerie failed to make a good impression at the job interview.","it":"Durante il colloquio di lavoro , Valeria non è riuscita a dare una buona impressione di sé.","ipa":"durạnte il kolːɔ̣kwjo di lavọro , valẹrja non ɛ̣ riuʃịt‿ a dạre ụna bwɔ̣na impresːjọne di sɛ̣."},{"n":986,"zh":"因为天气原因，我们决定不去外面。","en":"We decided not to go out because of the weather.","it":"A causa del tempo, abbiamo deciso di non uscire.","ipa":"a kạwza dɛl tẹmpo, abːjạmo deʧịzo di non uʃịre."},{"n":987,"zh":"我承诺不会迟到。","en":"I promised not to be late.","it":"Ho promesso di non ritardare.","ipa":"ɔ promɛ̣sːo di non ritardạre."},{"n":988,"zh":"你想买车吗？——嗯，但我还没下定决心。","en":"Are you thinking of buying a car? — Yeah, but I still haven't made up my mind.","it":"Stai pensando di comprare una macchina nuova? — Sì, ma non ho ancora preso una decisione.","ipa":"stạj pensạndo di komprạre ụna mạkːina nwɔ̣va? — sị, ma non ɔ aŋkọra prẹzo ụna deʧizjọne."},{"n":989,"zh":"他们看起来很有钱。","en":"They seem to have plenty of money.","it":"Sembra che abbiano un sacco di quattrini.","ipa":"sẹmbra ke ạbːjano un sạkːo di kwatːrịni."},{"n":990,"zh":"我喜欢维多利亚，但她好像话太多。","en":"I like Victoria, but I think she tends to talk too much.","it":"Mi piace Vittoria, penso, però, che tenda a parlare troppo.","ipa":"mi pjạʧe vitːɔ̣rja, pẹnso, perɔ̣, ke tɛ̣nd‿ a parlạre trɔ̣pːo."},{"n":991,"zh":"尼古拉伊在街上经过我时假装没看见我。","en":"Nikolai pretended not to see me when he passed me on the street.","it":"Nicola ha fatto finta di non vedermi, quando per strada mi è passato davanti.","ipa":"nikɔ̣l‿ a fạtːo fịnta di non vedẹrmi, kwạndo pɛr strạda mi ɛ̣ pasːạto davạnti."},{"n":992,"zh":"我假装在看报纸。","en":"I pretended to be reading the newspaper.","it":"Ho fatto finta di leggere il giornale.","ipa":"ɔ fạtːo fịnta di lɛ̣dʤere il ʤornạle."},{"n":993,"zh":"你好像瘦了。","en":"You seem to have lost weight.","it":"A quanto sembra, hai perso peso.","ipa":"a kwạnto sẹmbra, ạj pɛ̣rso pẹzo."},{"n":994,"zh":"亚尼克看起来很喜欢他的新工作。","en":"Yannick seems to be enjoying his new job.","it":"Sembra che a Yannick piaccia il suo nuovo lavoro.","ipa":"sẹmbra ke a (…) pjạtʧa il sụo nwɔ̣vo lavọro."},{"n":995,"zh":"我不敢告诉他。","en":"I wouldn't dare tell him.","it":"Non oserei dirglielo.","ipa":"non ozerẹj dịrʎːjelo."},{"n":996,"zh":"谁能教我怎么换这个打印机的墨盒？——当然，我会的。","en":"Can somebody show me how to change the cartridge in this printer? — Sure, I will.","it":"Qualcuno può mostrarmi come cambiare la cartuccia dell'inchiostro in questa stampante? — Certo, te lo mostrerò io.","ipa":"kwalkụno pwɔ̣ mostrạrmi kọme kambjạre la kartụtʧa dɛlːiŋkjɔ̣stro in kwɛ̣sta stampạnte? — ʧɛ̣rto, tɛ lo mostrerɔ̣ ịo."},{"n":997,"zh":"伊冯娜容易忘事。","en":"Yvonne tends to forget things.","it":"Yvonne ha la tendenza a dimenticarsi le cose.","ipa":"(…) a la tendẹnʦ‿ a dimentikạrsi le kɔ̣ze."},{"n":998,"zh":"他们声称已经解决了问题。","en":"They claim to have solved the problem.","it":"Sostengono di avere risolto il problema.","ipa":"sostẹŋɡono di avẹre rizɔ̣lto il problẹma."},{"n":999,"zh":"如果大楼里着火了，你知道该怎么办吗？——不太清楚。","en":"Would you know what to do if there was a fire in the building? — Not really.","it":"Sapresti cosa fare nel caso ci fosse un incendio nell'edificio? — Non esattamente (non proprio).","ipa":"saprɛ̣sti kɔ̣za fạre nɛl kạzo ʧi fɔ̣sːe un iɲʧɛ̣ndjo nɛlːedifịʧo? — non ezatːamɛ̣nte. (non prɔ̣prjo)."},{"n":1000,"zh":"我真的很惊讶，我都不知道该说什么。","en":"I was really astonished. I didn't know what to say.","it":"Ero davvero stupito. Non sapevo cosa dire.","ipa":"ẹro davːẹro stupịto. non sapẹvo kɔ̣za dịre."}]}]};
